window.__D("text/hemshech-ayin-beis/c003",{"p":[[3601330388,"<b>וירצה</b> באלקות, ועי\"ז יהי' חשוכא לנהורא דבחשך דעוה\"ז יהי' גילוי אור ע\"י אותיות התורה, וזהו ויצוק שמן, וזהו פותח את ידיך יודיך יו\"ד דש' הוי' ביו\"ד דש' אד', וז\"ע וירימה מצבה העלאה והמשכה.\nקטז) <b>והנה</b> מכל הנ\"ל מובן דמה שהכלים נק' ספי' ובהירות זהו בבחי' פנימי' הכלים שמגלים את האור כמו שהוא כו', דהנה בחי' חיצוני' הכלים הגם שמגלים את האור וכמשנת\"ל פק\"ה דכל ענין הכלים הוא לגלות דעש\"ז נק' גופין כו', ולא כמו הלבושי' שענינם הוא להסתיר, משא\"כ הכלים ענינם הוא לגלות כו', מ\"מ הרי אופן הגילוי הוא שע\"י שמסתירים על עצמו' ופנימי' האור כו', וכמשנת\"ל פרק הנ\"ל בענין אותי' הדבור שמעלימי' על עצם האור ועי\"ז הם מגלים, וכמו\"כ הוא בבחי' הכלים כו', וזהו שע\"י הכלים דע\"ס הרי המשכת האור בס' והדרגה דהשתל' שמתמעט האור כו'. אך זהו בבחי' חיצוני' הכלים, משא\"כ בחי' פנימי' הכלים באמת מגלים את האור כמו שהוא כו', וכמו ההמשכה דתו' שמהוע\"צ האור נמשך בכל המדרי' עד גם בחי' המל' ולמטה בבי\"ע, שזהו מה שהמשיך יעקב בחי' המשכת העצמו' ושלא יהי' ע\"ז שום העלם והסתר כלל כו' כנ\"ל, דהמשכה זו הוא בבחי' הפנימי' דע\"ס דוקא וכמשנת\"ל פקי\"ד בענין קו האמצעי ובחי' יחוד פנימי דאו\"א כו', והוא ע\"י בחי' פנימי' הכלים דוקא שאינם\nבבחי' מהות אחר מהאור (שזהו מה שיש דוגמא בהכלי שהיא כמו האור דמשו\"ז היא כלי לקבל את האור כו', שהרי אור וכלים הם רחוקי' ומובדלי' זמ\"ז ואיך האור מתלבש בהכלים כו' אלא שזהו מפני שיש בכלים שהן בדוגמת האור כו', וכמו בהירות חומר העין שבזה הוא כלי לאור הראי', וכמו בזכוכית הבהירות שבה הוא דוגמת האור שעי\"ז היא מקבלת את אור השמש כו', וכמו\"כ בכלים יש מה שהיא בדוגמת האור שזהו בחי' פנימי' הכלי כו' וכמ\"ש במ\"א) ומתאחדת ממש עם האור היינו עם בחי' עצם האור שלמע' מבחי' הארת האור (המתלבש בחיצוני' הכלים כו') ומגלים ממש את האור כו'. וע\"כ כל התהוות יש מאין הוא מבחי' חיצוני' הכלים, וכמו התהוות המלאכי' דהתהוותם הוא להיות בבחי' יש נברא כמ\"ש במ\"א ה\"ז מבחי' חיצוני' הכלים כנודע, אבל מבחי' פנימי' הכלים לא יהי' התהוות יש מאין, מפני שמאיר בחי' עצם האור כ\"א מבחי' פנימי' הכלים נתהוו נשמו' שהן אלקו' כנודע, והיינו דההמשכה וההתהוות שמבחי' פנימי' הכלים הוא שעצם האור נמשך ומתגלה מפני שאינם מסתירים על האור כו'. וע\"כ זה שהכלים נק' ספי' מל' אבן ספיר בבחי' ספירו' ובהירות שמגלים את האור זהו דוקא בבחי' פנימי' הכלים כו'.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש פדה בשלום נפשי, דכל העוסק בתו' ובגמ\"ח ומתפלל עם הצבור כאלו פדאני כו', דהנה ענין הפדי' שייך בבחי' מל' ובמדרי' אחרונות שבה שבאים בבחי' התלבשו' בלבושין דבי\"ע ומתעלם ומסתתר ביותר וכמשנת\"ל פק\"ח, וע\"כ צ\"ל הפדי' להסיר ההעלמו' וההסתרים ולהיות קימה בבחי' המל' וכמשנת\"ל באורך. והנה ידוע שיש אופני בירורים בדרך מלחמה ובדרך מנוחה, דהבירור דתפלה הוא בדרך מלחמה דשעת צלותא שעת קרבא וכמשנת\"ל בענין דטעים טעמא מרירו למתקא שכ\"ז הוא בדרך מלחמה כו', משא\"כ הבירור דתו' הוא בדרך מנוחה שע\"י המשכת האור והגילוי נעשה הבירור בדרך ממילא כו'. וזהו"],[3601330389,"כל העוסק בתו' ובגמ\"ח שהן המשכות מלמעלמ\"ט שעי\"ז נעשה הפדי' בשלום כו', וכן המתפלל עם הצבור דתפלת רבים ממשיך גילוי בחי' עצמו' אוא\"ס וכמארז\"ל דצבור בכל השנה הוא כמו יחיד בעשי\"ת דממשיכי' בחי' עצמו' אוא\"ס שעי\"ז נעשה ג\"כ הבירור בדרך ממילא כו'. וזהו פדה בשלום נפשי שאמר דוד זה על בחינתו בחי' מל' שצריכה פדי', אמנם הפדי' היא בשלום, והיינו ע\"י שברבים היו עמדי שרבים התפללו עבורו, וגם שהוא עצמו כמו רבים נחשב מפני שהי' נשמה כללי' וע\"כ הי' תפלתו כמו תפלת רבים כו'. וזהו פדה בשלום נפשי נפש דוד ע\"י תו' וגמ\"ח שהן המשכו' מלמעלמ\"ט ובפרט פנימי' התו' שהיא ההמשכה מבחי' פנימי' ועצמו' א\"ס כו', וע\"י תפלת רבים שתפלתו בעצמו הוא כמו תפלת רבים ועי\"ז הוא הפדי' בשלום כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וז\"ע ספירות ל' בהירות והוא בחי' פנימיות הכלים, דחיצוניות הכלים הגילוי ע\"י העלם, ולכן הן מקור העולמות והמלאכים, ופנימיות הכלי היא כדוגמת האור ומתאחד עם האור, ולכן הן מקור הנשמות, והן בחי' ספירות ובהירות שמגלים את האור. ובזה יובן מ\"ש פדה בשלום נפשי, פדי' במל' וע\"י התורה הפדי' והבירור בשלום.</span>"],[3601330390,"<h3>בס\"ד. ש\"פ מקץ, שבת חנוכה, תער\"ג</h3>\n<b>מאי</b> חנוכה דת\"ר בכ\"ה בכסלו יומי דחנוכה תמניא אינון, דכשנכנסו יוונים להיכל טמאו כל השמנים שבהיכל וכשגברו מלכות בית חשמונאי ונצחום בדקו ומצאו פך א' של שמן חתום בחותמו של כה\"ג ולא הי' בו כדי להדליק אלא יום א', ונעשה נס והדליקו בו שמונה ימים לשנה אחרת קבעוהו יו\"ט בהלל והודאה, ופרש\"י מאי חנוכה על איזה נס קבעוהו, וצ\"ל דלפ\"ז הי' צ\"ל נק' חג הנרות שזה הי' עיקר הנס שע\"ז קבעוהו ומפני מה נק' חנוכה. גם צ\"ל מהו\"ע שהדליקו בו שמונה ימים למה במספר הזה דוקא. גם צ\"ל מפני מה עשו לעיקר את נס הנרות ולא נס הנצחון, וידוע דהנצחון הי' בכ\"ד כסלו ונס הנרות הי' בכ\"ה וקבעו את היו\"ט בנס הנרות דוקא. ולהבין כ\"ז ילה\"ק משנת\"ל דש' ספי' הוא מל' אבן ספיר והוא ספי' ובהירות שמגלה את האור בלי הסתר, ונת' דהיינו בכלים דאצי' בבחי' פנימי' הכלים דחיצוני' הכלים הגם שמגלים ה\"ז ע\"י שמסתירים כו', ופנימי' הכלי הוא מה שהכלי היא בדוגמא אל האור ומגלה את האור כו'.\nקיז) <b>והנה</b> הפרד\"ס שעה\"כ ערך אבן הספיר כ' בש' התיקוני' שהמל' נק' כן כאשר היא דומה לחכ' שהוא הנק' ספיר וכדפי' בשער הגוונים פ\"ב, וכ\"ה במאו\"א אות א' סעי' ה' אבן ספיר מל' ע\"ש קבלתה מאבא עילאה הנק' ספיר כו' עכ\"ל, ובשער הגוונים פ\"ב כ' דגוון החכ' הוא גוון הספיר שהוא פתיחת כל"],[3601330391,"הגוונים מאין גוון לגוון וממנו יתחלקו לגוונים כו', וכן החכ' מקור כל הפעולות ע\"י השפעתה בבינה, וכמ\"ש כולם בחכ' עשית דחכ' היא מקור הכל וזהו כולם בחכ' ועשית בבינה, דבינה ציירא ציורים כו', ושם פ\"ה ביאר שהחכ' אין בה גוון וכמ\"ש בשם הת\"ז דיו\"ד דש' הוי' לא תפיס בי' גוון כלל הה\"ד אני ה' לא שניתי לא ישתנה בשום גוון כלל כו', אבל הוא האור שע\"י יתגלו הגוונים, והוא משל אל העששיות העשוי' גוונים גוונים ובעוד שלא יאיר האור בה הגוונים מתעלמי' ולא נראים אבל בהאיר אור בה אז יתראו הגוונים כו'. וא\"כ מ\"ש בפ\"ב שממנה יתחלקו הגוונים אין הכוונה שהגוונים הן מעצמה ומהותה והיינו שגם היא בחי' גוון וע\"כ היא פתיחת ומקור כל הגוונים כו', וה\"ז כמו כלל ופרט שאין בכלל אלא מה שבפרט שהכלל כולל כל הפרטי' רק שהן בו בהעלם ואינם ניכרים, אבל מ\"מ ה\"ה נמצאים בו בהעלם וע\"כ ממנו נמשכי' ומתגלי' כל הפרטי', כמו\"כ נא' בענין החכ' דלפי שהיא בעצמה בבחי' גוון וכוללת כולם ע\"כ היא פתיחת כל הגוונים כו', אין הדבר כן כי א\"ז שהגוונים נמשכי' ומתגלי'\nממנה רק שעל ידה יתראו כל הגוונים ע\"י האור שלה וא\"כ אדרבה לפי שהיא בעצם פשוט מכל גוון ומובדל מהם ע\"כ יתראו כל הגוונים ע\"י, וכמו שכל הציורים מציירי' על גוון לבן דוקא שעליו דוקא ניכרים כל הגוונים, והיינו לפי שהוא פשוט מכל הגוונים ע\"כ כל הגוונים והציורים ניכרים עליו דוקא כו', דכל הגוונים כמו אדום וירוק יש להם קירוב הערך זל\"ז דעומק ירוק נוטה לאדמומית ועומק אדום נוטה לשחרות ע\"כ אינו ניכר בהם הגוונים כ\"כ, כ\"א בגוון לבן להיותו מובדל בערך ניכרים בו כל הגוונים כו'. כן החכ' מובדלת היא מכל הספי' שהיא בבחי' אור פשוט וע\"כ על ידה דוקא נראים כל הגוונים כמו שהן בעצם מהותם, דמה שהוא בעצמו בבחי' גוון הרי כשמאיר במדרי' אחרת בהכרח שיש תערובות גוונו (ר\"ל גוון של המדרי' המאירה) באותה המדרי' ואינה נראית כמו שהיא באמת (וכמו שהשכל מראה את המדה לא בגוונה האמיתי כמו שהיא בעצם שהיא למעלה מהשכל כו'), אבל מה שפשוט מכל גוון ה\"ה מראה אמיתית כל הגוונים כו'. וכ\"ה בעבודה דהעיקר ויסוד כל דבר היא נקודת ההתקשרו' בכל לבו\nונפשו לה' בתפלה, ולא רק מה שחפץ בקירוב ודביקו' באלקו' מצד הטוב והעילוי באלקו' כ\"א בבחי' התקשרו' וביטול עצמי בעצם נקודת לבו ונפשו שמתקשר בעצם אלקו' כו' (דבד\"כ הוא הביטול דכח החכ' שבנפש שלמע' מטו\"ד), והעבודה דכל היום בעסק התו' וההתעסקו' בהשגת אלקו' וקיום המצות בוע\"ט כמו במצות צדקה וגמ\"ח וכה\"ג וכן לסור מהרע וגם לשנוא את הרע כו', הכל הוא הסתעפות מהנקודה הנ\"ל, שהיא היסוד שעלי' נבנה כל הבנין דקדושה כו', ועי\"ז היא עשיית כל דבר כפי אמיתי' מהותם באמת. דהנה כאשר קיום המצות מסתעף מן ההתבוננו' והשגה אלקי' והתעוררו' אהוי\"ר הרי בהכרח יש תערובו' המבוקש מההשגה בקיום המצות, דהיינו שעי\"ז יהי' נדבק באלקו' וימשיך גילוי אלקו' כו', וע\"ה שג\"ז הוא אמת וכמ\"ש בסש\"ב והמקיימן באמת הוא האוהב את ה' וחפץ לדבקה בו באמת כו', מ\"מ א\"ז עדיין אמיתי' קיום המצות כמו שהן מצ\"ע מהותם שהוא רק לקיים רצה\"ע כו' (ולבד זאת שיוכל להיות בזה טעות ח\"ו כשהולכים אחר הטעם וכמ\"ש הלא שמוע כו', הנה גם האמת בזה א\"ז עדיין האמת של המצות כמו שהן\nמצ\"ע כו'). ורק כאשר העבודה בידיעת והשגת אלקו' וקיום המצות בסו\"מ וע\"ט הוא מצד נקודת ההתקשרו' לה' לבד, אזי נעשי' כל הדברי' באמיתתן כמו שהן בעצם. ובאמת"],[3601330392,"לגבי נקודת הלב שוה היא ההשגה האלקי' עם מצות הצדקה ושנאת הרע כו', כי הוא רק שיהי' כל לבבו אחר ה' ואין בתנועה זו לא חכ' ולא מעשה כו', והיא יסוד ומקור כולם להיות נעשים כולם כפי אמיתי' מהותם מצד עצמן כו'. ולמע' זהו בחי' החכ' שמובדלת בערך שאין בה גוון כלל בעצם, ועל ידה מתראים כל הגווני' כמו שהן באמיתי' מהותן כו'. ומ\"מ צ\"ל שיהי' לזה איזה שייכות אל הגווני' שלא יתבטלו הגווני' במציאותם בהאיר בהם הגוון הפשוט כו', וי\"ל שזה מ\"ש מאין גוון לגוון והיינו שא\"ז כמו פשיטו' העצמו' דא\"ס שאינו בערך הגוונים כלל משא\"כ בחי' החכ' ע\"ה פשוט מ\"מ יש לה שייכות אל הספי' כו'. ועמ\"ש בשער ס' האצי' פ\"ד בענין החכ' שהיא בבחי' יש מאין לגבי הכתר כ' דאין הכוונה ביש ישות המושג כו', אמנם הכוונה במלת יש בהבדל אשר בין האין והיש לא ישות גמור אלא כשולל האין לא מחייב היש כלל (ושם דהיינו בבחינתה אל הבינה כו', ועמ\"ש מזה בדרוש וככה, רל\"ז). וכמו\"כ י\"ל ענין מאין גוון לגוון היינו רק לשלול העדר הגוון לגמרי אבל לא שהוא בבחי' גוון כו', ועמ\"ש\nבשער אבי\"ע פ\"ט בענין רשימה חקיקה כו' דרשימה אין בו תפיסא עדיין כ\"א ההבדל אשר בין אינו לישנו ר\"ל כהבדל שבין אין הגמור ליש, דוקא תחלת הישות כו', וזהו בבחי' האותי' כמו שהן באצי' בכלל ובחכ' בפרט וכמ\"ש בלק\"ת בהוספות ד\"ה להבין מ\"ש באוצ\"ח ספ\"ה (ובמ\"א אי' דרשימה בא\"א), ולפי שענין הרשימו הוא בבחי' הכלים כ' בין אין הגמור ליש תחלת הישות. ובשער ס' האצי' כ' כשולל האין לא מחייב היש כלל והיינו בבחי' האור כו', ולפ\"ז הוא באור החכ' השייך להשתל' כו'. וי\"ל ג\"כ דבחי' החכ' שאין לה גוון כלל הוא בחי' העליונה דחכ' שהוא בחי' האין דכתר ממש רק שנמצא בין הנאצלי' (וכ\"מ בפלח הרמון סוף שער הגווני' דהכוונה היא על בחי' העליונה שבחכ'), וע\"ה שהיא מובדל בערך מהנאצלי' מ\"מ להיותה נמצא בין הנאצלי' יש לזה שייכות אל הנאצלי' וע\"י יתראו כל הגוונים כמו שהן באמיתי' מהותם כו', וכמשנת\"ל בעבודה בבחי' נקודת ההתקשרות בה' שזהו בחי' פנימי' חכ', וזהו יסוד העבודה דכל היום בעסק התו' ובקיום המצות בסו\"מ וע\"ט להיות כפי אמיתי' מהותן מצ\"ע כו',\nוכמ\"ש במ\"א בענין פנימי' אבא פנימי' עתיק דע\"ה שזהו בחי' פנימי' עתיק ממש מ\"מ להיות שזהו פנימי' אבא שייך בזה המשכה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> בפרדס ובמאו\"א אי' אבן ספיר מל' כשמקבלת מחכ', ובשער הגוונים כ' דחכ' היא פתיחת כל הגוונים, והוא מפני פשיטותה בלי גוון ה\"ה מראה כל הגוונים, וכן בעבודה יסוד כל דבר הוא נקודת ההתקשרות וביטול העצמי, ומ\"מ צ\"ל דחכ' יש לה שייכות אל הגוונים, וז\"ש מאין גוון לגוון, וכמו בין האין והיש, וכמו רשימה בכלים, וי\"ל דהכוונה גם על הבחי' עליונה שבחכ' הואיל ונמצא בין הנאצלים. </span>\nקיח) <b>וע\"פ</b> הנ\"ל י\"ל שמתאים עם מ\"ש הבחיי ס\"פ משפטים בשם הרס\"ג דספיר היא אבן יקרה לבנה וכ\"כ הרד\"ק בשם גאון שהוא קריסטאל. והענין הוא דהנה ידוע דגוון לבן הוא גוון עצמי דבזה חלוק גוון לבן משארי הגוונים שאינו דבר נוסף על עצמו' הדבר כלל, ואינו כמו שאר הגווני' דצבע אדום וירוק וכה\"ג שכולם הם נוספים על עצמיותם, משא\"כ גוון לבן אינו דבר נוסף על עצם הדבר"],[3601330393,"כ\"א הוא הוא העצם כו', וכמו כל דבר שהוא במראה אדום או ירוק א\"ז שהעצם הוא כך כ\"א הוא מאיזה סבה היינו מצד איזה הרכבה דמשו\"ז נעשה במראה זו, וכמו זכוכית ירוקה או אדומה הרי אין הזכוכי' בעצם היא במראה זו רק שנצבעה כך, וכן האבן הירוק והאדום אינו שבעצם הוא כן שהרי אנו רואין אותו במראה אחרת, רק זהו שהמראה בא בו בהרכבה כו', וכ\"ה בעצם הצבע האדום או הירוק ג\"כ אינו עצמי כ\"א מורכב מאיזה דבר כו', שע\"י איזה סיבה נעשה בצבע ומראה זו כו', משא\"כ דבר הלבן הוא עצמי שאינו מורכב בשום דבר. וכמו שבאמת אינו מצוי כלל מציאו' גוון שיהי' צבעו לבן ממש כמו הלבן בעצם, וגוונים הלבנים שנמצאי' והיינו צבע הלבן אינם שוים כלל לעצם לבנוני' כמו שהוא בעצם, שהרי אנ\"ר פשתן הלבן אין דוגמתו בצבע כלל שיהי' צבעו ג\"כ לבן כמוהו כו' (ואפשר דבצבע לבן ג\"כ הלבנוני' הוא עצמי רק שיש בו תערובות מין גוון אחר שבא בו ע\"י הצמיחה או ע\"י האדמה וכמו לבן אדמדם שמעורב מראה אדום בהלבן, אבל הלבנוני' שבו הוא עצמי כו', כי הדוגמא מצבע הלבן למע' הוא מדת החסד\nשהוא ענף החכ' ויש בזה התדמו' לאוא\"ס ב\"ה במה שהוא בחי' הגילוי והגילוי הוא בבחי' בל\"ג כו', דמדת הגבו' היא מחולקת במה שהיא בחי' העדר הגילוי ובחי' ההגבלה כו', וה\"ז כמו דבר נוסף על העצם כו', אבל מדת החסד עם היותה בחי' מדה לבד ה\"ה כמו העצם שהיא בחי' הגילוי והגילוי הוא כמו שהוא דהיינו בבחי' בל\"ג כו', וזהו שגם בצבע הלבן הלבנוני' היא עצמי כו', משא\"כ שארי הגוונים עצם הצבע והגוון הוא מורכב לא עצמי כו'), ולכן בכל הגווני' יש בהם נטי' לכמה מיני מראות משונים, וכמו במראה האדום יש בו ריבוי מזיגו' והרכבו', וכן בירוק שיש בו כמה מיני מזיגות וכמו שאמרו על ירקרק או אדמדם ירוק שבירוקין או אדום שבאדומין כו', הרי שיש חילוקי' בירוק ואדום והוא בהם הרכבה, וכמו מראה הזהב הוא מראה הירוק ונוטה לאדום וכמ\"ש וירק את חניכיו וארז\"ל שהוריקן בזהב, ופרש\"י כמו ואברותי' בירקרק חרוץ שהוא ל' ירוק ונוטה לאדום, וכן מראה חלמון ביצה שנוטה לאדום ועומק ירוק יש בו אדמומיות ועומק אדום יש בו שחרות, ובד\"כ יש בהם ריבוי מיני הרכבות כו'\n(ומ\"מ אינו פתוך מפני שההרכבה היא מתולדה), והיינו מפני שבעצם הם מורכבים ע\"כ יש בהם הרכבה גם מגוונים ומראות אחרים כו'. משא\"כ גוון לבן אין בו נטיות לגוון זולתו רק שיש חילוקים במראה הלובן עצמו וכמו עזה כשלג וכצמר לבן וסיד ההיכל כו', שזהו דרגות בעצם הלובן אבל אין בו נטי' לגוון אחר, והיינו לפי שהוא גוון פשוט ועצמי כו'. והנמשל מזה יובן למע' בש' הוי' שנק' שם העצם שאינו נוסף על עצמותו כלל, והגם כי כל השמות אינם נוספים על עצמותו ח\"ו שה\"ה עצמו' אלקו' כו', מ\"מ דוקא ש' הוי' נק' ש' העצם מפני שאינו דומה לשאר השמות, שהרי גם קודם שנבה\"ע הי' הוא ושמו לבד שזהו ש' הוי' שנק' שמו הגדול כו', דענין הוא ושמו לבד היינו שהשם הוא כמו העצם ואינו דבר נוסף על העצם כו', והגם דשארי שמות הי' באמת ג\"כ קודם שנבה\"ע שאינם מחודשי' ח\"ו מאחר שהן אלקו' (ובד\"פ גם אצי' הוא מחודש ע\"י הצמצום כו' וכמ\"ש במ\"א). אך הענין דשארי השמות הן בכלים שהכלים הן בבחי' מציאו' דבר עם היותן אלקו' ממש כו', וע\"כ אינם עצמי' היינו שאינם בבחי' גילוי מן\nהעצם מאחר שהן בבחי' מציאו' דבר כו', וממילא ה\"ה בבחי' דבר נוסף על העצם כו', וגם בעצם מהותם אינם בבחי' פשיטו' מאחר שהן בבחי' מציאו' דבר כו' (והיינו שאינם עצמיים לגבי"],[3601330394,"אוא\"ס ב\"ה שאינם בבחי' גילוי מן העצם כו', וגם בעצמם אינם עצמי' ופשוטי' כו'). וכן בשרשם באוא\"ס שלפה\"צ הן בחי' כח הגבול שבא\"ס, והן אותי' הרשימו כו', דע\"ה שזהו בחי' א\"ס ממש מ\"מ ה\"ז נק' באין ערוך לגבי א\"ס הבל\"ג כו' וכמ\"ש במ\"א, ואינו בבחי' גילוי מן העצם דע\"ה שזהו בחי' עצמות א\"ס ממש ומ\"מ אינו בבחי' גילוי מן העצם כו', וידוע דע\"י הצמצום נעשו אותי' הרשימו בבחי' מציאו' דבר שזהו התגלו' שרש הכלים שנעשה ע\"י הצמצום כו', ולפה\"צ אינם בבחי' מציאו' כלל וכלל, ומ\"מ אינם בבחי' עצמי' ופשיטו' כו'. משא\"כ בחי' האור ה\"ה בבחי' גילוי מן העצם כו', וגם לפי המבו' בדרוש זה דבאורות יש ג\"כ ע\"ס ובשרשן באוא\"ס שלפה\"צ הוא מה שאוא\"ס שיער בעצמו להאיר בבחי' מדה וגבול כו', מ\"מ הרי נת\"ל פט\"ז שא\"ז בחי' כח הגבול כו', שהרי האורות הן בבחי' גילוי ההעלם וה\"ה בבחי' פשיטו' כו'. וז\"ע דש' הוי' הוא ש' העצם והוא בחי' האור (גם האורות דע\"ס וכ\"ש האור העצמי כו'), שהוא בבחי' גילוי מן העצם, וכמו העצם שהוא אור פשוט עדיין ואינו שייך בו גוון כ\"א גוון\nפשוט כמו גוון לבן כו', דשארי שמות שהן בבחי' הכלים ה\"ה בבחי' גווני' כמו אדום וירוק כו', אבל ש' הוי' הוא בחי' האור הוא בבחי' גוון פשוט כו'. וזהו שהחכ' נק' ספיר שהוא גוון לבן, להיות דחכ' הוא בחי' האור שהוא בבחי' גילוי מן העצם ובבחי' אין ה\"ה בבחי' פשיטות שאין בו שום גוון כ\"א בחי' גוון פשוט ועצמי כו', וכמ\"ש בסש\"ב פל\"ה בהג\"ה דאוא\"ס אחד האמת שהוא לבדו הוא ואין זולתו וזו היא מדרי' החכ' כו', והיינו דבחי' החכ' להיות שזהו בחי' האור הדבוק באוא\"ס המאציל ה\"ה בבחי' אין ובבחי' ביטול דכולא קכל\"ח שז\"ע אין זולתו כו', ע\"כ אינו בבחי' גוון כלל כ\"א בבחי' גוון פשוט כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ויתאים למ\"ש הבחיי דספיר היא אבן לבנה, לובן הוא גוון עצמי בלתי מורכב, לכן אין בו בעצם נטי' לשום גוון, משא\"כ בשארי גוונים, והדוגמא לזה ש' הוי' שם העצם, דכל השמות אינן גילוי מן העצם, וגם אינן עצמים ופשוטים, וש' הוי' הוא האור שהוא גילוי מן העצם, והוא עצמי ופשוט, וכן חכ' הוא בחי' האור שהוא בחי' גילוי מן העצם, והיא בבחי' אין ופשיטות. </span>\nקיט) <b>וזהו</b> ג\"כ ענין ספיר ל' ספירות ובהירות, דהנה האור הוא ג\"כ בבחי' לבוש וכמ\"ש עוטה אור כשלמה ות\"י דמתעטף נהורא איך סדינא, ובמד\"ר אי' שנתעטף בה הקב\"ה כשלמה (כ\"ה בב\"ר פ\"ז ובשמ\"ר פ\"נ אי' באו\"א), והיינו דלגבי העצמית הוא בחי' לבוש לבד שהרי אינו עצמי רק גילוי לבד וכל גילוי הוא בחי' לבוש, וכנודע דאור ושם ולבוש הכל א' שהכל הוא הארה כו', ובפרד\"ס בערך שם דשם הוא לבוש כו', הרי האור הוא בחי' לבוש לגבי העצמית כו'. אמנם הוא בחי' לבוש אור שאינו מעלים ומסתיר כלל על העצמי' ולא כמו בחי' הכלים שהם מעלימים על עצם האור שמגלים כו', וגם בחי' פנימי' הכלים ה\"ה בבחי' כלים עכ\"פ ואינו מאיר העצמי כמו שהוא כו', משא\"כ בבחי' האור שאין בזה העלם והסתר כלל ומגלה עצם האור כמו שהוא כו'. והענין הוא כמ\"ש והי' ה' לי לאלקים דקאי על לעתיד שאז יהי' הוי' בבחי' אלקים, והיינו כמו שעכשיו גילוי ש' הוי' הוא ע\"י ש' אלקים כמו\"כ יהי' לעתיד גילוי בחי' ש' ה' דלעילא ע\"י השם ה' דלתתא,"],[3601330395,"וזהו שההוי' דעכשיו יהי' לעתיד כמו אלקים דעכשיו שבו וע\"י יהי' גילוי ש' ה' דלעילא כו'. אך אופן הגילוי יהי' באופן אחר לגמרי דעכשיו הגילוי הוא ע\"י הסתר האור וכמ\"ש שמש ומגן ה' אלקים, דכמו שמגן ונרתק השמש ה\"ה מסתיר על אור עצם השמש כו', כמו\"כ ש' אלקים שהן בחי' הכלים בכלל ה\"ה מסתירים על האור שאינו מאיר עצם האור כו', אבל כאשר יהי' הגילוי ע\"י ש' ה' יהי' גילוי בחי' עצם האור שלא בבחי' הסתר כו'. ומה שתהי' ההמשכה ע\"י ש' הוי' הוא שיהי' בבחי' או\"פ ויהי' בבחי' התלבשות והתגלות בעולמות כו', דש' הוי' דלעילא הוא בחי' סוכ\"ע שבבחי' בל\"ג ואינו בא בבחי' התלבשות פנימי כו', ותכלית הכוונה הוא שיהי' בבחי' התלבשות דוקא כו' (והיינו בבחי' גילוי שז\"ע התלבשות וכמ\"ש בסש\"ב פמ\"ח כי ההשפעה שהיא בבחי' גילוי בעולמות נק' בשם הלבשה כו' כי הם מלבישים ומשיגים ההשפעה שמקבלים כו', וגילוי זה הוא ע\"י החכ' וכמ\"ש בלק\"ת ד\"ה ואהבת פ\"ב ובד\"ה ויקח קרח פ\"ב, דאוא\"ס הסוכ\"ע אינו מאיר בבחי' או\"פ בשום כלי כ\"א בבחי' החכ' מאיר בבחי' או\"פ, מפני\nשהחכ' הוא בחי' אין וכנ\"ל פקי\"ח, וכ\"ש שהוא כן בבחי' האור כו', ולהיות שהוא בבחי' מציאות אור עכ\"פ וכנ\"ל שהוא בחי' לבוש, ע\"כ שייך לומר שע\"י מתגלה בחי' האור העצמי דהיינו בחי' סוכ\"ע כו' ועמ\"ש לקמן בענין אור וכח, ובפרט לפי המבו' בדרוש זה שהאור הוא ג\"כ בבחי' ע\"ס כו'). וכמו הרחיבי מקום אהלך דגם בבחי' המל' יהי' הגילוי בבחי' מרחב העצמי דא\"ס וכמו פרזות תשב ירושלים כו', ומ\"מ יהי' בבחי' התלבשו' שז\"ע מקום אהלך דוקא כו', וזהו ע\"י שיהי' הגילוי ע\"י ש' ה' דלתתא שהוא בחי' או\"פ שעי\"ז יבוא האור העצמי ג\"כ בבחי' מדה ושיעור באופן שיהי' בבחי' התלבשו' כו' (וכמו בתו\"מ עכשיו שהן מבחי' עצמו' א\"ס ומ\"מ ה\"ה בבחי' או\"פ בבחי' מדה ושיעור כו', רק שבתו\"מ עכשיו הוא בד\"כ רק מה שתופס את העצם ואינו בבחי' גילוי ממש כו', וכמ\"ש בסש\"ב ח\"א ספ\"ד, ועמשית\"ל פ', והיינו שבלימוד ההלכה ה\"ה תופס במהות בחי' ח\"ע, אבל אינו מאיר עדיין בבחי' גילוי ממש רק הארה מזה בבחי' ידיעת פנימיות התורה כו', ומעין זה לנשמות בג\"ע שנהנין מזיו תורתן ועבודתן בבחי'\nהשגה כו', ולעתיד יהי' בבחי' גילוי ממש כו'). אבל הגילוי יהי' בחי' עצם האור ממש כו', והיינו לפי שהגילוי יהי' ע\"י ש' הוי' שהוא בחי' לבוש אור שמגלה את העצם כו', וז\"ע בחי' ספירו' ובהירות כו', ונמצא דעיקר ש' ספירה ל' בהירות הוא בהאור כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וז\"ע ספירות ובהירות, דהאור הוא בחי' לבוש לגבי העצם, והוא לבוש אור, וכמו שלעתיד יהי' הוי' אלקים והיינו שיהי' הגילוי דש' הוי' דלעילא ע\"י ש' הוי' דלתתא ויהי' גילוי האור ובבחי' התלבשות פנימי גם בבחי' מל', וכמו בתו\"מ עכשיו בהעלם יהי' לעתיד בגילוי, ולפ\"ז ענין הבהירות הוא בהאור. </span>\nקכ) <b>וענין</b> הבהירות שבהאור הוא בב' דברים, הא' מה שהאור בעצם הוא אור בהיר ולא כמו הכלים שהן בחי' העלם בעצם מהותן, וכמשנת\"ל פ\"ט, משא\"כ האור הוא בבחי' גילוי בעצם שהו\"ע הבהירות כו', גם ענין אור בהיר הוא בחי' עצם האור לא כמו שהוא מאיר ע\"י הכלים. והוא ההפרש בין ש' הוי' שנא' בהאבות לש' הוי' דמ\"ת כו', דגבי האבות נא' כ\"פ הוי' ומ\"מ כתיב וארא אל"],[3601330396,"אברהם כו' באל שדי ושמי ה' לא נודעתי להם, וידוע דש' שדי הוא בחי' הגבול והו\"ע הכלים כו', והיינו דמה שהאיר להאבות הוא האור והגילוי שע\"י הכלים שהן בחי' גווני האור לא בבחי' פשיטו' כו', והוא בחי' הארת ש' הוי' המאיר ע\"י ש' אלקים כו' (ובכ\"ד מבו' שזהו הנמשך בבי\"ע והוא בחי' יחוד ה' אלקים דברה\"ע דכתיב בראשית ברא אלקים והרי ההתהוות הוא מש' הוי' שהוא ל' מהווה כו', אך כמו\"כ י\"ל באצי' שזהו בחי' האור המאיר ע\"י הכלי שהרי האבות הי' להם גילוי אצי' אלא שהי' במדרי' הנ\"ל). אבל במ\"ת לכן אמור לבנ\"י אני ה' הוא ש' הוי' בעצם בחי' האור כמו שהוא בעצם כו', ובד\"פ הוא בחי' החכ' שלמע' מבחי' כלים עדיין והוא בחי' גוון לבן הנ\"ל בחי' גוון עצמי ופשוט כו' (ועמ\"ש בתו\"א ד\"ה משה ידבר ומש\"ש בענין ז' שמות כו' הן אורות המתלבשי' בכלים כמש\"ש בהביאור בהג\"ה, ומשה הוא בבחי' עצם החכ' כו'), וז\"ע אור בהיר כו'. ולפ\"ז י\"ל ענין הספירו' והבהירו' שבהאור הוא לגבי האור עצמו שהוא בבחי' בהירו' היינו מה שמאיר בגילוי ממש בבחי' אור בהיר כמו שהוא\nבעצמותו כו', והב' ענין הבהירות שבהאור שמגלה את האוא\"ס שלמע' מאצי' וכמו שמגלה המח' הנעלמו' וההפלאה דאוא\"ס שנת\"ל מפצ\"ה עד פק\"ד שהגילוי הוא בבחי' בהירות כו', וגם כמשנת\"ל בענין והי' הוי' לי לאלקים כו', שמגלה את הש' הוי' דלעילא כו'. וענין הבהירות של הכלים הוא רק שמגלים את האור כו', ובאמת בענין הכלים יש ג\"כ בהירות עצמן ומה שמגלים את האור, דהנה בסש\"ב פ\"ך וכ\"א מבאר ענין יחו\"ע שהו\"ע דבורו ומחשבתו ית' שמיוחדות עמו בתכלית היחוד כמו דבורו ומחשבתו של אדם בעודן בכח חכמתו כו', ומובן שזהו היחוד בבחי' הכלים דאצי' שהן כדוגמת האותי' שמיוחדי' עם האור דאיהו וגרמוהי חד כו' (ועמשית\"ל פ'), והיחוד דאורות ה\"ה למע' מהיחוד דכלים דז\"ש איהו וחיוהי חד בפ\"ע כו'. והוא ההפרש שבין תו' למצות דאוריי' וקוב\"ה כו\"ח ממש והמצות נק' אברים רמ\"ח פקודין רמ\"ח אבד\"מ וכמ\"ש בסש\"ב פכ\"ג, דע\"ה שהאברים מיוחדי' עם הנפש מ\"מ אינו דומה ליחוד הכחות עם הנפש שהן כחות נפשי' ומיוחדי' ממש כו', והוא ההפרש בין אחד ליחיד כו' עמ\"ש בתו\"א ד\"ה וארא הא',\nדכמו\"כ הוא בהבירורי' למטה דע\"י המצות הוא שנעשים דברים התחתוני' כלים לאלקו' ע\"ד כלים דאצי' וע\"י התו' היחוד הוא בבחי' האורות כו'. וז\"ע הבהירות דהכלים מצ\"ע שהו\"ע היחוד שע\"י המצות שמתייחדים באחד כו', ומה שמגלים בהירו' האור היינו בחי' פנימי' הכלים שמגלים עצם האור שהו\"ע היחוד שע\"י התו' כו'. ובהירות האור הוא בחי' עצם האור שלמע' מבחי' הכלים, וכנודע דבכלים יש ג' מדרי' פנימי אמצעי חיצון שהן רת\"ס, ובהאור יש ד' מדרי' והוא האור שלמע' מהכלים בחי' אצי' שבאצי' כו' (וי\"ל שזהו מדרי' עליונה בתו' גופא וכמו תורתו אומנתו וכה\"ג), ומה שהאור מגלה בחי' ש' הוי' דלעילא. והענין הוא כמבו' במ\"א (בדרוש יו\"ט של ר\"ה, רס\"ו) בענין ואמת ה' לעולם דאמיתו' דש' ה' הוא ש' ה' דלעילא והוא בחי' ד\"ע כמו שהוא בבחי' עצמות אוא\"ס שלמע' מאצי' שלמע' מבחי' ד\"ע דאצי' כו', וז\"ע הבהירות שהאור מגלה כו'.\n<b>וע\"פ</b> הנ\"ל יובן משארז\"ל מאי חנוכה דכשנכנסו כו' וכשגברו כו', דהנה חנוכה הוא חנו כה, ונודע דכה הוא בחי' כדמותנו בחי' יחו\"ת וכמ\"ש נעשה אדם"],[3601330397,"בצלמנו כדמותנו, דצלמנו הוא בחי' צורה עצמי' והיינו בחי' דעה עליונה שהיא הדעה דבחי' עצמו' אוא\"ס והיא הדעה האמיתי' כו', וכדמותנו הוא בחי' יחו\"ת שהעולם הוא במציאו' יש רק שבטל לאלקו', שאין זה כפי האמת דהרי באמת אין שום מציאו' דאני הוי' לא שניתי וכולא קמי' כל\"ח כו', א\"כ ה\"ז רק דמיון לבד ומ\"מ הוא כדמותנו לפי שהוא בחי' ביטול עכ\"פ כו'. וזשארז\"ל כל הנביאים נתנבאו בכה בחי' כדמותנו ומשה נתנבא בזה בחי' גילוי והיינו בחי' האור שהוא בחי' גילוי בבחי' בהירות שהביטול בזה הוא בבחי' כולא קכל\"ח כו'. וענין חנו כה הוא שיהי' הגילוי גם בבחי' המל' וכמו הרחיבי מקום אהלך שנת\"ל גם בבחי' מל' יהי' גילוי אוא\"ס ויהיה הביטול דבחי' יחו\"ע כו', ובזה הי' להם המנוחה מהמלחמה שז\"ע חנ\"ו כה כו'. דהנה דמלחמת היוונים הי' מלחמה רוחני' שבקשו להשכיחם תורתך כו', ולהגביר ח\"ו החכמו' החיצוני' וכמא' כתבו לכם על קרן השור כו', וזהו שטמאו כל השמנים כו', וכשגברו מלכות בית חשמונאי ונצחום שההתגברו' הי' בכח מס\"נ דוקא שעי\"ז המשיכו בחי' עצמו' אוא\"ס\nשלמע' מס' השתל', בדקו ומצאו פך א' של שמן חתום בחותמו של כה\"ג בחי' א\"א והדליקו בו שמונה ימים היינו ח' פעמים, וכנודע דז' נרות הן ז\"פ הוי' והן ש' הוי' דס' השתל' וח\"פ הוי' הוא בחי' ש' הוי' דלעילא שלמע' מהשתל', דיצחק בגימט' ח\"פ הוי', ולעתיד יאמרו ליצחק כי אתה אבינו כו', והיינו דלעתיד יהי' גילוי ש' הוי' דלעילא ע\"י ש' הוי' דלתתא ויהי' בבחי' גילוי ממש כו' כנ\"ל, וזהו שהדליקו בו דוקא שמונה ימים לפי שהמשיכו גילוי בחי' ש' הוי' דלעילא כו'. וזהו שעשו עיקר מהנס דנרות להיות שזהו ההמשכה שע\"י התגברות המס\"נ וזהו עיקר הנצחון שלהם דבגילוי בחי' זו יתפרדו כל כו', והגילוי הי' בבחי' מל' שעי\"ז דוקא הגילוי למטה, וזהו שם חנוכה חנו כה שהי' הגילוי במל' והגילוי הוא מבחי' עצמו' אוא\"ס שעי\"ז הי' המנוחה שלהם כו'. וזהו מאי חנוכה על איזה נס קבעוהו ואו' שהוא על נס הנרות, דהיוונים רצו להתגבר ח\"ו על התורה להעלים ולהסתיר כו' (וכמו לבן הארמי אובד אבי כו' וכמשנת\"ל). והחשמונאים התגברו בכח מס\"נ שלהם והמשיכו עי\"ז מבחי' עצמו' אוא\"ס,\nוהוא גילוי ש' ה' דלעילא שיאיר בבחי' מל' ויהי' הגילוי למטה ועי\"ז יתפרדו כו', ועש\"ז נק' חנוכה חנו כה שהי' הגילוי דבחי' עצמו' אוא\"ס בבחי' המל' ועי\"ז הוא בחי' המנוחה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וענין הבהירות שבאור הא' הוא בהירות עצמו שהוא גילוי, ועוד גילוי עצם האור, וזהו יתרון הגילוי דמ\"ת על הגילוי דהאבות, והב' שמגלה האור שלמע' מאצי', גם בכלים יש בהירות עצמן והוא הביטול והיחוד שלהם בהאור, והב' דפנימיות הכלים מגלים עצם האור דאו\"פ, והאור מגלה בבחי' או\"פ האור דא\"ס. וע\"פ הנ\"ל ית' ענין חנוכה חנו כ\"ה. </span>"],[3601330398,"<h3>בס\"ד. ש\"פ ויגש, תער\"ג</h3>\n<b>ולא</b> יכול יוסף להתאפק לכל הנצבים עליו ויקרא הוציאו כל איש כו' ולא עמד איש אתו כו', וצ\"ל מפני מה לא יכול להתאפק הרי פעמי' כתי' ויתאפק יוסף וכאן לא יכול להתאפק. גם צ\"ל מ\"ש ולא עמד איש אתו הרי כבר נא' הוציאו כל איש ומהו עוד ולא עמד כו'. ובזהר אי' ולא עמד איש אתו הה\"ד ביום השמיני עצרת תהי' לכם וצ\"ל מה שייכות שמע\"צ לולא עמד איש כו'. ולהבין כ\"ז ילה\"ק משנת\"ל בש' ספירה שהוא ל' ספירו' ובהירות ונת' זה בבחי' הכלים הוא בבחי' פנימי' הכלים שאינם מסתירי' על האור לפי שאינם בבחי' מהות אחר כו', והעיקר הוא בבחי' האור שהוא בבחי' אור עצמי ופשוט ע\"כ הוא בבחי' בהירות בעצם וגם שמגלה את האור א\"ס שלמע' מאצי' בבחי' גילוי כמו שהוא, והו\"ע הגילוי דלעתיד שיהי' גילוי הוי' דלתתא בבחי' אלקים שבו וע\"י יהי' גילוי ש' הוי' דלעילא בבחי' גילוי ממש כו'.\nקכא) <b>והנה</b> באמת י\"ל דעיקר ענין ספי' ובהירות הוא במדרי' שלמע' מאצי' הן מצד בחי' הכלים והן מצד בחי' האורות, דהנה בבחי' הכלים הרי ידוע דכלים דאצי' הן כמשל אותי' הכתב והכלים שבכתר הן כמשל אותי' החקיקה, וההפרש ביניהם ידוע דבאותי' הכתב הרי הדיו הוא דבר בפ\"ע מהקלף ומכסה עליו, וע\"ה שעי\"ז מתגלים האותי' (דגילוי האותי' הוא מהקלף וכמארז\"ל כל אות שאין גויל מוקף לה מד' רוחותי' פסולה, הרי מובן מזה שהאות הוא מהקלף דוקא, ולכן צריכים שיהי' גויל מוקף לה כו'), ה\"ז ע\"י הכיסוי וההסתר דוקא. משא\"כ אותי' החקיקה אינן דבר בפ\"ע וה\"ה מהאב\"ט עצמו כו'. דהדוגמא מזה למע' דהכלים שבאצי' הן כמהות אחר מהאור, רק שאינם מהות זר ח\"ו כמו הכלים דבי\"ע שהם בענין אחר שלא מענין האצי' כו', משא\"כ הכלים דאצי' ה\"ה ג\"כ אצי' כו', אבל מ\"מ ה\"ה בבחי' מהות אחר לגבי האור כו', וממילא אין עצם האור מתלבש בהם כו', והכלים מכסים ומעלימים על האור ועי\"ז הם מגלים כו', שזהו כן בכללו' הכלים גם בבחי' הפנימי' שלהם שנת\"ל פקט\"ז שזהו מה שהכלי הוא\nדוגמת האור מ\"מ ה\"ז כלי ולא אור כו'. וכמו בהירות הזכוכית שהיא בדומה לבהירות אור השמש וכמו בהירות חומר העין שבדומה לאור הראי', הרי מ\"מ א\"ז בהירות השמש או בהירות אור הראי' כ\"א רק בהירות החומר לבד, רק שחומר העין ממש ה\"ה כמו כל חומרי' האברי' ובענין הבהירות שבו הוא מובדל מכל האברי' שבזה הוא בהתדמות אל הצורה הרוחני' שהוא אור הראי', אבל כ\"ז הוא בהחומר לבד כו'. וכמו\"כ יובן למע' דגם מה שהכלי היא בדומה להאור הכל הוא בחי' הכלי שהוא בבחי' נוסף על האור כו', וע\"כ בכ\"מ שיש נגיעת הכלי אין האור מתגלה כמו שהוא בעצם ממש כו'. אבל בחי' הכלים דכתר שאינן בבחי' מהות בפ\"ע מהאור היינו שאינם מהות אחר כלל, הרי אינם מסתירים כלל על האור ומאיר האור כמו שהוא כו', והגם דאותי' החקיקה ג\"כ משחירים על האב\"ט, ה\"ז רק על הבהקת האבן לא על עצם האב\"ט, שהרי אין כאן דבר המכסה על האב\"ט כ\"א שמשחיר את הבהקת האב\"ט. דהענין למע' הוא דהנה בענין ההסתר של הכלים יש ב' ענינים, הא' שאין העצמי ממש של האור מתלבש בהכלים כ\"א רק חיצוניותו לבד, ובזה לא שהכלי"],[3601330399,"מסתיר על האור כ\"א בדרך גורם לבד, שבכ\"מ שבא בבחי' התלבשו' בכלים אין העצמו' מתלבש כ\"א הארה כו', והב' שהאור המתלבש הוא מתעלם ומסתתר ע\"י הכלים כו'. והנה האופן הא' יש גם באותי' החקיקה להיות שמ\"מ ה\"ה בבחי' כלים ע\"כ אין העצמי' ממש מתלבש בזה כו', אבל האור המתלבש אינו מתעלם ומסתתר כלל ע\"י האותי' כו', וזהו שהאותי' משחירים רק על הבהקת האב\"ט היינו בחי' עצמו' האור אבל האור המתלבש בהם אין שום דבר המכסה ומסתיר כו'. וזהו ההפרש בין אותי' הכתב לאותי' החקיקה דאותי' הכתב דהיינו כלים דאצי' מכסים ומסתירים על האור המתלבש בתוכם, וכלים שלמעלה מאצי' אינם מכסים על האורות המתלבשי' בתוכם ומאיר האור כמו שהוא כו'. ובאמת יש הפרש גם מצד בחי' העצמו', דבכלים שאינם בבחי' מהות אחר אין ההתלבשו' רק בחי' חיצוני' האור כ\"א גם מבחי' העצמו' כו', וע\"כ באמת אינו דומה אופן האור המתלבש בכלים שבכתר לאופן האור המתלבש בכלים דאצי' כו'. אך ההפרש הזה יש בכלים דאצי' גופא בין חיצוני' הכלים לפנימי' הכלים, דבבחי' פנימי' הכלים שזהו מה שהכלי היא\nבדוגמא ג\"כ ההתלבשו' היא יותר מבחי' עצמו' האור כו'. אמנם ההפרש הנ\"ל הוא בכללו' בין הכלים דאצי' לכלים שבכתר, דכלים דאצי' מכסים על האור המתלבש בתוכם, משא\"כ הכלים שבכתר אינם מכסים כלל על האור המתלבש בתוכם כו', ועמ\"ש מזה באורך בדרוש יו\"ט של ר\"ה, רס\"ו, וע\"כ שם הוא עיקר ענין הבהירות שבכלים שמגלים עצם האור כמו שהוא כו'. אך בחי' הכלים שבכתר י\"ל שזהו בבחי' הע\"ס הכלולי' בכתר דהיינו שרש הפנימי כו', דבבחי' אוא\"ס ממש היינו האור שהוא בבחי' א\"ס ובבחי' בל\"ג אינו שייך ענין הכלים כלל כו', והבהירו' דשם הוא רק בבחי' האור כו', וכמ\"ש אור בהיר הוא בשחקים שזהו בהירות דבחי' עתיק כו' וכמ\"ש במ\"א, דהבהירות דשם הוא בבחי' גילוי העצם ממש כו'. דהנה האורות דאצי' הרי המשכתם הוא ע\"י בחי' הצמצום והפרסא שבין הכתר אל החכ' כו', וע\"ה שאינה בבחי' פרסא המפסקת כמשנת\"ל פק\"ז שאין האור בבחי' מהות אחר ח\"ו, מ\"מ אינו ג\"כ בחי' מהות האור של המאציל ממש כו', ובפרט לגבי האור שבבחי' א\"ס (הגם דהאור דאצי' הוא בבחי' גילוי ההעלם גם לגבי האור\nדסוכ\"ע כו') דהצמצום הוא בבחי' סילוק לא רק בבחי' מיעוט לבד כו', וכמשנת\"ל פכ\"ז דבענין הצמצום יש ב' דברים דהיינו בחי' מיעוט ובחי' סילוק, דלגבי שרשי האורות הוא בבחי' מיעוט לבד ולגבי האור שבבחי' א\"ס הוא בבחי' סילוק כו', וא\"כ ע\"ה שאינו בבחי' מהות אחר ח\"ו, מ\"מ ה\"ז אור הבא ע\"י הצמצום כו', וע\"כ א\"ז בבחי' גילוי מן העצם ממש כו', וממילא גם בחי' הבהירות א\"ז בבחי' בהירות ממש, הן בבחי' בהירות האור בעצם אינו בבחי' אור בהיר ממש מאחר שהוא אור מצומצם כו', וכמו\"כ אינו שמגלה ממש את האוא\"ס מאחר שבא ע\"י צמצום והפסק כו'. והגם שנת\"ל פקי\"ט בענין והי' הוי' לי לאלקים שיתגלה הש' הוי' דלעילא כמו שהוא, דבאמת כן יהי' בגילוי דלעתיד שלא יהי' שום כיסוי והסתר כלל וכמ\"ש ולא יכנף כו', י\"ל שזהו שהגילוי דש' הוי' דלעילא יהי' באופן כזה שיתגלה כמו שהוא והשם הוי' דלתתא ודאי יהי' בבחי' כלי לקבל את האור דש' הוי' דלעילא כמו שהוא בעצם כו', אבל לא דהש' הוי' דלתתא מגלה את האור כמו שהוא, כ\"א שהש' הוי' דלעילא יתגלה כמו שהוא בעצם, מפני\nשלעתיד לא יהיו ענין הצמצומי' וכמו עכשיו בשבת דכתי' ויכל אלקי' שכלו הצמצומי' כו' וכמ\"ש במ\"א, ושבת הוא מעין דלעתיד כו',"],[3601330400,"וע\"כ לעתיד שלא יהיו הצמצומי' יהי' גילוי אור העצמי כמו שהוא בעצם ממש כו', אבל האור מאחר שבא ע\"י הצמצום אינו מגלה את האור העצמי כמו שהוא ממש כו'. משא\"כ בחי' האור הא\"ס שלמע' מאצי' מאחר שאינו בא ע\"י צמצום כלל ה\"ה בבחי' גילוי מן העצם ממש, וע\"כ הוא בבחי' אור בהיר בעצם וגם מגלה עצם האור כמו שהוא ממש כו', וע\"כ עיקר ענין הבהירות הוא בבחי' האור שלמע' מאצי'.\n<span data-k=\"ks\"><b>קיצור.</b> וי\"ל דעיקר ענין בהירות הוא בבחי' הכתר, הן בבחי' הכלים כידוע דכלים דאצי' הן עד\"מ אותיות הכתב שמעלימים על האור להיותם מהות אחר, גם בחי' פנימיות הכלים, וכלים שבכתר עד\"מ אותיות החקיקה דעם היות שמשחירים היינו שבהכלים אינו מתלבש עצמות האור, אבל אינם מעלימים על האור המתלבש בהם. וי\"ל דזהו בהע\"ס הכלולים בכתר, ועצם הכתר בחי' אור, אור בהיר גילוי העצם, דאורות דאצי' הן ע\"י צמצום א\"כ אינו אור בהיר ממש, ואינו מגלה ממש האוא\"ס, ולעתיד יהי' גילוי ש' הוי' דלעילא ממש, זהו שמלמעלה יהי' ההתגלות באופן כזה, ואור הא\"ס שאינו ע\"י צמצום ה\"ז אור בהיר ממש, ומגלה עצם האור. </span>\nקכב) <b>והגם</b> דלכאו' מה שייך באוא\"ס שמגלה דבר הרי הכל הוא בחי' עצמו' אוא\"ס כו'. הענין הוא דהנה יש בחי' לבושין גם למע' מאצי', וכמ\"ש הוד והדר לבשת ואח\"כ כתי' עוטה אור כשלמה, דעוטה אור הוא בחי' אור האצי' כנ\"ל פרק הנ\"ל, וא\"כ מ\"ש קודם לזה הוד והדר לבשת היינו במדרי' שלמע' מאצי' והוא בבחי' הכתר כו'. דהנה ידוע דכתר יש בו ג\"כ פנימי' וחיצוני' דכל אור גם שאין בו התחלקו' מדרי' מ\"מ יש בו פנימי' וחיצוני' (שהוא עצם האור והתפשטו' האור) וכמ\"ש במ\"א, וכן בבחי' הכתר יש בחי' פנימי' וחיצוני' והן בחי' עתיק ואריך, וז\"ע בחי' הוד והדר כו', כי הוד פירושו זיו כמו ונתת מהודך עליו וכמו כסה שמים הודו כו'. אמנם ענין ההוד הוא בחי' זיו ואור עצמי, וזהו ההפרש בין הוד להדר דהוד הוא עצם האור והדר הוא התגלו' ההוד וכמו הדר כבוד הודך כו', וכמו במשה אי' ברע\"מ פנחס דרכ\"ג ונתן ההוד למשה, וביהושע הי' בבחי' הדר וכדאי' בילקוט פ' ברכה ניתן ההוד למשה וההדר ליהושע שנא' בכור שורו הדר לו כו', וכתי' ונתת מהודך עליו מהודך ולא כל\nהודך, והיינו שההוד הוא העצם וההדר הוא ההתגלו' כו'. וכמו עד\"מ באדם ענין ההוד הוא שזיו הוד פניו יאיר ויתקבל בלב כאו\"א בלא טו\"ד, לפי שהוא עצם ההוד והיופי שאינו בא מאיזה פרטים, וע\"כ אינו שייך בו טעם וידיעה וע\"כ מתקבל בלב כאו\"א כו', משא\"כ ההידור הוא שמהודר בפרטי' שלו, וכמו פרי עץ הדר שצ\"ל מהודר בכל הפרטי' שבו עד שבין כולם הוא הדר, וכן והדרת פני זקן שצריכי' להדרו ולפארו בפרטי עניני כבודו כו', כי ההידור הוא שבא בפרט דוקא וההוד הוא בד\"כ לפי שהוא העצם כו'. וזהו מ\"ש גבי שלמה ויתן עליו הוד מלכות (דה\"י א' כ\"ט כ\"ה), ופי' במצ\"ד שהי' נראה בעיני כל אשר הוא הגון וראוי למלוכה מפאת עצמו. והענין הוא דהנה ידוע דאין מלך בלא עם, א\"כ בחי' ההתנשאו' אינו נמשך ומסתעף רק מן העם שמנשאין אותו עליהם ועושין אותו למלך כמו שום תשים עליך מלך, והוא בכתר מל' שנותנים בראשו ומשתחוים לו שמקבלי' עול מלכותו עליהם כו', ובלא זה לא הי' לו יתרון על שאר אדם זולתו כו'."],[3601330401,"<b>ולמה</b> כשנעשה מלך אימתו גדולה מאלי' שאינה צריכה התבוננות בזה שהוא מלך וקבלו עליהם מלכותו, ולא משום יראת העונש, כ\"א שמאליו וממילא נופל אימתו ופחדו על כאו\"א, והוא מפני ההתנשאו' שלו ודוקא מפני ההתנשאו' עצמי שבו (שנק' יראת הרוממו' כו'). וכנראה בחוש ההפרש בין יראת המלך ליראת השר, דיראת השר הוא רק מצד ההשתררות שהוא מושל עליהם, אבל יראת המלך אינה מצד ההשתררו' כ\"א מצד התנשאו' עצמו ולכן היראה באה בדרך ממילא (אז מיא פארלירט זעך), והיינו שההתנשאות נעשי' בו עצמי וטבעי כאלו בעצם הוא נבדל בערך מכל העם ומרומם ומנושא בעצם כו', עד שכל המורד בו חייב מיתה כמורד באלקי' וכמ\"ש ברך נבות אלקי' ומלך כו', דכ\"ז אא\"ל רק מפני ההכתרה של העם שקבלו אותו למלך, דע\"ה שעי\"ז יהי' בו ההתנשאו' עליהם ה\"ז רק התנשאו' על עם הנק' השתררות כו', דמהתנשאו' זאת לא הי' היראה והביטול בדרך ממילא כו', אבל ענין התנשאו' העצמי שנעשה בעצם מרומם ומנושא ושעי\"ז תהי' היראה ממילא לא תהי' זאת מההכתרה לבד כו'. אך הענין הוא דכאשר קבלוהו למלך נמשך בו\nממדת מל' דלעילא בכתר מל' שלו ועי\"ז הוא ההתנשאו' עצמי שלו כי נעשה מלך בעצם מצ\"ע כו' (ובאמת בעצם יש בו כח המלוכה בהעלם גם קודם שמכתירי' אותו שהוא נשמה כללי' בעצם ויש בו ענין ההתנשאות בעצם כו' וכמ\"ש במ\"א, והוא מה שיש בו בהעלם מבחי' מל' דלעילא וע\"י ההכתרה מתגלה בו הכח נעלם שבו כו'), וכל המורד בו כאלו מורד במל' דלעילא שנק' אלקים חיים ומלך עולם כו'. ולפ\"ז יובן במל' דלעילא בבחי' התנשאו' אלקי' שא\"ז רק מה שנמשך ונלקח מעם נפרד יש מאין וכמו צבא השמים שמשתחוים כו', שהרי אין ערוך לו כלל שזה יעשה התנשאו' כו', כ\"א נק' המלך המרומם לבדו שההתנשאו' היא בבחי' התנשאו' עצמי דוקא, ומה שהוא מתנשא להיות מלך על עם הוא עולם הברי' והיצי' שז\"ש מלכותך מכ\"ע הוא בחי' לבוש וצמצום גדול, וכמ\"ש ה' מלך גאות לבש דגאות זו היא אצלו בבחי' לבוש לבד שמצמצם עצמו כבי' להיות מלך על עם ולקבל מהם כתר מל', וכמו ויתנו לך כתר מלוכה בבחי' ביטול היש שלהם כו', אבל כמו שהוא בעצמו הוא בבחי' המלך המרומם או המלך הקדוש בחי' רוממו' וקדושת עצמי\nכו', וזהו הנק' כבוד מל' וכמו כבוד מלכותך יאמרו כבוד מלכותך העצמי דוקא בבחי' התנשאו' עצמי כו'. והנה בענין כתר מל' שזהו בחי' ההתנשאו' והרוממו' בכלל יש בזה ג\"כ בד\"פ ב' מיני ההתנשאות הנ\"ל והן ב' מדרי' בכתר מל', הא' הכתר מל' שהשרים והעם נותנים על ראש המלך שעי\"ז נעשה מלך עליהם בבחי' התנשאו' והשתררות עליהם כו' כנ\"ל, והב' כתר מל' שיש בו מצד ירושה מאבותיו שהכתר שהי' על ראש אביו ילבש גם הוא ממילא והו\"ע שהכתר הולמתו, וזהו בחי' התנשאו' עצמי שמצ\"ע ראוי הוא למלוכה שז\"ע שהכתר הולמתו כו', וזהו ג\"כ ענין הוד מלכות שראוי בעצם לרוממו' זו וא\"צ להסכמה מזולתו כלל וכלל להיותו מלך בעצם בבחי' רוממו' העצמי כו', וז\"ש גבי שלמה ויתן עליו הוד מלכות שכולם הכירו שהוא הגון למלוכה מצ\"ע מצד עצם ענין ההתנשאו' שבו שבא לו מבחי' מל' דלעילא כו'. וזהו ההפרש בין הוד מל' להדר מל', דהוד מל' הוא מצד העצם, והדר מל' הוא שבא מן העם והיינו בחי' התפשטו' ההתנשאו' על העם, וכמו ברוב עם הדרת מלך דההדור בא מן העם וברוב עם דוקא הדרת מלך כו',\nדהוד מל' אינו תלוי ברוב עם שגם במיעוט עם וגם בלא עם כמו שהמלך בהיכלו יושב על כסא מלכותו יכול להיות הוד מלך בעצם"],[3601330402,"וכמו מלך ביופיו תחזינה כו', אבל הדרת מלך הוא ברוב עם דוקא דהיינו בריבוי התפשטו' דכל מה שירבה העם יותר יותר יהי' בזה הדרת מלך כו', וביותר כאשר הריבוי עם הוא ממינים שונים ומחולקים זמ\"ז דוקא, דכאשר הם ממין א' הגם שהן בריבוי אין בזה הידור כ\"כ כ\"א כאשר מחולקים בריבוי מינים שונים. וכמו חיל המלך כשהוא ממין א' גם אם ירבה כחול הים א\"ז הדרת מלך עדיין רק אם יהיו חלוקים בכמה מינים, וכמו חיל הרוכבים בכמה מיני כלי זיין אלו בחרבות ואלו בקשתות וחצים, וכן בחיל הרגליים ומחולקים במלבושיהם ובתכונתם וכאו\"א עובד את המלך כפי ענינו ולא ישנו את תפקידם, וכאשר יבאו ויתקבצו כולם לכבוד המלך זה בכך וזה בכך אז הוא דוקא הדרת מלך כו'. והיינו כנ\"ל דהוד מלך הוא דבר עצמי שאין בזה התחלקו' כלל, והדר מלך הו\"ע התפשטו' והתגלו' המלוכה, וכל התפשטו' יש בה התחלקו', וההתכללו' מכמה מיני התחלקו' בזה הוא דוקא ההידור כו'. והדוגמא מזה במלכותא דלעילא במ\"ש וכבוד הדר מלכותו שהוא בחי' התפשטו' מלכותו ית' בבחי' התנשאו' על עם שבא בריבוי פרטים,\nוכמש\"א מלך מהולל בתשבחות במיני תשבחות רבות בנשמו' ומלאכים בכאו\"א לפי מדריגתו וכמו משובח ומפואר בלשון חסידיו ועבדיו שהן נשמו' ומלאכי' כו'. ויש בזה כמה חילוקי מדרי' וכמו מחנה מיכאל באה', ויש בו ק\"פ אלף מחנות ומלאך גבריאל ביראה כו', וכן בנשמו' זה עובד באה' וזה ביראה כו', וכידוע בענין ז' נרות דמנורה כו' שיש בזה מדרי' רבות מאד עד אין שיעור כו', ובהתאסף כולם יחד שבטי ישראל למטה ומלאכים למע' לפאר ליוצרם כו', והיינו בכ\"י בעת התפלה שכאו\"א מהלל ומשבח להקב\"ה כפי מהותו ומדריגתו כו' זהו בחי' הדרת מלך כו'. וכ\"ז הוא בבחי' התפשטו' האור, אבל בבחי' עצמו' אוא\"ס כתי' נורא תהלות שיראים להללו כו', ולך דומי' תהלה בבחי' ביטול בתכלית שאין בזה חילוקי מדרי' כלל כו', לפי שזהו בהעצם שאין שם מדרי' כלל וכן בהביטול אין התחלקו' כלל כו', והוא בחי' הוד מל' כו' (וזהו ג\"כ מה שהוד הוא ל' הודאה שאינו שייך בו הילול ושבח כ\"א הודאה לבד, וכמ\"ש ועתה כו' מודים אנחנו לך לעצמותך ומהללים רק לשם תפארתך בחי' אור וזיו ובבחי' התפשטו' כו').\n<span data-k=\"ks\"><b>קיצור.</b> ובה\"ע דכתיב הוד והדר לבשת, הוד עצם האור, והדר התגלות ההוד, וכמו הוד פני אדם הוא מכללות העצמית, והדר הוא שמהודר בהפרטים, וכמו\"כ הוד מלכות הוא שהוא מלך בעצם שנמשך מבחי' מל' דלעילא, ובא לו מאבותיו דהכתר הולמתו, והו\"ע התנשאות עצמו, ומזה הוא עיקר יראת המלך, וע\"כ ישנו גם בלא עם, והדר מלכות הוא ההכתרה וקבלת המלוכה, והו\"ע התנשאות על עם, וע\"כ ברוב עם הדרת מלך, וכמו\"כ למעלה ה' מלך גאות לבש בבחי' התנשאות על העולמות, וההילול דמלאכים ונשמות הוא הדר מלכותו ית', ובחי' המלך המרומם שעז\"נ נורא תהלות, וזהו ג\"כ הוד ל' הודאה. </span>\nקכג) <b>ובזה</b> יובן ג\"כ ענין הוד והדר לבשת שהן ב' מדרי' שבכתר, דהוד הוא בחי' עתיק שזהו בחי' פנימי' הכתר בחי' עצמות אוא\"ס שלמע' מבחי' התפשטו' וגילוי, אדרבה נק' עתיק מל' ויעתק משם בבחי' העתקה והבדלה כו', והדר זהו התגלו' ההוד והוא בחי' א\"א שהוא בחי' לבוש שבו וע\"י מאיר בחי' עתיק כו',"],[3601330403,"ובבחי' זו שייך לשבחו ולפארו ית' בבחי' ידיעת השלילה שעי\"ז יודעים ההפלאה דאוא\"ס כו' וכמשנת\"ל פק\"א, משא\"כ בבחי' פנימי' הכתר שמובדל בערך אינו שייך גם ידיעת השלילה כו'. וגבי משיח כתי' הוד והדר תשוה עליו, דהנה נודע דמשיח זכה ליחידה בחי' פנימי' עתיק וז\"ש ונחה עליו רוח ה' רוחא דעתיקא כו', ונודע ג\"כ דלימוד התו' דמשיח יהי' בבחי' פנימי' התו' שישפיע לכללו' ישראל, ואופן הלימוד יהי' בבחי' ראיית המהות כו' וכמ\"ש במ\"א, וזהו הוד והדר תשוה עליו הוד לעצמותו שיהי' בבחי' ומדרי' פנימי' הכתר, והדר מה שיהי' יכול לגלות בחי' ההוד כו'. וזהו\"ע הוד והדר לבשת דהוד הוא בחי' האור העצמי וג\"ז נק' לבוש להיות שזהו ג\"כ רק בחי' אוא\"ס ולא העצמי כו', וכל אור הוא בחי' לבוש לגבי העצם דהיינו רק גילוי מן העצם שמגלה את העצם אבל אינו בחי' העצם גופא כו', ומה שמגלה הוא רק בחי' מציאו' העצם, וכמ\"ש במ\"א בענין אור וזיו השמש דגוף מאור השמש להיותו עצמי ה\"ה מובדל לגמרי מן האור ואין האור מגלה מהות העצם כ\"א מציאותו כו', ועד\"ז יובן בכללו' בחי'\nאוא\"ס להיותו רק בחי' גילוי לבד ה\"ה בבחי' לבוש כו', ומ\"מ ה\"ה בבחי' גילוי העצם דהיינו דמה שיכול להתגלו' מן העצם ה\"ז מתגלה ע\"י האור, דהרי האור הוא מעין המאור ממש ומה שאפשר להתגלו' מן המאור מתגלה ע\"י האור כו', וזהו לגבי העצמו' שגם ההוד הוא בחי' לבוש, אבל במדרי' דאוא\"ס ה\"ז בחי' אור עצמי כו'. אמנם בחי' ההדר בחי' חיצוני' הכתר שזהו בחי' התפשטו' ההוד ה\"ז בחי' לבוש לבד כו', אך גם בחי' זו ה\"ה בבחי' גילוי העצם ממש ואין בזה שום העלם כלל שהרי אין המשכה זו באה ע\"י איזה צמצום והפסק כ\"א בבחי' גילוי מן העצם לבד, וא\"כ אין בזה שום העלם כו', ונק' לבוש אור שמגלה ממש את האור כו'. וע\"כ עיקר ענין הספירו' והבהירות הוא באוא\"ס שלמע' מאצי' והיינו בבחי' האור שבבחי' א\"ס ובל\"ג שהוא בבחי' גילוי מן העצם ממש, דכל מה שיכול להיות בבחי' התגלו' מהעצם ה\"ז בא בגילוי ממש כו', והו\"ע אור בהיר דעתיק שמאיר ומתגלה ע\"י בחי' א\"א כו'. ולפ\"ז י\"ל פי' ד' בש' ספירה ל' ספר כמו זה ספר תולדות, ספר הברית. דהנה במ\"ב פ\"ב דמגילה אי' עד שתהא כתובה\nאשורית על הספר מבו' דפי' ספר היינו קלף, והענין דהנה ארז\"ל כל אות שאין גויל מוקף לה מד' רוחותי' פסולה הרי שהעיקר הוא הקלף, והיינו כי הדיו הוא רק משחיר את הקלף אבל עיקר האות הוא מהקלף רק שע\"י הדיו מתגלה האות מהקלף, והענין הוא דע\"ה שתמונת האות הוא רק מהדיו הרי בלתי הקלף הנושאו וסובלו לא הי' ממנו שום תמונה כלל, ולכן כל אות שאינו מוקף גויל פסול, וא\"כ הרי הדיו רק משחיר את הקלף בכדי שהקלף יגלה את האות ועיקר מקור האות הוא מהקלף כו', וא\"כ צ\"ל שיש אותי' בהקלף גם מה שאין הדיו משחיר ומגלה ומתגלה רק מצ\"ע כו'. והנמשל מזה הוא שהקלף הלבן זהו בחי' אור הא\"ס הפשוט בתה\"פ כו', והאותי' הן הע\"ס שהן בחי' אורות וכלים והמגלים את האור הן הכלים אבל שרש המשכת האור מהאוא\"ס הפשוט, וזהו כמו עד\"מ הקלף הלבן שנושא וסובל האותיות כו', כמו\"כ גילוי בחי' האור הוא מאוא\"ס ב\"ה רק שי\"ל שזהו בחי' או\"פ והיינו מה שאוא\"ס שיער בעצמו להאיר בבחי' מדה וגבול כו', דבחי' זו אינו בבחי' גילוי מן העצם ממש (שהרי ענינו הוא להאיר והוא ע\"י הצמצום\nכו'), וכ\"ש שע\"י הכלים אין האור מתגלה כמו שהוא ממש כו'. אמנם כמו\"כ יש גילוים מבחי' אוא\"ס הפשוט שלא ע\"י הכלים דבחי' זו היא בבחי' ספר היינו בבחי' ספירו'"],[3601330404,"ובהירות ממש שהוא בבחי' גילוי מן העצם ממש כו', וזהו משארז\"ל שהתו' ניתנה באש שחורה ע\"ג אש לבנה, דכללו' ענין אש הוא בחי' האור וכמשנת\"ל פצ\"א, ואש שחורה הן הע\"ס דאצי' שהגילוי הוא ע\"י הכלים כו' (וגם י\"ל שהאור נק' ג\"כ אש שחורה מפני שבא ע\"י הצמצום שהוא ג\"כ בדוגמת כלי כו', וכמשנת\"ל פצ\"ד), וזהו ספירה מל' ספור והגדה כו', ואש לבנה הוא בחי' האור והגילוי דעצמו' אוא\"ס הפשוט בתכלית והו\"ע ספירה מל' ספיר וספר כו' (ובד\"פ בתורה י\"ל שזהו בחי' חיצוני' ופנימי' שבתו' או בחי' רזין דרזין כו', גם י\"ל שז\"ע מ\"ע ומל\"ת כו').\n<span data-k=\"ks\"><b>קיצור.</b> וכמו ב' המדרי' בכתר מל', כ\"ה בבחי' כתר הוד בחי' עתיק, והדר בחי' אריך שע\"י מאיר הארת עתיק, ושייך בזה ידיעת ההפלאה, משא\"כ בעתיק, ומשיח יגלה עצם בחי' ההוד, ובחי' הוד הוא ג\"כ לבוש לגבי העצמות, אמנם זהו עצם האור, והדר הוא רק התגלות ההוד, אך מגלה כל מה שמאיר ומתלבש בו, ועפ\"ז י\"ל ספירה ל' ספר, וכמו האותיות שמעצם הקלף, כמו\"כ הגילוים מעצמות אוא\"ס הו\"ע ספיר וספר. </span>\nקכד) <b>ועפ\"ז</b> יובן איך ששייך ספי' גם בהאור א\"ס הבל\"ג, דלפי הפי' דספי' הן ל' ספירו' ובהירות הרי עיקר ענין זה שייך באוא\"ס הבל\"ג שהוא בבחי' גילוי מן העצם ממש כו', וזהו\"ע ספי' שבאוא\"ס היינו בבחי' התפשטו' האור, וכנ\"ל בענין הוד והדר דהוד הוא עצם האור והדר הוא בחינת התפשטו' האור שהוא בחי' לבוש כו', אך הוא בחי' לבוש אור שמגלה את העצם לפי שגם ההתפשטו' הוא בבחי' גילוי העצם כו', ולהיותו בחי' התפשטות שייך שם ענין ספי' דהיינו בחי' התגלו' האור שז\"ע ספירה כו'. ובפרט לפמשנת\"ל פקכ\"ב דהדר הוא שבא בריבוי פרטי' הנה הפרטים שבהתפשטות ז\"ע הספי' כו', והיינו כידוע בענין אנת הוא חד ולא בחושבן דלהיותו חד בעצם (דהיינו בחי' עתיק) גם ההתפשטות (שזהו בחי' אריך) שבא בריבוי מדרי' הוא לא בחושבן כו', וכמ\"ש בבי' מאה\"ז ע\"פ ויהיו חיי שרה מאה שנה, והכל הוא בבחי' א\"ס והיינו שהספי' הן בבחי' אין קץ ושיעור בריבוי שלהם שז\"ע ולא בחושבן כו', וגם בעצם הן בבחי' אין קץ היינו בבחי' א\"ס מאחר שזהו התגלות העצם ממש כו'. והענין הוא\nדהנה נת\"ל פק\"א בענין ידיעת השלילה דש' חכם באוא\"ס הוא רק לשלול ההיפך מזה וא\"כ זהו חכ' רק שמושלל לגמרי מבחי' החכ' דס' השתל' כו', וכן שם יכול וכה\"ג, ונת' שם דכ\"ז אינו מדרי' באוא\"ס כ\"א הוא הפלאת אוא\"ס ב\"ה בענין החכ' ובענין היכולת וכה\"ג. וביאור הענין י\"ל ע\"ד מ\"ש במ\"א ע\"פ השיטה שהאורות הן פשוטי' לגמרי, מה שנק' אור החכ' ואור הבינה כו' א\"ז שהאור הוא בבחי' חו\"ב דהאור בעצם הוא פשוט ואין לו יחוס אל החכ' יותר מאל הבינה, רק שהאור הוא הארת המאציל ב\"ה להאציל ספי' החכ' (שהיא הכלי), וכשנאצלה ספי' החכ' האור מתלבש בתוכה להחיותה ונק' אז אור החכ' ע\"ש הכלי שעושה תמונה וגוון בהאור כו' (וג\"ז אינו נקנה בהאור רק שנראה כן בהאור עד\"מ המים שמשתנים לפי גוון הכלי כו' כנודע), ולפ\"ז הרי האור המהווה את החכ' יכול להוות את הבינה שמצד פשיטו' האור אינו שייך אל החכ' ויכול להיות שאותו האור עצמו יהווה את הבינה ויתלבש בתוכה כו', רק כאשר כבר נתהווה החכ' ונתלבש האור בתוכה ה\"ה בבחי' חכ' (היינו שנראה כן כנ\"ל)."],[3601330405,"<b>וא\"כ</b> מכ\"ש שי\"ל כן באוא\"ס הבל\"ג שהאור הוא בבחי' פשיטו' ממש, הרי אינו בגדר בחי' חו\"ב כו', וא\"כ מה שאנו אומרי' שהוא מ\"מ חכם ויכול (חכם בחכ' ויכול בבינה כו') הרי אותו האור ממש שהוא בבחי' חכ' הוא ג\"כ בבחי' יכולת וכו', שהרי באוא\"ס לא יש בחי' הכלים וזהו שאינם בבחי' חיוב כ\"א בבחי' שלילה היינו שאינם בבחי' מהות ומציאו' דבר כלל כו', וא\"כ אותו האור שהוא בבחי' חכ' הוא ממש גם בבחי' היכולת כו'. וזהו שאינם בבחי' מדרי' באוא\"ס כ\"א הפלאת אוא\"ס בענין החכ' והיכולת כו', והיינו שהאוא\"ס שהוא מופלא בבחי' החכ' ה\"ה מופלא גם בבחי' יכולת וכה\"ג, ובעצם הוא בבחי' פשיטו' העצמו' כמו שהוא כו'. וז\"ע שהספי' שבאוא\"ס הן בבחי' אין קץ שהן בעצם בבחי' א\"ס, דענין הספי' הוא רק התגלו' העצמו' ממש וא\"כ ה\"ה בבחי' הפשיטו' דאוא\"ס ב\"ה כו' (תוכן הענין הנ\"ל הוא דכמו בהאו\"פ (להשיטה שהוא בבחי' פשיטו' ממש) קודם שמהווה את הכלים, כ\"ה בהאור הא\"ס גם כמו שאנו אומרים בו שהוא חכם ויכול כו', לפי שאינו בא בבחי' כלים ובבחי' מציאות דבר כו').\n<span data-k=\"ks\"><b>קיצור.</b> וזהו ששייך ספי' גם באור הא\"ס שהו\"ע בהירות גילוי העצם שזהו דוקא באוא\"ס, ולהיות שזהו התפשטות אור ע\"כ יש שם ספירות רק שהן עד אין קץ ובעצם הן בבחי' א\"ס, והענין הוא דלהשיטה דהאורות פשוטים לגמרי הרי האור המאציל את החכ' יכול להאציל את הבינה, כ\"ש שהוא כן באוא\"ס הבל\"ג דאוא\"ס שהוא מופלא בבחי' החכ' ה\"ה מופלא בבחי' היכולת וכה\"ג. </span>\nקכה) <b>אמנם</b> עדיין צ\"ל מ\"ש בע\"ח שיש ע\"ס דעיגולים איך הם מספר עשר, שהרי לפמשנת\"ל באוא\"ס הבל\"ג הן ספי' עד אין קץ וגם הספי' עצמן הן בבחי' אין קץ ואיך שייך שם מספר ע\"ס, ומאחר שהן ע\"ס הרי לכאורה בהכרח לומר שהן במדרי' מחולקו' דאל\"כ אינו שייך מספר עשר כו', ובאמת אינו שייך לו' באוא\"ס הבל\"ג מדרי' מחולקו' כו', וכמשנת\"ל פרק פ\"ב שגם מיעוט וריבוי אינו באמת באוא\"ס הבל\"ג, וכ\"ש שאין התחלקו' מדרי' וכנ\"ל שהן בבחי' אין קץ בעצמן כו'. אך הענין הוא דהנה נת\"ל פנ\"ו דאור הא\"ס להיותו בבחי' גילוי מן העצם אינו בו שום שם כלל רק כמו שבא בבחי' מקיף לעולמו' ה\"ה נק' בש' רצון כו', והנה הרצון הגם שהוא רק בבחי' מקיף לבד מ\"מ מאחר שנעשה בבחי' מקיף אל האו\"פ ה\"ה בבחי' קירוב ושייכות אל האו\"פ והארה ממנו בא בבחי' התלבשו' בהאו\"פ כו', רק שאופן התלבשותו א\"ז שנתפס בהאור לבוא בבחי' הגבלה (וכמו האו\"פ שע\"י ההתלבשו' בהכלי ה\"ה בבחי' תפיסא שנעשה כמהות הכלי, וכמשנת\"ל פי\"ד בענין ח\"ס וחכ' הגלוי' דבחי' חכ' הגלוי' ע\"י התפיסא בכלי נעשה\nבבחי' מהות חכ' עד שח\"ס היא למעלה מן החכ' לגבה כו', ובהאו\"מ אינו כן), אלא שגם בהתלבשותו בהאו\"פ ה\"ה כמו שהוא בבחי' בל\"ג כו'. והענין הוא דהנה נת\"ל פ\"נ דהרצון הוא בבחי' מקיף על כל אברי הגוף ועל הכחות ופועל בהם בשוה באור המוחין שבראש כמו בכח ההילוך שברגל כו', ומ\"מ הרי ברגל הוא בבחי' מקיף לבד, משא\"כ במוחין הרי לבד מה שפועל בהם בבחי' מקיף (היינו שמכריח התגלו' אור המוחין כו' וכמשנת\"ל פנ\"א), ה\"ה בא ג\"כ בבחי' פנימי שהרצון בא בשכל להיות טעם לרצון כו', וזהו רק בבחי' הארת הרצון דעצם הרצון הרי אין טעם לרצון"],[3601330406,"כו', אבל הארת הרצון בא בבחי' טעם לרצון כו', וכמו התורה שהוא פי' וביאור המצות דבמצות הן רצה\"ע והתו' בא בבחי' טעם וביאור אל הרצון כו', ועי\"ז יש התחלקו' בהרצון וכמו קלות וחמורות שיש חילוקי' בהמצות מצד הטעם כו'. ובאמת הרצון גם כמו שמתלבש בהטעם הוא בעצם בבחי' בל\"ג שהרי אין הטעם סיבת הרצון, והיינו דהרצון דמצות אין סבתם מצד הטעם כ\"א שהן רצון באמת, וע\"כ גם לאחר פי' וביאור המצוה ע\"פ התו' הנה כשעושה את המצוה כמו שהיא ע\"פ התו' ה\"ה מקיים את הרצה\"ע ונמשך עי\"ז בחי' הרצון כו', ובכוונת המצוה לבד או בלימוד טעמה וסודותי' אינו יוצא כלל כ\"א בקיום המצוה בפו\"מ (לבד במצות שאפשר לעשותן ע\"י אחרים אין מבטלין ת\"ת והיינו במצות שאינן חובת הגוף כו'), וכן בעשיית המצוה לא די בכוונת המצוה כ\"א צריך לעשותה בבחי' קבעומ\"ש דוקא וכמ\"ש בסש\"ב פמ\"א ב' כוונות בעשיית המצוה כו', דקבעומ\"ש הוא מצד הרצון כו', והיינו דגם כמו שבאה המצוה בבחי' טעם לרצון מ\"מ ה\"ה בבחי' רצון באמת כו', והיינו משום דע\"ה שמשיג את הרצון, מ\"מ אין הרצון נתפס בזה\nלהיות בבחי' שכל וטעם כ\"א הוא בבחי' רצון באמת כו', ולכן מצד הרצון שבמצות לא יש באמת קלות וחמורות וכמארז\"ל אל תהי יושב ושוקל במצותי' ש\"ת כו' (וגם באמת אין הטעם תופס בעצם מהות הרצון, וכמ\"ש במ\"א בענין דכסות סומא חייב בציצית וכסות לילה פטור דמצד הטעם יכולים לומר טעם להיפך ג\"כ רק מפני שכ\"ה הרצון, וכ\"ה בכמה מצות שאין הטעם לבדו מספיק כו', והיינו לפי שענין הטעם הוא רק להיות קצת מושג בהרצון אבל לא שהרצון נתפס בזה כו'). והנה הרצון שבא בבחי' חכ' להיות בבחי' טעם לרצון זהו בחי' התפשטו' וגילוי הרצון לבד, והיינו בחי' המל' שבכתר ובחי' המדות שבו, וכידוע דבחי' מל' הו\"ע הגילוי לבד וכן ענין המדות הו\"ע התפשטו' וגילוי כו', וכידוע דכל ענין המדות הן לזולתו, שזהו ההפרש בין המוחין אל המדות דמוחין הן לעצמן עדיין אבל המדות הן אל הזולת כו'. וכמו\"כ בבחי' הכתר ההתפשטו' והגילוי אל הנאצלי' הוא בחי' מדות ומל' שבכתר והוא בחי' רצון גלוי כו', אמנם ידוע שיש בחי' חכ' שבכתר הנק' ח\"ס שזהו בחי' טעם כמוס לרצון כו', דבחי' ח\"ס ה\"ז\nלמע' מן החכ' והטעם לגבי חכ' הגלוי' וכמשנת\"ל באורך, והוא בבחי' המשכה נעלמת כו', ונת\"ל פצ\"ו דענין המשכה נעלמת הוא דעם היותו מושלל מן הגילוי היינו מן המציאו' דחכ', מ\"מ אינו מושלל לגמרי מגדר וענין החכ' כו' ונק' חכ' נעלמה כו', ובבחי' זו מתלבש בחי' הרצון הנעלם שלמע' מבחי' רצון הגלוי בחכ' כו', והיינו דבחי' הרצון שהוא למע' מן הטעם לגמרי בבחי' חכ' הגלוי' יש ע\"ז טעם בבחי' חכ' הנעלמה, וכענין שתוק כך עבמ\"ח בבחי' הרצון המתלבש בחכ' הנעלמה שלמע' מן הטעם לגבי חכ' הגלוי' כו', דלגבי חכ' הגלוי' הוא בבחי' מקיף לבד כמו רצון בלא טעם כו'. וכ\"ז הוא בבחי' הרצון הבא בגילוי אם בבחי' גילוי אל הנאצלי' שמתלבש בבחי' חכ' הגלוי' או בבחי' גילוי לעצמו עדיין שזהו בחינת הרצון שמתלבש בח\"ס כו', אמנם עצם בחי' הרצון הנעלם לגמרי שאינו בא בבחי' גילוי כלל, זהו בחי' כשב\"כ דהיינו בחי' פשיטות הרצון שאין טעם לרצון כלל גם לא בחי' טעם כמוס לרצון, ואינו בא בבחי' הגילוי גם לעצמו כ\"א הוא בבחי' רצון נעלם לבד כו'. וזהו\"ע מ\"ש בע\"ח בע\"ס\nדעיגולים די\"ל שאין הכוונה שיש ע\"ס ממש בבחי' האו\"מ, כי הוא בבחי' א\"ס ובל\"ג, וגם הספי' שבו הן בבחי' אין קץ לספירו' וכמשנת\"ל, רק מצד התגלו' והתפשטו' הרצון בהספי' עש\"ז אנו אומרים"],[3601330407,"ע\"ס בהאו\"מ, דבחי' הרצון הגלוי שמאיר בבחי' חכ' דאצי' נק' בחי' מדות ומל' שברצון כו' כנ\"ל להיותם בבחי' התפשטו' וגילוי כו'. וגם נודע דאו\"א מלבישי' לזרועות דא\"א היינו בחי' חו\"ג דאריך (ומבינה דאריך נעשה כתר לאו\"א) כמ\"ש בע\"ח, וע\"כ גם בחי' הרצון (היינו בחי' האור הא\"ס) המתלבש באו\"א נק' מדות כו', ומה שמתלבש בבחי' ח\"ס דאריך דהיינו בחי' הגילוי לעצמו עדיין נק' בש' חכ' והו\"ע עיגול החכ' ועיגול הבינה וכן עיגול החסד כו', דכ\"ז הוא רק ע\"ש ההתלבשו' לבד כו', וגם כמו שמתלבש ה\"ז בבחי' א\"ס ובבחי' פשיטות כנ\"ל. אמנם עצם בחי' הכתר זהו בחי' כתר שבכתר שזהו בחי' הרצון הנעלם והפשוט שאינו בא בבחי' גילוי כלל והוא בבחי' פשיטו' העצמו' כו'.\n<span data-k=\"ks\"><b>קיצור.</b> אמנם מ\"ש בע\"ח ע\"ס דעיגולים הענין הוא עד\"מ הרצון הוא בחי' מקיף ובא ג\"כ בבחי' פנימי בחכ', ועי\"ז בא בהתחלקות, ומ\"מ הוא רצון בעצם ובלי התחלקות, וכמו הרצון דמצות שבא בטעם בתורה, ומ\"מ המצות הן רצון ואין בהם התחלקות דקלות וחמורות, כמו\"כ למעלה בחי' מדות שבכתר באים בבחי' פנימי בחו\"ב, ורצון הנעלם מתלבש בח\"ס, ועש\"ז נק' גם בבחי' הכתר חכ' ומדות, והן בבחי' א\"ס בעצם, וז\"ע ע\"ס דעיגולים, אך כשב\"כ שאינו בא בהתלבשות הוא בבחי' פשיטות לגמרי. </span>\nקכו) <b>וע\"פ</b> כל הנ\"ל יובן משנת\"ל בתחלת הדרוש בג' פי' שבכתר, ל' כתר לי זעיר דענינו שתיקה, ול' כתר ועטרה בחי' או\"מ, ול' מכתיר שהוא סיבוב כל האצי' בתוכו והו\"ע תר\"ך העמודים כו'. דהנה המבואר מכל משנת\"ל הוא שיש ב' מדרי' בכלל בהתגלו' אוא\"ס ב\"ה, הא' בחי' אור הפנימי שהוא להאיר את העולמו' כו' ושרשי האורות עד רום המעלות כו', והב' האור שבבחי' א\"ס שהוא בבחי' גילוי מן העצם כו'. ובזה גופא יש ב' מדרי', הא' כמו שהוא מובדל מהאו\"פ לגמרי, והב' כמו שבא בבחי' מקיף לעולמו' והשתל' כו'. וזהו ג' ענינים הנ\"ל שבכתר דענין סיבוב האצי' בתוכו היינו בחי' שרש האו\"פ הכלול בהאור הבל\"ג, והוא מה שאוא\"ס שיער בעצמו להאיר בבחי' מדה וגבול שנת\"ל פכ\"ז שזהו בחי' מל' שבא\"ס כו', ובחי' כתר ועטרה זהו בהאו\"מ עצמו היינו בהאור שבבחי' א\"ס רק זהו כמו שבא בבחי' מקיף עכ\"פ כו', ובחי' כתר לי ושתיקה הוא כמו שלמעלה גם בבחי' מקיף לעולמו' כו'. אמנם י\"ל כל אלו הג' מדרי' הכל בבחי' אור הא\"ס כמו שבא בבחי' מקיף כו' (שגם בחי' שתיקה א\"ז בבחי'\nעצמו' הכתר ממש היינו בבחי' פנימי' הכתר כ\"א בבחי' הרצון כו'), דהנה אור הא\"ס עם היותו בבחי' גילוי מן העצם מ\"מ ה\"ה בא בבחי' מקיף לעולמו', דאז יש לו עכ\"פ שייכו' לעולמו' והשתל' שבא בבחי' התלבשו' בהשתל', ומ\"מ הוא בבחי' א\"ס כו' וכנ\"ל, ונת' שיש בזה ג' מדרי', הא' כמו שמתלבש הרצון בחכ' דאצי' והוא בחי' רצון גלוי כו', והב' בחי' רצון נעלם שמתלבש בחכ' נעלמה והוא בבחי' מקיף לגבי אצי' כו', והג' בחי' עצם הרצון שאינו בא בגילוי כלל כו', וז\"ע ג' מדרי' הנ\"ל. דהנה תר\"ך עמודי אור הן מה שנמשך מן הכתר אל הנאצלי' והוא בחי' רצון הגלוי כו', וכמ\"ש הפרד\"ס שע\"ח פ\"ג בשם ר' נחוניא בן הקנה בתפלתו אקראך בתר\"ך עמודי אור שהם ראש מילולך שהם תיקון לרום מעלתך כו', ופי' אקראך קריאה והמשכה שהוא ההשפעה מהכתר,"],[3601330408,"שהם ראש מילולך, פי' תחלת התגלו' הא\"ס כו' שהם תיקון כו', כענין שהע\"ס הם תיקון המאציל כו' כמשנת\"ל פק\"ו, כן פי' הפרד\"ס שם (ושם שהתר\"ך עמודים יש בהם פנימי וחיצון ומבו' במ\"א שזהו בחי' או\"פ ואו\"מ כו', ושם דאור המקובל להם ממעלה הוא או\"מ כו'), וזהו בחי' הרצון הגלוי כו'. וענין בחי' כתר ועטרה הוא בחי' רצון הנעלם דעם היותו בא בבחי' טעם כמוס מ\"מ ה\"ז בבחי' מקיף לגבי בחי' חכ' דאצי' כו' (ועמ\"ש בהבי' לד\"ה אוסרי לגפן בענין מקיפי הראש ומקיפי הגוף ג\"ר וז\"ת, ושם דכללו' כולם מעטרת כו' י\"ל ז\"ע המקיף הנ\"ל). וענין כתר לי זעיר בחי' שתיקה זהו בחי' כשב\"כ בחי' הרצון הנעלם לגמרי שז\"ע שתיקה שלמע' מבחי' גילוי כו', וע\"ה שכ\"ז הוא בבחי' מקיף להשתל' מ\"מ בחי' זו הוא עצם פשיטו' הרצון כו'.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש ולא יכול יוסף להתאפק, דהנה אי' בפע\"ח בכוונת ויעבור שאומרי' אחר שים שלום שז\"ע בקיעת היסוד דברכת שים שלום הוא ביסוד, ומפני עוצם האור והגילוי נבקע היסוד והו\"ע גילוי יגמה\"ר כו', וכנודע בכוונת אל עליון כו' קונה הכל דקונה הכל הוא בחי' יסוד, ומה שאל עליון קונה הוא גילוי בחי' עצמו' אוא\"ס ביסוד שעי\"ז נעשה בקיעת היסוד כו'. וז\"ע ולא יכול יוסף להתאפק דכאשר מאיר ביסוד בחי' האוא\"ס שבבחי' בל\"ג כו', לא יכול להתאפק שנבקע היסוד ומאיר האור בגילוי כו', ויקרא הוציאו כל איש מעלי ע\"ד וכל אדם לא יהי' באה\"מ, והיינו שזהו גילוי שלמע' מכל ההשתל' דאו\"פ גם בבחי' שרשי האורות כו'. וענין ולא עמד איש אתו היינו שהגילוי הוא בנש\"י לבד להיות שהגילוי הוא מבחי' עצמו' הכתר בחי' עצמו' הרצון כו', דהנה מצד המקיף הרי כחשכה כאורה כו', וזהו בבחי' חיצוני' המקיף אבל בפנימי' המקיף הכוונה הוא דוקא בנש\"י ולהם הוא דוקא ההמשכה כו', וזהו ולא עמד ע\"ד הוא ולא אחר כו'. וז\"ש בזהר הה\"ד ביום השמיני עצרת תהי' לכם\nדאי' ע\"ז במד\"ר הה\"ד יהיו לך לבדך ואין לזרים אתך וזהו לכם בא ונגלגל אני ואתה כו'. וזהו ולא יכול יוסף להתאפק שהי' הגילוי מבחי' האור שבבחי' א\"ס ובל\"ג בחי' עצמו' המקיף כו', ויקרא הוציאו כו' שזה למעלה מכל סדר השתל', ולא עמד איש אתו בהתודע שהגילוי הוא לנשמות ישראל דוקא, וכמ\"ש יהיו לך לבדך ואין לזרים אתך כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ובכל הנ\"ל יובן הג' פי' בכתר, סיבוב האצי' בתוכו הוא בחי' שרשי האורות הכלולים באוא\"ס, עטרה הוא בחי' אור א\"ס שבא בבחי' מקיף, ושתיקה הוא שלמעלה מבחי' מקיף, ובפרטיות באוא\"ס י\"ל שזהו בחי' רצון הגלוי שמתגלה באצי', והו\"ע תר\"ך עמודי אור, ורצון הנעלם שמתלבש בח\"ס ובבחי' מקיף לגבי חכ' דאצי', ועצם פשיטות הרצון. וע\"פ הנ\"ל יובן מ\"ש ולא יכול יוסף להתאפק שע\"י הגילוי דאוא\"ס נבקע היסוד, ולא עמד איש אתו שהגילוי הוא רק לנש\"י. </span>"],[3601330409,"<h3>בס\"ד. ליל א' דחה\"ש, תער\"ג</h3>\n<b>ועשית</b> חג שבועות לה' אלקיך מסת נדבת ידך אשר תתן, וצ\"ל מהו\"ע נדבת ידך הלא נדיבות שייך אל הלב, וכן בתורה מייחס נדיבות אל הלב וכמ\"ש כל נדיב לבו יביאה, והיד שייך רק למעשה להיות עשי' בפועל, וא\"כ מהו אומרו נדבת ידך ומפני מה נא' זה גבי חה\"ש דוקא. גם צ\"ל מפני מה נק' יו\"ט זה בשם חה\"ש, הלא השבעה שבועות כבר ספרו מקודם ויום החג אינו במנין הז' שבועות, וכמ\"ש וספרתם לכם ממחרת השבת כו' שבע שבתות תמימות תהיינה עד ממחרת השבת כו', והן המ\"ט יום שסופרים קודם וחה\"ש הוא היום החמשים, וא\"כ למה נק' חה\"ש. והנה במנין הז' שבועות נא' בפסוק וספרתם ב' סימנים ע\"ז, ממחרת השבת ומיום הביאכם את עומר התנופה היינו מיום הבאת ותנופת העומר, וכאן קודם פסוק ועשית חג שבועות נא' שבעה שבועות תספר לך מהחל חרמש בקמה כו', והיינו משעת קצירת העומר, וצ\"ל מפני מה נא' שם שהספי' היא מההובאה ותנופה וכאן נא' מהקצירה כו', גם מהו\"ע מהחל חרמש בקמה כו'. גם צ\"ל משארז\"ל בשעה שהקדימו ישראל נעשה לנשמע ירדו מה\"ש וקשרו להם שני כתרים כו', וצ\"ל בזה\nוהלא מצינו שיש ג' כתרים וכדאי' במשנה דאבות ג' כתרים הן, כתר תו', כתר כהונה, וכתר מל', ולמה קשרו להם רק שני כתרים כו'. ובמשנה דאבות גופא צ\"ל הלא בפרטי' חושב ד' כתרים, וכמ\"ש אח\"כ וכתר ש\"ט עולה על גביהן והול\"ל ד' כתרים הן, ולמה או' ג' כתרים כו'.\nקכז) <b>ומעתה</b> צ\"ל מהו\"ע הג' כתרים כתר תו' כתר כהונה וכתר מלכות, והענין הוא דהנה מהמבו' לעיל מובן דבכללו' ההמשכות והגילוים מא\"ס ב\"ה יש ב' מיני המשכות, הא' ההמשכה שהיא בבחי' א\"ס ממש, והב' ההמשכה שבבחי' גבול ומדה. והנה ההמשכה שבבחי' גבול ומדה הוא הקו הנמשך מאוא\"ס ב\"ה שנמדד ונגבל לפי אופן העולמו' ובא בבחי' מדה וגבול כו', דכפי רצונו ית' באופן ההשתל' שיהיו ע\"ס עשר ולא תשע עשר ולא אחד עשר, וספירו' אלו דוקא שהן בחי' חב\"ד חג\"ת נהי\"ם, כן נמדד הקו ג\"כ במדידה זאת שיש בו ג\"כ ע\"ס אלו, כי כללו' האור הזה הוא לצורך העולמו' דמאחר שהוא מה שבא במדה וגבול ה\"ז רק לצורך העולמו', ולולא הרצון בעולמו' אינו שייך כלל המשכת אור זה, וע\"כ כפי רצונו ית' בענין העולמו' וההשתל' כ\"ה המדידה בהאור שיש בו הע\"ס כו'. דמדידה זו היא בהאור הזה בתחלת המשכתו בשרשו ומקורו, והיינו דהמדידה וההגבלה שבהקו א\"ז מה שנתחדש בו ע\"י הצמצום, כ\"א דבתחלת המשכתו יש בו מדידה זו, והוא שגם בשרש ומקור האור כמו שהוא לפה\"צ יש בו ג\"כ ע\"ס והן\nהע\"ס הגנוזות במאצילן כו', ונק' גנוזות שהן גנוזות ונעלמות בהאור שבבחי' א\"ס ובל\"ג, והוא מה שאור הא\"ס שיער בעצמו להאיר בבחי' מדה וגבול כו', אך שם המה בתכלית הפשיטות לגמרי שאינם בבחי' מציאו' ניכרות כלל והן שם בתכלית האחדות כו'. והמשכת הקו מהע\"ס הגנוזות הוא ע\"י הצמצום דענין הצמצום בזה הוא להיות ספי' מיוחדות, וכמו שספי' החכ' תהי' ספי' מיוחדה בפ\"ע וכן כל הספי' ועי\"ז נעשים בבחי' מציאות ניכרות כו'. ומ\"מ גם בזה הן עדיין בבחי' בלי מה וכמ\"ש בס\"י ע\"ס בלי מה דגם כמו שהן ע\"ס ה\"ה בלי מה עדיין כו', כי הקו ידוע שהוא עשוי מנקודות, והיינו"],[3601330410,"שאינו בבחי' אורך הנמשך מלמעלמ\"ט כ\"א הוא בבחי' נקודות, והן הספי' פרטי' שבהקו דכל ספי' הוא בבחי' נקודה כו', וכל נקודה ה\"ה בבחי' פשיטו' שאין בה ציור עדיין כו'. והנה לפעמים מצינו דנקודה היא אדרבה בבחי' תוקף המציאו' ביותר, כמו בספי' דתהו שהיו בבחי' נקודות שזהו ג\"כ בחי' העצמי' דכל ספי' כנודע, הרי היו בבחי' תוקף ביותר כו', הנה זו כאשר הנקודה באה בבחי' כלים ה\"ה בבחי' תוקף המציאו' ביותר, אבל כשאינה בבחי' כלים ה\"ה בבחי' פשיטו' כו', וכמו בעקודים שהעשר אורות עקודים בכלי אחד ה\"ה בבחי' פשיטות, דמשו\"ז ביכולתם להיות בכלי אחד עם היותם עשר אורות כו' כמ\"ש בע\"ח, וכ\"ש באור הקו שאין שם בחי' הכלים הרי האורות הן בבחינת פשיטות כו', וזה גופא הוא מפני שענין הקו הוא רק לגלות מן ההעלם ולא כמו ספי' דתהו ששם הכוונה הי' להיות בבחי' מציאו' שזהו לצורך איזה כוונה כמ\"ש במ\"א, וע\"כ באו בבחי' כלים כו', משא\"כ בהקו הכוונה הוא רק התגלו' הספי' מהעלמם דע\"ס הגנוזות כו', וע\"כ אין שם כלים והן בבחי' פשיטות כו', וכאשר האורות נתלבשו\nבכלים דאצי' נעשו בבחי' מציאות אור בחי' אור החכ' ואור החסד כו'. ויובן כ\"ז עד\"מ בנפש האדם הרי הכחות הן בגדרים מיוחדים ומחולקים זמ\"ז דכח החכ' הוא בגדר מיוחד וכח הבינה בגדר מיוחד וכן כח החסד כו', ועם היותם כחות נפשי' ה\"ה מ\"מ בגדרים מיוחדים ומוגבלים כו', והנה הנפש הוא עצם אחד רוחני פשוט ומופשט מגדר ציור ומגדר הגבלה כו', ואיך יהיו מהנפש כחות מוגדרים ומוגבלים דגם מהארת הנפש א\"א שיהיו כחות מוגבלים כו', ומ\"מ הרי הנפש פועלת ע\"י הכחות, שמתחכם ע\"י כח החכ' ומתחסד ע\"י כח החסד כו'. אך הענין הוא כמ\"ש בסש\"ב פנ\"א שתרי\"ג מיני כחות כלולים בנפש, דעם היותו עצם א' פשוט נמצאים כלולים בו תרי\"ג כחות שהן מקורי הכחות הגלוים כו', וא\"כ הכחות הכלולים בנפש הן כמו ממוצעים בין עצם הנפש ובין הכחות הגלוים כו', ומאחר שהן בבחי' ממוצע צ\"ל שיש בהם ב' מדרי', והוא כמו שהן לגבי הנפש וכמו שהן לגבי הכחות הגלוים כמו בכל ממוצע כו' כנודע, והיינו דכמו שהן לגבי עצם הנפש ה\"ה משתוים אליו שהן בבחי' פשיטות ממש בערך פשיטו' עצם הנפש כו',\nוכמו שהן לגבי הכחות ה\"ה בבחי' פשיטות רק לגבי הכחות, דגם שם הן בבחי' פשיטו' רק שזהו רק הפשיטו' מבחי' המציאות דהכחות לא בבחי' פשיטות ממש. וכמו כח המשכיל שהוא מושלל ממציאו' שכל ומ\"מ הו\"ע שכלי שאינו מושלל מגדר ענין השכל לגמרי כו', אבל כח השכל ההיולי העצמי הנטוע ומושרש בנפש הוא מושלל מגדר ענין השכל לגמרי, דעם היותו כח השכל היינו רק בערך פשיטות עצם הנפש שמושלל לגמרי מגדר השכל כו', וזה גופא היא הסיבה דהכח השכל כמו שהוא כלול בנפש שאינו בבחי' המשכה עדיין ה\"ה בבחי' פשיטו' לגמרי, וכמו שבא בבחי' המשכה נעלמת הפשיטו' שלו הוא רק לגבי מציאות הכח הגלוי כו'. והדוגמא מזה יובן למע' דע\"ס הגנוזות הכלולים באוא\"ס ב\"ה ה\"ה בבחי' פשיטות ממש כו', וכמו שבאו בבחי' הקו ה\"ה ג\"כ בבחי' בלי מה כו', והוא בחי' הפשיטו' לגבי ע\"ס הגלויות שהן בבחי' התלבשות אורות בכלים כו'. ומובן מזה דע\"ה דעיקר המציאו' של האורות הוא ע\"י הכלים שע\"י ההתלבשות והתפיסא בהכלים נעשים כמהות הכלים כו', מ\"מ האורות עצמן הן ג\"כ בבחי' מציאו' ע\"ס כו' (ויש\nבהם התחלקות מעומ\"ט בעצם מהותן כו'), וזהו הסבה שבאים בבחי' התלבשות בכלים כו', ובסוף המשכתן (היינו בהתלבשותן בהכלים) נתגלה בחי' המציאו' וההתחלקות שבהם"],[3601330411,"בעצם כו', וע\"י הכלים נעשו כמהות הכלים לפעול כפי אופן הכלי כו'. אמנם ההמשכה שבבחי' א\"ס הוא מה שבא בבחי' גילוי מן העצם, והיינו שענינו אינו לפעול דבר כמו פעולת האור והגילוי כ\"א הוא בבחי' גילוי מן העצם לבד והוא כמו העצם כו', דבאמת אינו שייך בזה שום שם כלל רק שם א\"ס, וכמו שבא בבחי' גילוי בעולמות (דהיינו בחי' התפשטו' שלו כו') ה\"ה נק' בש' רצון שהוא גילוי העצמו' כו', וכמשנת\"ל פמ\"ט דכח הרצון חלוק מכל הכחות שהן בבחי' מציאות לעצמן כמו כח השכל שהוא כח לעצמו חוץ מעצמו' הנפש, משא\"כ כח הרצון אינו מציאו' דבר לעצמו חוץ מעצמות הנפש, דהרי כל ענינו הוא רק הטיית והמשכת הנפש כו', ולכן מכל הכחות נשאר דבר גם לאחר סילוק הכח וכמו ההשכלה שנשארה גם כשפוסק מלהשכיל כו', משא\"כ ברצון שאינו נשאר ממנו מאומה כו' וכמשנ\"ת שם, וע\"כ בחי' הגילוי דאור הא\"ס שנמשך בעולמו' נק' בש' רצון, להיותו אינו דבר במציאו' לעצמו רק גילוי העצמו' כו', וה\"ה בבחי' מקיף על כולם בשוה כו', ואור זה מאחר שהוא בבחי' גילוי מן העצם לבד ה\"ז שייך גם אם לא היו עולמות כלל כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ומעתה צ\"ל ענין הג' כתרים כ\"ת כ\"כ כ\"מ, דהנה נת' דבכללות הן ב' מיני המשכות אורות, הא' שבבחי' מדה וגבול והוא בחי' הקו שנמדד לפ\"ע העולמות, והמדידה היא בשרשו באוא\"ס ששיער בעצמו להאיר במדה וגבול, והן הע\"ס הגנוזות והן בבחי' פשיטות לגמרי, וע\"י הצמצום להיות ספי' מיוחדות נמשך הקו בבחי' נקודות, והן בבחי' בלי מה (ולא כמו נקודות דתהו שנתלבשו בכלים והכוונה בהם להיות בבחי' מציאות), ועד\"מ כחות הנפש שישנם כלולים בעצם הנפש ושם הן בבחי' פשיטות כפשיטת הנפש, ובהמשכה נעלמת הן בבחי' פשיטות לגבי כחות הגלוים, ובסוף המשכתם היינו בכלים נעשים בבחי' מציאות אור, והמשכה זו היא מפני הרצון בעולמות, והמשכה הב' הוא האור שבבחי' א\"ס שהוא לגלות עצמותו, וכמו הרצון שהוא גילוי עצמיות הנפש. </span>\nקכח) <b>והנה</b> יש להבין בזה, והלא האור שהוא בבחי' גילוי מן העצם ודאי שהוא ג\"כ לצורך איזה כוונה, שהרי עצמותו ית' אינו מוכרח ח\"ו בהגילוים ממנו כנודע, וכמשנת\"ל פנ\"ו דהמשל דאור וזיו השמש אינו מכוון כ\"כ לענין אוא\"ס בזה שהשמש מוכרח בהגילוי אור ממנו כו', ומכוון יותר המשל דאור וחיות הנפש שאין הגילוי הכרחי כו', וא\"כ הגילוי מן העצמות הוא באיזה כוונה וה\"ז ג\"כ לצורך העולמות ואיך הוא בבחי' גילוי מן העצם כו'. אך הענין הוא דהנה זאת ודאי כן הוא שהגילוי הוא רצוני והוא בשביל איזה כוונה, אמנם הכוונה בגילוי אור זה הוא שיהי' גילוי אוא\"ס בעולמו' ויהי' בהם בחי' ביטול שעי\"ז יושלם הכוונה דנתאווה הקב\"ה להיות לו דירה בתחתונים כו', ומאחר שהכוונה בזה הוא להיות גילוי אור ושיהי' ביטול העולמו' ע\"כ הגילוי הוא בבחי' גילוי מן העצם שהוא כמו העצם כו', והיינו שהוא בבחי' א\"ס ובבחי' בל\"ג ממש ובבחי' אין בעצם מהותו כו'. והענין הוא דהנה האו\"פ שהוא האור הבא בבחי' מדה וגבול ה\"ה נמשך ג\"כ מן העצמות כו' (רק שאין ההמשכה מן\nהעצמו' ממש כ\"א מבחי' האחרונה דאוא\"ס הבבע\"ג ששיער בעצמו את האור שבבחי' גבול כו' וכמשנת\"ל פכ\"ז, ושרש ההמשכה הזאת היא ג\"כ מן העצמו' כו'), אך להיות שהכוונה בזה הוא שיהי' בחי' מדידה והגבלה"],[3601330412,"בעולמות כו', הרי ההמשכה אינו בבחי' גילוי העצם כ\"א אדרבה להיות לא כמו העצם כו', וזהו שההמשכה והגילוי אינו מצד העצמו' כ\"א מצד העולמו', והיינו שהגילוי הזה אינו שיהי' כמו העצמו' בבחי' העדר המציאו', כ\"א שיהיו עולמו' בבחינת מציאות דבר, ואם לא הי' הרצון שיהיו עולמו' לא הי' כלל גילוי אור כזה כו', וזהו שהגילוי הוא רק לצורך העולמות לפעול פעולת ההתהוות והמציאות, וע\"כ גם האור הוא בבחי' מציאו' דבר כו', והוא שנמצא מן העצמו' אור שהוא לא כמו העצם כו'. אבל האור שהוא בבחי' א\"ס ע\"ה שהוא ג\"כ בכוונה לצורך העולמו', ענינו הוא שיהי' הביטול בעולמות ויהיו בבחי' ביטול במציאו' בבחי' העדר כו' וכמשי\"ת בעזה\"י, וא\"כ גילוי אור זה הוא מצד העצמו' לא מצד העולמות, והיינו שגם העולמות יהיו כמו העצמות ובחי' העדר המציאו' כו', וע\"כ האור והגילוי הזה הוא בבחי' גילוי העצם, דהיינו חפץ העצמות לגלות אור כמהות העצמו' כבי' (לא להמציא אור שאינו כמו העצמו' כ\"א לגלות אור שהוא כמו העצם כו'), דאור וגילוי זה שייך גם אם לא הי' התהוות העולמו',\nמאחר שהוא גילוי שכמו העצם כו', והוא כמו העצם בבחי' א\"ס ובבחי' אין בעצם מהותו כו'. והענין דהנה נת\"ל פמ\"ט ההפרש בין כח הרצון לכח השכל, דכח השכל הוא שנמצא מן הנפש למהות כח בפ\"ע שהנפש משכלת בו כו', אבל הרצון אינו מהות כח בפ\"ע רק הוא הטיית והמשכת הנפש, א\"כ ה\"ה רק עצמו' הנפש ואינו שום דבר לעצמו כו', ומ\"מ ה\"ז ג\"כ רק רצון הנפש היינו מה שהנפש רוצה, והיינו שהוא רק הטיית הנפש ולא עצמותו רק שאין כאן מציאו' דבר חוץ מעצמו' הנפש שה\"ז רק מה שהנפש נמשך ורוצה כו'. והדוגמא מזה יובן למע' בבחי' האור שבבחי' א\"ס (שהוא למע' גם מבחי' רצון כו' וכמשנת\"ל) שאינו שום מציאו' לעצמו רק בחי' גילוי העצמו' לבד כו', ומ\"מ ה\"ז רק גילוי העצמו' ולא העצמו' ממש, אלא שהגילוי אינו בבחי' דבר לעצמו כ\"א הוא גילוי העצמות כו', וזהו שהוא בחי' אין בעצם מהותו מאחר שאינו בבחי' דבר לעצמו רק גילוי העצמות כו', והיינו שהוא בבחי' אין לא רק מצד הדביקות לבד כ\"א הוא בבחי' אין בעצם מפני שהוא רק גילוי העצמות כו'. והענין הוא דהנה ידוע בענין ד\"ע וד\"ת\nשהן מיש לאין ומאין ליש, דיש כאן ב' בחי' אין, הא' האין של היש האמיתי, והב' האין של היש הנברא, ומבו' במ\"א שאינם דומים זל\"ז, דהאין של היש האמיתי הוא בחי' אין באמת דהוא כל\"ח לגבי בחי' יש האמיתי כו', וא\"כ מה שנק' אין לגבי היש האמיתי ה\"ז באמת כן שה\"ה כלא כו', והאין של היש הנברא מה שהנבראים קוראין אותו אין ה\"ז רק שם המושאל לבד, דהנה מה שנק' אין הוא לפי שאינו מושג כלל לנבראים וה\"ה כאלו אינו כו', הרי א\"ז שהוא אינו באמת ח\"ו כ\"א לפי שאינו מושג להם, ועוד זאת מה שנק' אין הוא לפי שהוא בבחי' לא דבר, הרי זהו רק שהוא בבחי' לא דבר לגבי דבר, והיינו שאינו בבחי' יש אבל לא שהוא לא דבר ואין באמת שה\"ה מקור ליש, ואם הי' בבחי' אין באמת איך הוא בבחי' מקור דכל מקור הוא בבחי' מציאו' דבר כו', וא\"כ שם אין בו הוא רק שם המושאל כו'. והנה ההפרש הזה הוא גם בההארה אלקי' גופא (דזה שנת\"ל הוא ההפרש בין הב' בחי' אין כמו שהן לגבי יש האמיתי ולגבי יש הנברא, ובאמת ההפרש הזה הוא בההארה אלקי' עצמה), דהאין הא' הוא בבחי' אין ממש והאין\nהב' אינו בבחי' אין ממש כו', והוא מפני שהאין של היש הנברא ה\"ה בחי' הארה נבדלת (דהאור שהוא בבחי' דבקות במקורו הגם שהוא דוקא שרש ההתהוות וכמ\"ש באגה\"ק סי' כ', מ\"מ ההתהוות בפועל אא\"ל מאור זה כ\"א מהארה דהארה שהוא הארה נבדלת כו', וזהו שההתהוות הוא מבחי' מל' דוקא כו' וכמ\"ש במ\"א), וא\"כ אינה בבחי' אין ממש"],[3601330413,"כו', והאין של היש האמיתי הוא האור שבבחי' דבקות במקורו ונרגש בו מקורו כו', וע\"כ האור גופא הוא בביטול דכולא קכל\"ח כו', וכמ\"ש בסש\"ב פל\"ה בהג\"ה דאוא\"ס אחד האמת שהוא לבדו הוא ואין זולתו וזו היא מדרי' החכ', והיינו שבחכ' נרגש איך שהוא לבדו כו', וע\"כ הוא בבחי' אין ממש כו', וכ\"ז הוא שהוא בבחי' אין מצד הדבקות לבד לא בבחי' אין בעצם (כי נמצא מן העצמו' בבחי' מציאו' אור דהיינו בחי' חכ' כו', רק שדבוק במקורו כו'), וי\"ל שזהו בחי' אין של היש הנאצל דע\"ה שזהו ג\"כ בחי' אין של היש (ומבו' במ\"א שזהו בכלל בחי' ד\"ת כו'), ה\"ה מ\"מ בבחי' דבקות במקורו כו'. אבל האור שבבחי' א\"ס הוא בחי' אין בעצם להיותו רק גילוי העצמו' כו', וע\"ה שגילוי זה הוא ג\"כ באיזה כוונה בשביל העולמות כו', הנה הכוונה בזה להיות גילוי אוא\"ס בעולמו' ולהיות בהם בחי' הביטול כו'.\n<span data-k=\"ks\"><b>קיצור.</b> וצ\"ל והלא האור שבבחי' א\"ס הוא ג\"כ גילוי רצוני, וא\"כ הוא בשביל איזה כוונה. אך הענין דהאור שבבחי' מדה הוא להיות התהוות העולמות, א\"כ המשכתו מן העצמות הוא שיהי' לא כמו העצמות כ\"א בחי' המציאות, והאור הבל\"ג הוא שיהי' בחי' הביטול גם בעולמות בבחי' העדר המציאות. והענין שיש ב' בחי' אין, האין של היש האמיתי שהוא כלא והאין של הנבראים שנק' אין רק לגבי הנבראים, וכן בעצם הארה זו אינו בבחי' אין ממש להיותה הארה נבדלת, והאין הא' שהיא בבחי' דביקות ה\"ה בבחי' אין ממש, וי\"ל שזהו במקור האו\"פ, ואור הא\"ס הוא אין בעצם מפני שהוא גילוי העצמות, והכוונה שביטול זה יהי' גם בעולמות. </span>\nקכט) <b>אמנם</b> עדיין צ\"ל והלא האו\"פ הוא ג\"כ להאיר העולמות להיות בהם בחי' הביטול, וכמ\"ש הפרד\"ס שע\"ד פ\"ה בפי' מא' הת\"ז אנת הוא דאפיקת כו' לאנהגא בהון עלמין להיות ע\"י גילוי האלקו' בעולמו' כו', וכמשנת\"ל פ\"ח ופמ\"ח דאמצעית האצי' הוא בב' דברים, הא' שיהי' עי\"ז התהוות העולמו' בי\"ע בבחי' המציאו' שלהם שזהו העיקר ע\"י הכלים וכמ\"ש באגה\"ק איהו וגרמוהי חד לברוא כו', והב' שע\"י האצי' דוקא יכול להיות גילוי אלקו' בעולם, והו\"ע ידיעות והשגות אלקו' והרגישות אלקו' שבעולם שכ\"ז מהע\"ס דאצי' מבחי' מוחין ומדות כו', שזהו העיקר מן האור כו', וכמ\"ש בסי' שער הק\"ש דגוף ונפש דמלאכים שהו\"ע חומר וצורה זהו מבחי' או\"כ דאצי', דזה שיש בהם בחי' הביטול לאלקו' וגם יש בהם צד פירוד מצד החומר כו', וכן אפי' בנבראים שלמטה יש בהם השגה באלקו' וביטול לאלקו' כו', שכ\"ז הוא מבחי' או\"כ דע\"ס דאצי', וא\"כ מהו\"ע האור דא\"ס שזהו דוקא גילוי מן העצם מפני שהכוונה בזה הוא הביטול כו'. אך הענין הוא דזה גופא שהאו\"פ יהי' מאיר בכל העולמו' גם בעולמו'\nבי\"ע ויהי' בהם בחי' הביטול כו', זהו ע\"י האור שבבחי' א\"ס כו', דהנה ע\"פ מא' קו המדה שנמדד בתחלת ההשתל' אין אור האצי' מאיר כלל בבי\"ע כו', דאור האצי' הוא אור הקו הנמשך מאוא\"ס וכמא' ש' מ\"ה מלגאו דאיהו אורח אצי' כו', וידוע דהקו מסתיים במל' דאצי' ואינו מאיר בבי\"ע כו', דלהיות דהמשכת הקו הוא ע\"י הצמצום שנמשך אור מצומצם לפי\"ע העולמו', דהרי אור הקו הוא שנמשך אור להיות בבחי' התלבשו' בעולמו' בבחי' אור וחיות פנימי שזהו ע\"י הצמצום דוקא, דלולא זאת לא הי' אפשר כלל להיות התלבשו' אוא\"ס בעולמו' וכלים כו' (דהגם שהאור הזה"],[3601330414,"בשרשו ומקורו הראשון הוא בבחי' או\"פ (לפי השיטה המבו' בדרוש זה), מ\"מ כמו שהוא לפה\"צ אינו בערך התלבשו' בעולמו', וכמשנת\"ל דע\"ס הגנוזות עם היותם בחי' ממכ\"ע בשרשם ומקורם הראשון ה\"ז בבחי' סובב לגבי הקו כו'), ורק ע\"י הצמצום הוא שנמשך האור באופן כזה שיהי' בבחי' התלבשו' כו', אבל יש בזה מדידה והגבלה דהתלבשו' האור יכול להיות רק במדרי' שהן אלקו' ממש כו', וע\"כ המשכת והתלבשו' אור הקו הוא רק עד אצי' שהכלים דאצי' הן אלקו' ממש כו' (וגם עד האצי' האור הולך ומתמעט, וכנודע דגם באצי' הוא רק הארת הקו כו', וכמשנ\"ת ג\"כ לעיל). אבל בבי\"ע אא\"ל המשכת אור הקו ע\"פ מא' קו המדה כו', ורק מבחי' הכלים דאצי' הוא שנמשך בבי\"ע שנעשים נר\"ן לבי\"ע כנודע, וג\"ז לא מבחי' עצמו' הכלים כ\"א מה שע\"י הכאת הכלים בהפרסא שבין אצי' לברי' נתנוצצו מהם בבי\"ע כמ\"ש בע\"ח שער השמות פ\"א שזהו רק הארה נבדלת מהכלים כו', וע\"ה שגם מן האורות דאצי' נתנוצצו בבי\"ע כמ\"ש בע\"ח שער כסה\"כ, הנה זהו רק מבחי' בינה ולמטה שא\"ז עצמו' האצי' ממש, דעיקר עצמו' האצי' הוא\nבחי' החכ' כו', ואי' בע\"ח דאור אבא אינו נכנס כלל בברי' רק מבחי' בינה מתנוצץ בברי' ע\"י בחי' מל' דמל' דאצי' כו'. ונמצא דבס' השתל' אין אור האצילות מאיר בבי\"ע כו', וזהו שארז\"ל במד\"ר פ' וארא פי\"ב ע\"פ כל אשר חפץ ה' עשה בשמים ובארץ משל למלך שגזר שבני רומי לא ירדו לסוריא ובני סוריא לא יעלו לרומי, אח\"כ ביטל הגזירה, כך מתחילה השמים שמים לה' והארץ נתן לבנ\"א, ובמ\"ת עמד הקב\"ה וביטל הגזירה כו', והיינו דקודם מ\"ת לא הי' התחברות דאצי' עם בי\"ע, וזהו דבני רומי לא ירדו כו', וה\"ז כענין אם אני לא אעבור אליך כו' ואם אתה לא תעבור אלי כו', שנעשה פרסא והפסק בין אצי' לבי\"ע שלא יומשך מאצי' לבי\"ע ביותר מכפי המדה, וכמו\"כ לא יהי' עליית בי\"ע לאצי' כו' (ובקי\"ס שהי' חבור אצי' וברי' כמ\"ש במ\"א זה הי' רק לפי שעה והי' זה הכנה למ\"ת), ובמ\"ת נתחדש זאת שיהי' גילוי אצי' בבי\"ע כו'. וזה שיהי' גילוי אצי' בבי\"ע ויהי' ביטול בעולמות זהו דוקא מעצמו' אור האצי', וכמ\"ש החכמה תעוז לחכם יותר מעשרה שליטים שבעיר דעשרה שליטים הן העש\"מ שנמשכים\nמע\"ס דאצי', רק שזהו מבחי' חיצוני' דאצי' היינו מבחי' בינה דאצי' ולמטה, שמזה נעשה בחי' המציאות דעולמות (וגם בחי' הידיעה והשגת האלקו' שבעולמות כו'), אבל זה שיהי' הביטול בעולמו' ע\"י גילוי אור האצי' וכמשי\"ת, זהו מבחי' עצמו' האצי' שז\"ע מה שהחכ' תעוז לחכם כו' וכמשי\"ת. וזהו ג\"כ ענין מלגאו איהו שם מ\"ה כו', וידוע דשם מ\"ה שהוא ש' הוי' במילוי אלפי\"ן הוא בת\"ת, וענין מלגאו איהו ש' מ\"ה זהו בחי' הדעת דמשה מלגאו ויעקב מלבר כו', ונודע דדעת ממשיך מפנימי' הכתר כו', ובכדי שתהי' המשכה זאת שהיא שלא ע\"פ הדרגה דס' השתל' זהו ע\"י האור שבבחי' א\"ס ובל\"ג כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ועדיין צ\"ל והלא האו\"פ הוא ג\"כ בכדי שיהי' הביטול וכמשנ\"ת דאמצעית אצי' הוא גם שיהי' גילוי אלקות בעולם. אך הענין הוא דהרי הקו מאחר שבא ע\"י הצמצום לפ\"ע העולמות ה\"ה מסתיים באצי', ונר\"ן דבי\"ע הוא רק מכלים דאצי' והתנוצצות האור דאצי' הוא רק מהבינה, ובמ\"ת נתחדש שיהי' גילוי אצי' בבי\"ע, והיינו מעצמות האצי' שעי\"ז הוא הביטול בבי\"ע, והוא</span>"],[3601330415,"<b>ע\"י</b> המשכה מעצמות אוא\"ס, והו\"ע ש' מ\"ה דמלגאו בחי' הדעת שממשיך מפנימיות הכתר.\nקל) <b>וביאור</b> הענין צ\"ל תחלה ההפרש בין ההמשכה דהאבות לההמשכה דמ\"ת שהרי האבות ג\"כ המשיכו גילוי אלקו' בעולם וכדאי' במד\"ר בא אברהם התחיל להאיר כו', ומה נתחדש לכאו' במ\"ת שאז דוקא ביטל הגזירה כו'. אך הענין הוא דהנה כת' וארא אל אברהם כו' באל שדי ושמי ה' לא נודעתי להם, ולכאו' א\"מ והלא מצינו כמה פעמים ש' הוי' גבי האבות, וצ\"ל דכ\"ז הוא רק בחי' אל שדי, והיינו שגם מה שנא' בהם ש' הוי' א\"ז גילוי ש' הוי' עדיין כ\"א גילוי ש' אל שדי, וכמו גבי מצות מילה שאז הי' אמית' הגילוי לאאע\"ה נא' אני אל שדי התהלך לפני כו', וצ\"ל מהו\"ע שם שדי. והנה בגמ' דחגיגה די\"ב ע\"ב ובמד\"ר לך פמ\"ו אי' אני אל שדי אני הוא שאמרתי לעולמי די כו', שאלולי שאמרתי די עד עתה היו נמתחים כו', ומשמע מזה שאם לא א\"ל די הי' העולם נמשך בלי הגבלה כלל, ולכאו' א\"מ איך יכול להיות יש נברא בבחי' בל\"ג שה\"ה בבחי' הגבלה בעצם, וצ\"ל שזהו כמ\"ש בסש\"ב ח\"ב פ\"ג שהנבראי' הם רק אור וזיו המתפשט מן השפע ורוח ה' השופע ומתלבש בתוכם ומוציאם מאין ליש כו', ומאחר\nשהן רק אור וזיו המתפשט ממקורם הרי יכול להיות ההתפשטות עד אין שיעור ואז לא היו באמת בבחי' מציאו' יש כו'. והענין הוא כמש\"ש פ\"ד בענין השבחים הגדול הגבור דההתהוות הוא מבחי' החסד וכמ\"ש כי אמרתי עולם חסד יבנה, דמדת החסד הוא התפשטו' החיות בכל העולמו' וברואים לאין קץ ותכלית כו', ונק' גדולה כי באה מגדולתו של הקב\"ה בכבודו ובעצמו כו', והיינו כי חסד הוא בחי' גילוי אור והוא אור הדבוק במקורו כו', שמזה הוא דוקא ההתהוות כו', וכמו שהוא מצד מדת החסד לא היו העולמו' בבחי' יש ומציאו' כ\"א רק הארה ממקורם כו', והיו נמשכי' בבחי' בל\"ג דאור החסד אינו מתעבה כו'. אמנם ענין מדת הגבו' הוא מדת הצמצום ומניעת התפשטות החיות מגדולתו מלירד ולהתגלות כו' בגילוי כ\"א בהסתר פנים כו', וכאלו גוף הנברא הוא דבר בפ\"ע, ואף שבאמת אינו דבר בפ\"ע אלא כמו התפשטו' האור מהשמש כו', והיינו שע\"י הגבו' והצמצום נעשו הנבראי' בבחי' מציאות יש ובבחי' הגבלה כו'. ולפי\"ז מובן דמ\"ש לעולמו די אין הכוונה על העולם עצמו שהרי א\"א שיהי' העולם בל\"ג כ\"א הכוונה\nהוא על הארה האלקי' שאמר די להיות בבחי' הגבלה דעי\"ז נעשה בחי' המציאות וההגבלה בעולם כו', וז\"ע שם שדי שאמר לעולמו די כו'. ובשרש שרשו שם שדי הו\"ע צמצום הראשון שהי' באוא\"ס דבתחלה הי' אוא\"ס ממלא כל מקום החלל שהי' הכל בבחי' א\"ס כו', והי' הצמצום שלא יהי' התפשטות וגילוי האור בבחי' א\"ס כ\"א שיוכלל האור במקורו המאור וישאר רק רשימו כדי להיות שרש להתהוות בחי' בע\"ג כו', ובעולם האצי' הו\"ע מיעוט האור וריבוי הכלים שזהו עיקר התקון, וכנודע דבתהו הי' ריבוי האור והכלים היו במיעוט ולא היו יכולים לסבול ולכך נשברו כו', אבל בחי' התיקון הוא בהיפך שהאור במיעוט והכלים בהתרחבות ובריבוי התחלקות כלים רבים לאור א' ועי\"ז נתקיימו כו'. וז\"ע שם שדי באצי' שיהי' בחי' מיעוט האור באופן שיהי' בבחי' התלבשות בהכלים, והכלים יהי' בבחי' התרחבות שיקבלו את האור ויגבילו ויעלימו אותו שעי\"ז יכולים ליהנות מן האור כו', וז\"ש וירא אלקי' את האור כי טוב פי' כי טוב"],[3601330416,"לגנוז שיתלבש ויתעלם בהכלים כו', וזהו ל' תיקון שהוא ל' לבוש כמו לא ילבש לא יתתקן כו', דענין התיקון הוא שהכלים ילבישו את האור שע\"י הלבשת האור והעלמו בכלים יכולים ליהנות ממנו כו'. והאבות זכו לבחי' התיקון דעד אברהם היו שני אלפים תהו (ואי' דהוו קרין לי' בשמות נוכראין), ומאברהם התחיל בחי' התיקון והוא בחי' הכלים שיתלבש בהם האור, דע\"ה שזהו בחי' צמצום והעלם ה\"ז תכלית החסד שעי\"ז דוקא יכולים לקבל הגילוי כו'. וזהו דאי' בע\"ח שער העקודים דהתחלת התגלות הכלים הוא בעקודים שזהו בחי' אברהם (והו\"ע ויעקוד את יצחק להיות התקשרות האור בכלי כו'), דאברהם בגימט' רחם והכלים הן תכלית הרחמים והחסד כו', ועז\"א וארא אל אברהם כו' באל שדי שע\"י ש' שדי שאמר לעולמו די כו', עי\"ז וארא אל אברהם בבחי' חסד ואה' כו', דבכדי שיהי' גילוי בחי' החסד והאה' למטה זהו ע\"י הכלים דוקא כו', גם ענין וארא אל אברהם שנמשך בו ממהות בחי' כלי החסד דאצי' כו', דהאבות הן המרכבה וכתי' הלוך ונסוע הנגבה במדת החסד ואה' עליונה עד שזכה להיות מרכבה למדת החסד\nדאצי', וממדת החסד נמשך מבחי' פנימי' הכלי דחסד להתלבש ממש בנשמת אברהם המאירה בגופו ממש כו'. והענין הוא כדאי' בע\"ח שמ\"א פ\"ג בפי' האבות הן המרכבה, כי יש ניצוץ קטן מאד שהוא בחי' אלקו' נמשך ממדרי' אחרונה שבבורא, וזה הניצוץ מתלבש בכח ניצוץ א' נברא שהיא נשמה דקה במאד מאד, ובניצוץ זה הנק' יחידה יש בה שרשי ד' בחי' הרוחניות נרנ\"ח כו', והיינו כי הנשמה היא ד' בחי' נרנ\"ח שהן ד' בחי' חו\"ב וזו\"נ, ובמ\"א מבו' דחי' הוא בחי' מקיף והיינו בחי' מקיף הקרוב שיש לו אחיזה בפנימי', וכל הגילוים דנר\"נ הן מהמקיף דחי' דעש\"ז נק' מזל ע\"ש שנוזל ונוטף בהנשמה שבגוף כו' וכמ\"ש במ\"א, ובחי' יחידה היא שרש ד' בחי' הנ\"ל הכוללת כולם כדמיון התכללות חו\"ב וזו\"נ בא\"א כו', ומבו' בע\"ח שם שזהו כדמיון חומר הראשון שפשוט מכל צורה והוא הנושא כל הד' צורות כו', ובבחי' ניצוץ זה הנק' יחידה מתלבש ניצוץ קטן שהוא אלקות ממש, ע\"ד התלבשות בחי' עתיק בא\"א דעתיק הוא בחי' תחתונה שבא\"ס ומתלבש באריך שהוא ראש ומקור הנאצלי' כו', וכמו\"כ בחי' ניצוץ קטן הוא\nאלקו' ממש מבחי' הכלים דאצי' שהן אלקו' ממש לברוא בהן וע\"י כו', רק שהכלים נק' בחי' אחרונה שבבורא להיות שהן מגבילים את האור כו', דההתהוות הוא מהאור והכלים רק מגבילים בכדי שיהי' הנברא בבחי' יש כו', ע\"כ נק' הכלים בחי' תחתונה שבבורא כו', והוא מתלבש בניצוץ היחידה שרש הד' מדרי' שבנשמה כו'. וזהו וארא כו' באל שדי דמבחי' פנימי' הכלים נמשך הניצוץ להתלבש בהאבות אברהם מבחי' חסד דאצי' ויצחק מבחי' הגבו' ויעקב מבחי' הת\"ת כו', וזהו וארא כו' באל שדי דשם שדי באצי' הו\"ע הכלים שמגבילים את האור, והניצוץ קטן שממהות הכלים האיר בגילוי ממש בנשמתם כו'. וענין שם שדי בעבודה הוא מ\"ש משפט וצדקה ביעקב אתה עשית, דצדקה הוא מדת החסד שמצד מדת הטוב והחסד הוא מתחסד עם הזולת כו', אך בצדקה יש השתתפות מדת הרחמים דענין הצדקה הוא להחיות רוח שפלים שזהו מצד הרחמים, וכידוע ההפרש בין חסד לרחמים דחסד שייך לכל אדם להתחסד עמו, אבל רחמים שייך רק על השפל דמי שהוא באיזה דרגא אינו נופל עליו רחמים כ\"א על השפל כו', וזהו ג\"כ ההפרש בין גמ\"ח\nלצדקה, דגמ\"ח הוא בין לעניים ובין לעשירים וצדקה הוא לעניים דוקא, וע\"י הצדקה למטה ממשיכי' למע' מדת החסד שהו\"ע התפשטו' האור והחיות כו', וזהו ג\"כ בהשתתפות"],[3601330417,"מדת הרחמים להחיות רוח שפלים והיינו להוות ולהחיות עולמו' התחתוני' שזהו בחי' הגדול כו' כנ\"ל. אמנם צדקה משפט כתיב בה שצ\"ל משפט בצדקה שישפוט א\"ע מן המותרות שלו ויתן לצדקה שזהו עיקר ענין הצדקה, דלא זו היא עיקר ענין הצדקה דלאחר כל מילוי המותרות שלו יתן מהמותר לעניים, כ\"א שישפוט א\"ע מן המותרות, דמשארז\"ל חייך קודמין הוא כעין מעשה שהי' בקיתון של מים כו' דהיינו רק מה שמוכרח לו, אבל לא שיתענג הוא בכל התענוגי' וחברו ימות ברעב ח\"ו, וכן גם בריבוי השפעה צריך לשפוט א\"ע מהדברים המותרים וזאת יתן לצדקה שזהו עיקר ענין הצדקה כו'. וע\"י המשפט שעושה בעצמו עי\"ז הוא למע' בחי' הצמצום וההגבלה בהאור שיהי' באופן כזה שיהי' התהוות הנבראי' בבחי' מציאו' ויהנו הנבראים לאורו ית' שז\"ע הגבור שנת\"ל, וכמו\"כ הוא בכללו' עבודת האדם לצמצם א\"ע ולכבוש רוח תאוותיו שלא יהי' בהתפשטו' והתרחבות בעניני' החומרי', כ\"א אדרבה יכפה א\"ע בכל פרטי עניניו ויהי' כוונתו לש\"ש, וכמו באכו\"ש יהי' כוונתו לקיום גופו בכדי שיוכל ללמוד ולהתפלל, וממילא הוא\nנזהר מן המותרות שהן רק למלאות תאוותו, ומסתפק רק בהמוכרח לו ובכוונה הנ\"ל, וע\"י הכפי' שכופה ומצמצם א\"ע עי\"ז נעשה התרחבות הכלים למעלה שיהיו כלים לקבל את האור ולהגבילו שיהי' באפשר לקבל את האור כו', והאבות שהיו מרכבה היו כל אבריהם קדושים ומובדלים מעניני העולם עד שכל עניניהם הגשמי' היו אלקו' ממש, והיינו שהאיר אצלם בגילוי עצם הניצוץ האלקי כנ\"ל שזהו עצם בחי' שדי כנ\"ל, וע\"כ היו כל עניניהם אלקו' כו', ובכל אדם הו\"ע הכפי' והצמצום בנפשו ועי\"ז נעשה ההגבלה להיות האור באופן כזה שיתקבל בנבראי' ויהנו לאורו ית' כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ובה\"ע דהנה בהאבות כתי' וארא כו' באל שדי שא' לעולמו די, והיינו בחי' ההארה אלקית שמבחי' החסד גילוי בבחי' בל\"ג ואמר די ע\"י מדת הגבו', הגדול הגבור, ובשרשו הוא בחי' הצמצום שנשאר רשימו, והכוונה שיהי' ריבוי הכלים שעי\"ז יתקבל האור, והו\"ע התיקון, והאבות זכו לתיקון, והיינו בחי' כלים שמתלבש בהם האור, והאיר בנשמתם בחי' מהות פנימיות הכלים, והו\"ע הניצוץ קטן שביחידה שמבחי' אחרונה שבבורא דהיינו בחי' הכלים, וזהו וארא גילוי המהות, וענין ש' שדי בעבודה הו\"ע משפט וצדקה, שע\"י הכפי' הוא התרחבות הכלים לקבל את האור.</span>"],[3601330418,"<h3>בס\"ד. ליל ב' דחה\"ש, תער\"ג</h3>\n<b>אנכי</b> ה' אלקיך אשר הוצאתיך מארץ מצרים, וצ\"ל מהו\"ע שמודיעים ענין יצי\"מ במ\"ת ע\"ה דיצי\"מ הי' הכנה למ\"ת מ\"מ צ\"ל מה שייכות יצי\"מ למ\"ת שמודיעים זאת בדבור הראשון כו'. גם צ\"ל מ\"ש אנכי ה' הלא ידוע דאנכי והוי' הם ב' עניני' דאנכי זהו בחי' עצמו' אוא\"ס ב\"ה שלמע' מבחי' גילוי כו', ושם הוי' הוא"],[3601330419,"בחי' גילוי אור כו', וא\"כ צ\"ל איזה גילוי הי' במ\"ת אם הי' גילוי העצמו' שז\"ע אנכי למה נא' כאן הוי' והול\"ל אנכי אלקיך כו', ואם הי' גילוי שם הוי' מהו אומרו אנכי הוי' כו'. ולהבין זה צלה\"ק משנת\"ל בענין וארא אל אברהם כו' דהגילוי להאבות הי' בש' שדי, ונת' דשם שדי הוא שא' לעולמו די, דהיינו בחי' הגבלת האור כו', ובשרש הראשון הו\"ע הצמצום שהי' באוא\"ס להעלים ולהגביל את האור כו', ובאצי' הו\"ע מיעוט האור שיוכל להתקבל שזהו ג\"כ ע\"י הצמצום כו', וענין הכלי' שמקבלי' את האור ומגבילי' אותו זהו בחי' שם שדי כו'.\nקלא) <b>והנה</b> במד\"ר פ' בא פט\"ו אי' בא אברהם התחיל להאיר שנא' מי העיר ממזרח כו', בא יצחק אף הוא האיר שנאמר אור זרוע לצדיק כו', ובזח\"א מ\"ה ע\"ב משמע דמ\"ש מי העיר הו\"ע אור זרוע כו', והיינו שהאבות בכלל המשיכו בחינת אור זרוע כו'. וענין אור זרוע למע', הענין הוא דהנה אי' אנת הוא חכים ולא בחכ' ידיעא מבין ולא בבינה ידיעא, וקאי על בחי' חו\"ב שלמע' מאצי', דהנה חו\"ב דאצי' הן בבחי' ידיעא וכמו שאו' לפני זה חכ' מוחא איהי מח' מלגאו בינה ליבא ובה הלב מבין הרי שהבינה היא שבה הלב מבין בבחי' ידיעא, וכמו\"כ בחכ' שאו' דאיהי מח' ה\"ז בבחי' ידיעא דבמה שאינה ידיעא או' קודם לית מתב\"כ, והיינו בבחי' עילאה על כל עילאין וסתימא עכ\"ס שסתום ונעלם אי' דלית מת\"ב כו', וכאן שנא' איהי מח' מלגאו ה\"ז בבחי' חכ' ידיעא כו'. וידוע דאצי' הוא בבחי' גילוי ההעלם, ולא יש ענין גילוי ההעלם למטה ממדרי' האצי' כו', ובכללו' הרי כל ענין הקו הוא בחי' גילוי ההעלם משרשו ומקורו שהן הע\"ס הגנוזות כו' וכמשנת\"ל באורך, ובפרטי' הע\"ס דאצי' הן בבחי'\nגילוי ההעלם, וא\"כ הרי החכ' היא בבחי' חכ' ידיעא כו'. ומ\"ש אנת הוא חכים ולא בחכ' ידיעא היינו בחו\"ב שלמע' מאצי', והיינו בבחי' חו\"ב דעקודים או חכ' דא\"ק דלא בחכ' ידיעא עדיין, וכמ\"ש בזהר דלאו אינון נהורין כו', דע\"ס דאצי' הן בבחי' מציאו' אורות אבל ע\"ס הגנוזות לאו אינון נהורין עדיין כו', שהרי הע\"ס דעקודי' עם היותם עשר אורות ה\"ה עקודי' כולם בכלי א' ובהכרח לו' שהן לא בבחי' מציאו' דבר כו', וכמו בכחות הנפש הכלולי' בעצם הנפש ה\"ה בבחי' העדר המציאו', דאל\"כ איך ישכנו כולם יחד כו', וכמו\"כ הוא בעקודים כו' וכמ\"ש במ\"א, וכ\"ש בע\"ס דא\"ק שהן בבחי' פשיטו' עדיין, וכמ\"ש במ\"א שזהו עד\"מ כמו שהנפש נושא הכחות בעצמו כו', ולפ\"ז צ\"ל איך הוא התהוות ע\"ס דאצי' מע\"ס הגנוזות. הנה מבואר בתו\"א ד\"ה פתח אליהו (ושם מבו' בהתהוות חכ' דברי' מחכ' דאצי', ובמ\"א מבו' די\"ל דהכוונה שם על בחי' הכלים דאצי' כו', וכאן הכוונה על התהוות האורות דאצי' מהע\"ס הגנוזו' כו', ועמ\"ש בתו\"א ד\"ה ויאמר הן עם אחד) שזהו עד\"מ כמו זריעת גרעין של תפוח בארץ וצומח\nממנו תפוח ע\"י כח הצומח שבארץ, והנה אנ\"ר שאותה המתיקות שבתפוח הנרגש לחיך לא הי' כלל בהגרעין שנאמר שממנו נתהווה כו', ורוב זרעוני גינה אינם נאכלים כלל כו', ואם נא' שמכח הצומח נתהווה מתיקו' הזאת הלא אין מציאו' מתיקות כלל בכח הצומח הרוחני כו' (ובמ\"א מבו' שגם בכח הצומח יש בו המתיקות, וזהו שפרש\"י ע\"פ יושבי הארץ שהיו טועמים את העפר כו' רק שהוא מתיקות רוחני כו', ובאגה\"ק סי' כ' כ' שמכח הצומח הוא עצם ישות הפרי, והצמיחה שהו\"ע החיות, והמתיקו' הוא מהמזל כו'). אך הענין הוא כמארז\"ל אין"],[3601330420,"לך עשב מלמטה שאין לו מזל למע' המכה בו ומגדלו, ובאותו המזל הרוחני יש בו המתיקו', אמנם הוא מתיקו' רוחני מאד וכמו מתיקות שבניגון ומתיקו' שבאור שכל וכה\"ג, ואינו מתיקו' גשמי הנרגשת לחיך הגשמי כ\"א בבחי' הרגשה לחיך הרוחני כו', וכמו ענין תפוח רוחני שאכל אדה\"ר כשלא הי' לו עדיין גוף גשמי וחומרי כו', והמתיקות הרוחני' שבמזל ה\"ה מתעבה ומתגשם ע\"י הגרעין הנזרע ונעשה מתיקו' גשמי, והוא המתיקו' הגשמי שבתפוח הנרגש לחיך הגשמי כו'. והדוגמא מזה יובן למע' דע\"ס הגנוזות הן כמו עד\"מ המתיקות שבמזל שהוא בבחי' רוחני' עדיין, והיינו שאינם בבחי' אור החכ' עדיין, וכמשנת\"ל פי\"ד דבחי' ח\"ס הוא למע' מהחכ' עדיין לגבי בחי' החכ' דאצי' וכ\"ש בחי' חכ' דא\"ק כו', ומ\"מ נתהווה משם בחי' אור החכ' דאצי' שזהו כמו הזריעה עד\"מ שהמתיקו' נתעבה ונתגשם כו'. והנה המתיקות שבהתפוח א\"ז עצמיות ומהות כח הרוחני דהמזל אלא רק הארה המתפשטת מעצמו' ומהות הרוחני דכח המזל המכה בו כו', והארה זו נתעבה ונתגשמה כ\"כ עד שנעשה מתיקות גשמי כו', ואין התפשטו' זו כמו\nהתפשטו' המים הנמשכים ממקום למקום, דמהות המים הוא שנמשכו ממקום למקום, וע\"כ המים הנמשכים לא נשארו במקום הראשון כלל, משא\"כ בכח המזל הרוחני הרי לא נחסר כלל בצמיחת והגדלת הפרי מפני שזהו התפשטות הארה בלבד, והארה היא שמתגשם ונעשה מתיקות גשמי כו'. והדוגמא מזה למע' הוא מה שהע\"ס נק' אורות להורות שהן הארה לבד משרשם ומקורם, ואינם עושים שום שינוי ח\"ו כו', והיינו כמשנת\"ל פנ\"ד בענין אור ושפע דענין אור הוא שאינו עושה שינוי ח\"ו כו', וזהו אור זרוע שהתהוות הע\"ס הוא כמשל אור הזרוע להיותם בחי' הארה לבד כמשל המשכת האור מהמאור כו', אך לא כאור השמש שהאור לא נתגשם כלל כ\"א כמו אור זרוע שע\"י הגרעין הזרוע ההארה מתעבה ומתגשם כו', כמו\"כ האורות דע\"ס הן כמו אור זרוע שבא בהגשמה לגבי מקורו עד שנק' בשם אור החכ' כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ובמד\"ר בא אברהם התחיל להאיר, ובזהר שז\"ע אור זרוע, והענין דהנה חכים ולא בחכ' ידיעא זהו בחי' חכ' דא\"ק ועקודים, דלאו אינון נהורין, וכמו הכוחות הכלולים בנפש ושהנפש נושא בעצמו, וחכ' דאצי' היא חכ' ידיעא גילוי ההעלם, ואיך הוא התהוותם, הענין הוא ע\"ד התהוות מתיקת התפוח מהמזל שע\"י אמצעית הגרעין בא לידי הגשמה, והנה מתיקות התפוח היא רק הארה ממתיקות המזל שלא נחסר דבר, ולא כמו אור השמש כ\"א שבא בהגשמה ע\"י הגרעין, כמו\"כ האורות הן הארה ממקורם שאין מזה שום שינוי רק שבאים בבחי' מציאות אור, והו\"ע אור זרוע. </span>\nקלב) <b>והנה</b> בהמשל הרי הגשמת ההארה הוא ע\"י הגרעין הנזרע כו', ולמע' י\"ל עפמ\"ש בע\"ח שער מטולמ\"ט פ\"א שהתהוות הכלים בעקודים הוא ע\"י שהמשיך את האור כו', ואחר שנמשך חזר ונסתלק האור ההוא למע' לגבי מקורו, ומניח רושם חותם למטה וזה הרושם נעשה בבחי' כלי ע\"י ריחוק האור ממנו כו', וזה הרושם י\"ל שזהו כמו עד\"מ הגרעין שבו וע\"י נצמח הפרי כו', כך ע\"י הרושם הנ\"ל נצמחו ונתהוו הע\"ס משרשן שבא\"ק כו'. וי\"ל דכמו שהכלים דאצי' מגבילים את האור הרי מבו' במ\"א שההגבלה הוא שמגביל חוץ לאצי', דבאצי' ה\"ה עדיין בבחי' א\"ס להתפשטותן כו', דגם הכלים דאצי' אינם בבחי' גבול"],[3601330421,"עדיין וכמא' מדתן עשר שאין להם סוף כו', וכמ\"ש הפרד\"ס וכמבו' במ\"א, רק ההגבלה היא שחוץ לאצי' יפעול האור בבחי' גבול דהיינו בהתהוות בי\"ע כו', וכמו\"כ בחי' הכלי דעקודים פועל בהאור שבהמשכתו באצי' יהי' בבחי' מציאו' כו'. וממ\"ש בע\"ח הניח רושם חותם י\"ל שהכלי דעקודים מאחר שנק' בשם רושם ה\"ז מגביל יותר מכלים דאצי' כו', וע\"ד המבו' במ\"א ההפרש בין כלים דאצי' להפרסא שבין אצי' לברי', דכלים דאצי' ה\"ה כלים להאור, וע\"כ הגם שמעלימים ומגבילים את האור מ\"מ ה\"ז מהות אותו האור כו', וכמו אותיות הדבור שמלבישים את השכל ומעלימים עליו מ\"מ השכל המתגלה ה\"ה אותו השכל רק שהוא חיצוניותו לבד כו', אבל הפרסא שאינו כלי להאור ה\"ז מעלים ומגביל לגמרי כו', ועמ\"ש בלק\"ת שה\"ש ד\"ה מה יפו פעמיך בנעלים וכמשנת\"ל פק\"ו, ובדוגמא כזאת י\"ל בכלי דעקודים שנק' רושם כו' (ומובן שאינו דומה כמו פרסא רק בדרך דוגמא לבד). ושרש ענין זה למע' יותר י\"ל שז\"ע הרשימו שנשאר לאחה\"צ וסילוק האור הא\"ס שזהו כמשל הגרעין כו', ואח\"כ המשכת הקו מאוא\"ס ה\"ז ע\"ד המזל המכה בו\nואומר גדל כו', וידוע דהקו נק' מזל וכדאי' בזח\"ג דקל\"ד א' האי חוטא יקירא קדישא כו' איקרי מזלא כו', וכמו המזלות דא\"א שמהם נמשך לחו\"ב דאבא יונק ממזל הח' כו', והמזלות הן שבאים בבחי' מציאות אור בחו\"ב ע\"י רושם הכלים דעקודים כו', כמו\"כ בחי' הקו ה\"ה בבחי' מציאו' אור ובא במדה ומשקל ע\"י הרשימו כו', וזשארז\"ל ע\"פ וכל עשב השדה כו' עמדו דשאים על פתח הקרקע כו', י\"ל שהו\"ע הרשימו ומזה נמשך הקו בבחי' מציאו' אור כו' וז\"ע אור זרוע כו'. וי\"ל ג\"כ ענין אור זרוע על התהוות הכלים שזהו עד\"מ כמו התהוות מהות הפרי מכח הצומח שבארץ שא\"ז ממהוע\"צ כח הצומח כ\"א הארה הנמשכת ממנו ובאה בהגשמה ע\"י הגרעין הנזרע עד שנעשית פרי כו', כמו\"כ הוא בהתהוות הכלים דאצי' מכלים דא\"ק (עמ\"ש מזה בד\"ה יו\"ט של ר\"ה, רס\"ו), שזהו ע\"י הרושם דכלים דעקודים כו', דהרי הכלים דא\"ק הן שרש נשמות דגופות כמ\"ש בע\"ח, והארה שלהם באה בבחי' הגשמה ע\"י בחי' הרושם דעקודים עד שנעשית בבחי' מציאות כלי כו' (וי\"ל דבכלים סדר ההמשכה וההתהוות הוא מהות ממהות כו', רק שבא\"ק\nהכלים הן מהות א\"ס עדיין, דא\"ק בכלל נק' א\"ס בהשאלה כו' וכמשנת\"ל פס\"ו, ובאצי' נעשים בבחי' מהות כלים וזהו ע\"י הרושם הנ\"ל שהוא כמשל הגרעין כו'). וכן י\"ל בהתהוות הכלים דעקודים בחי' רושם הנ\"ל שנעשה מן האור (והיינו ג\"כ מהתעבות האור כו'), שזהו כמו עד\"מ התהוות אילנות ופירות מכח הצומח שלא ע\"י זריעה שתחלה מתהווה ומתגשם מכח הצומח שרש האילן והפרי ועי\"ז צומח מציאו' הפרי כו', וכמו\"כ בהתהוות הכלים שהאור מתגשם ע\"י ההמשכה והסילוק עד שנעשית כלי כו'. וכ\"ז אינו פועל שום שינוי בהמקור כלל, וכמו שהתהוות הפרי אינו עושה שום שינוי בכח הצומח שיכול להצמיח עד אין שיעור, וכמו עד\"מ מחשבת האדם שנמשך מכח המח' שבנפש שאינו עושה שום גרעון בכח המח' שיכול לחשוב מח' עד אין קץ כו', וכמו\"כ הוא בהתהוות הכלים שאינם עושים שום שינוי וגרעון ח\"ו.\n<span data-k=\"ks\"><b>קיצור.</b> והענין הוא דהנה הכלי דעקודים היא ע\"י שהאור הניח רושם, וזהו בחי' הגרעין שעי\"ז בא האור בבחי' מציאות באצי', שע\"י הכלי דעקודים</span>"],[3601330422,"<b>מציאות</b> והגבלת האור חוץ לעקודים, וי\"ל דרושם הוא כמו פרסא שמעלים ומגביל יותר מכלים, ובשרשו הוא בחי' הרשימו שע\"י בא הקו בבחי' מדה וגבול, וכמו\"כ כלים דאצי' מכלים דא\"ק ע\"י הרושם דעקודים, וכמו התהוות הפרי מכח הצומח שמתהווה השרש ועי\"ז נעשה צמיחת הפרי, וכ\"ז אינו עושה שינוי בהמזל וכח הצומח, וכמו\"כ הוא למעלה.\nקלג) <b>ועפ\"ז</b> יובן מ\"ש ויקרא שם אברם בשם הוי' אל עולם, שנא' אל עולם ולא העולם היינו שאין העולם דבר בפ\"ע כ\"א הוא אלקות, וכמו מהות הפרי שזהו הארה (או מהות) כח הצומח רק שבא בהגשמה כו', כמו\"כ הכלים הן הן האור שמזה נעשה הכלים שזהו הרושם הנ\"ל (וכן בשרשם הן בחי' הכלים דא\"ק ובשרש שרשן הן בחי' אותי' הרשימו שהן אותן האותי' עצמן שהיו לפה\"צ שלא נתחדש בהם שום דבר רק שע\"י הצמצום וסילוק האור מן האותיות נעשו בבחי' מציאו' דבר כו' וכמ\"ש במ\"א), רק שזהו כמו שהאור בא בהגשמה כו', וכ\"ה בכל הנבראים וכמ\"ש בסש\"ב ח\"ב פ\"ג שכל הנבראים הן אור וזיו המתפשט מהכח האלקי השופע עליהם ומהווה אותם כו', שההארה אלקי' עצמה באה בהגשמה ונעשה בבחי' מציאות דבר כו', וזהו אל עולם שהעולם הוא אלקו' ממש כו', וזה גילה והמשיך אברהם אע\"ה שקרא אל עולם כו'. והענין הוא דהנה כתי' רם על כל גוים ה' על השמים כבודו, והיינו שאומרים שעל השמים כבודו ועזב ה' את הארץ ח\"ו, וזהו לפי טעותם שחושבים דהמשכת החיות ממנו ית' להעולמות הוא בדרך עו\"ע,\nוהנה בעו\"ע יש ב' ענינים הא' שממהות העילה מתלבש בהעלול וכמו שכל ומדות הרי ממהות השכל מתלבש בהמדות רק שזהו חיצוניותו לבד כו', וממילא ה\"ז פועל שינוי בהעילה כו', והב' דמהות העלול אינו מהות העילה וכמו שהמדות הן מהות אחר ממהות השכל, וענין ההתהוות בזה הוא רק בחי' התגלות לבד שהמדות מתגלים ע\"י השכל, והיינו שיש מציאות המדות קודם ומתגלים ע\"י השכל ואם לא הי' מציאות המדות לא היו מתהווים מן השכל כו'. וכ\"ה בעו\"ע בשכל גופא וכמו ברב ותלמיד שהתלמיד מקבל ההשפעה מהרב ונעשה עי\"ז בעל שכל הלא זהו כשהתלמיד הוא בר שכל בעצמו דאם אינו בר שכל הרי לא יתהווה עי\"ז שכל אצל תלמיד כ\"א כאשר בר שכל פועל בו השפעת הרב התגלות כח שכלו שיהי' בעל שכל כו', ואופן הפעולה וההתגלות הוא ע\"י התלבשות מהות העילה שנתפס בזה, וכמו כשמגלה מדה זו לא יגלה מדה אחרת וכ\"ש בהשפעת השכל שנתפס בזה כו', ולכן בעו\"ע צ\"ל שיהי' בערך זל\"ז שהמדות הן בערך השכל וכן בהשפעת השכל צריך שיהי' המשפיע ומקבל בערך זל\"ז כו'. ולפי טעותם שכ\"ה בהמשכת החיות ממנו ית' שבדרך\nעו\"ע אומרים דהשמים הוא בערך והארץ אינו בערך כו', אבל באמת אינו כן דהשמים ג\"כ אינו בערך האלקו' כמו הארץ וכמ\"ש המשפילי לראות בשמים ובארץ כו', והתהוות העולמות מאתו ית' הוא רק מהארה לבד שאינו פועל שום שינוי ח\"ו בו ית', וענין ההתהוות הוא שמהות הנבראים ממש נתהוו מאלקו', והיינו מההארה שמאתו ית' שההארה גופא נעשה מהות נברא כו', וכמו שהארת כח הצומח מתעבה ומתגשם ומתהווה מהות פרי וא\"ז פועל שום שינוי בכח הצומח כו', כמו\"כ הוא למע' שההארה אלקי' עצמה מתגשם ונעשה מציאות נברא כו'. וזהו שגילה אברהם והודיע בעולם וקרא אל עולם שהעולם הוא אלקו' כו'. וזהו"],[3601330423,"שאמרז\"ל עד אברהם לא הוה זקנה, ופי' הה\"מ ז\"ל דהכוונה שלא הי' התגלות בחי' יגת\"ד עד אברהם שקרא אל עולם. והענין הוא דהנה ידוע דהשערות הן ממותרי מוחין לבד שהרי כשחותכין השערות אינו מרגיש כאב, ומ\"מ יש בהם קצת חיות מהמוחין שהשערות המה חלולים שבהם מתלבש החיות כו', והנה מהות השערה היא גופא היא מהחיות שבמוח שמתעבה ומתגשם ונעשה שערה, והתהוותה הוא באופן כזה שנעשה כמו דבר נבדל לגמרי מן הגוף עד שאינו מרגיש שום כאב כשחותכין אותה, ובאמת היא מהחיות גופא שנעשה מציאות שערה כו'. וכמו\"כ הוא בהתהוות הנבראים שהן אור וזיו המתפשט מכח השופע כו' שהיא ההארה האלקי' ונתהווה מהות נברא כו', וזהו שגילה אברהם אע\"ה והודיע זה בעולם ועי\"ז המשיך גילוי יגת\"ד דשם אל הוא תיקון הראשון מיגת\"ד כו', ובאמת התהוות בי\"ע הוא מתיקון הראשון דיגת\"ד וכמ\"ש באד\"ר דקל\"ב ע\"א דתלת עלמין נפקין מתיקונא קדמאה כו' וכמ\"ש בתו\"א בהבי' דמשה ידבר, וזהו דאברהם שקרא אל עולם כנ\"ל המשיך גילוי בחי' יגת\"ד כו'. וזהו שאברהם התחיל להאיר שהמשיך בחי' האור והגילוי\nוהוא בחי' אור זרוע כו', והיינו להיות התלבשות האוב\"כ שעי\"ז יהי' בבחי' מציאות אור ויהי' בחי' גילוי אור כו' וכמשנת\"ל פק\"ל בענין שא' לעולמו די כו', וגם בד\"כ המשכת האור משרשו ומקורו להיות בבחי' מציאות אור כו', והיינו המשכת האורות דע\"ס דאצי' ועי\"ז גם למטה יהי' גילוי אור אלקי כו'. והיינו דכללות המשכת ההשתל' הוא ע\"י האבות כו', כי עד האבות לא הי' עדיין כתיקונו וכמשנת\"ל שם דעד האבות הי' בבחי' התהו כו', והאבות המשיכו בחי' התיקון להיות האור באופן כזה שיהי' בבחי' גילוי בעולמות ובבחי' התלבשות אוב\"כ כו', ועוד בהתהוות הכלים שהן אלקו' והמשיך הגילוי למטה ענין אל עולם שהעולם הוא אלקו' כו'. וכללות ההמשכה הזאת זהו בחי' אל שדי שא' לעולמו די שזהו ההגבלה להיות מציאות דבר כו', וכן בהאור הוא שבא בהתלבשות והתעלמות וכמו ההגשמה ע\"י אמצעי' הגרעין כו', דבאמת זהו תכלית הטוב והחסד לפי שעי\"ז דוקא יכולים לקבל את האור שזהו בחי' הגילוי כו'. והנה בשערי אורה להר\"י גיקטלייא ז\"ל ש\"ב אי' דמשארז\"ל בגמ' שא' לעולמו די ע\"ה שלפי\nהפשוט הפי' בזה כמו שא' שם שהי' העולם מרחיב עצמו עד שאמר לו די, עיקר הפנימי בזה הוא כי במדת אל שדי הוא נותן מזון לכל ברי' וברי' ומשלח ברכותיו לאד' עד שיבלו שפתותיהם מלומר די כו', וכל הברכות והטובות הנשפעות באד' למלאות צורך כל ברי' ע\"י אל שדי הוא כאמרו ואל שדי יברך אתכם כו', והיינו דאל שדי הוא ריבוי ההשפעה ע\"ד מ\"ש והריקותי לכם ברכה עד בלי די שארז\"ל ע\"ז עד שיבלו שפתותיכם מלומר די כו'. ולכאורה נראה שזהו בלתי הגבלה שהרי זהו מה שיבלו כו', אמנם באמת לא כן הוא שהרי זהו מה שהמוגבל יבלה שפתותיו מלומר די שהוא השפעה בשפע וריבוי כו', אבל א\"א לקרות זה בשם בל\"ג דא\"כ לא הי' הנברא המוגבל משיגו כלל כו', גם ממה שקורין זה בשם ברכה וכמ\"ש והריקותי לכם ברכה כו', מובן ג\"כ שזהו בהגבלה, שהרי ענין הברכה ידוע שזהו מה שכבר ישנו במקורו, וכידוע ההפרש בין ברכה לתפלה כו', ומה שכבר יש בשרש ומקור ה\"ז בבחי' הגבלה במדה וקצבה לפי אופן מה שיכולים לקבל כו', ומה שנשפע ונמשך מזה ה\"ז בבחי' מיעוט ובבחי' הגבלה ממש (והיינו מפני שגם\nהמקור מוגבל ע\"כ ההמשכה הוא בבחי' מיעוט כו', דהאור שהוא בל\"ג בעצם אינו שייך בו מיעוט כו' וכמ\"ש במ\"א), והברכה הוא"],[3601330424,"שנמשך כמו שהוא במקורו שזהו ריבוי השפעה וכמו ויזרע יצחק כו' וימצא מאה שערים ויברכהו הוי' שהברכה היא שהי' הצמיחה בריבוי ומ\"מ ג\"ז הוא בהגבלה כו', וזהו ל' והריקותי לכם מל' שמריקין מכלי אל כלי והיינו שמה שישנו במקורו יומשך למטה א\"כ ה\"ז הגבלה כו', והגם שהל' בלי די לכאורה מורה על בל\"ג, הנה רז\"ל שדרשו מ\"ש בלי די עד שיבלו כו' הוציאו זה מל' בל\"ג רק שאינו בבחי' הגבלה כמו די סתם שפי' עד פה תבא ולא יותר, ובלי די היינו יותר מדי (בל\"א אזוי פיל ויפיל גינוג) וכמו די והותר שבמלאכת המשכן ועוד יותר מזה, אמנם בערך וסוג זה יחשב כו'.\n<b>ועפ\"ז</b> יובן מ\"ש אנכי ה' אלקיך אשר הוצאתיך מאמ\"צ, דהנה ידוע שיש מצרים בקדושה והו\"ע ההגבלה כו' והיינו בחי' הגבלת האור שבא במדה ומשקל ומתלבש בכלים המגבילים את האור כו', וענין מ\"ת הוא להיות היציאה מהמיצרים וגבולים והיינו להיות גילוי האור שלא בבחי' הגבלה כו', וז\"ש אנכי ה' אלקיך דהוי' הוא בחי' האור ויש בזה ב' מדרי' בחי' האור כמו שהוא בבחי' שייכות אל העולמות וכמו שהוא בערך העצמו' שגם האור הוא לא בבחי' הגבלה כו', וזהו אנכי הוי' דהגילוי דמ\"ת הי' גילוי ש' הוי' וכמו תורת ה' ומצות ה' כו', והוא בחי' ש' הוי' כמו שהוא מצד אנכי בחי' עצמו' אוא\"ס כו', ואו' אשר הוצאתיך מארץ מצרים, דכל ענין התו' הוא להיות יצי\"מ והיינו היציאה מהמיצרים וגבולים דקדושה כו', ולא נז' כאן בריאת שו\"א מפני שזהו בחי' די סתם שא' לעולמו די להיות בבחי' גבול רק הודיע כאן ענין יצי\"מ שז\"ע מ\"ת כו', וזהו אנכי ה' אלקיך להיות גילוי ש' הוי' כמו שהוא מצד בחי' אנכי ועי\"ז הוצאתיך מאמ\"צ מבחי' מיצרים וגבולים כו'\n<span data-k=\"ks\"><b>קיצור.</b> וז\"ע אל עולם, כמו הפרי שהיא הארת כח הצומח שנתגשם ואין שום שינוי, כן העולם הוא הארת אלקות שבא בהגשמה, ואין שום שינוי כלל, דהנה רם על כל גוים שהן או' שזהו בבחי' עו\"ע שהעלול פועל שינוי בהעילה והעלול אינו מהות העילה, וכמו בשכל ומדות וכן במשפיע ומקבל, ובאמת אינו כן כ\"א כנ\"ל, וזהו עד אברהם לא הווה זקנה ופי' הה\"מ ז\"ל שהמשיך יגת\"ד, וכמו עד\"מ השערות הן עצמן מהחיות שבמוח רק שנתגשמו, כמו\"כ העולם הוא אלקות ושרשם מתיקון הראשון דיגת\"ד, וזהו שהתחיל להאיר שהמשיך אור זרוע שיהי' בבחי' מציאות אור, וגילה שהעולם הוא אלקות כמו בכלים למעלה וכן בהעולם למטה, ובש\"א דש' שדי הוא עד בלי די, והוא ג\"כ המשכה שבבחי' מדה וגבול אך הוא בחי' ריבוי ההשפעה עד בלי די. </span>"],[3601330425,"<h3>בס\"ד. יום ב' דחה\"ש בסעודה, תער\"ג</h3>\n<b>ואשים</b> דברי בפיך ובצל ידי כסיתיך לנטוע שמים וליסוד ארץ כו', וידוע דואשים דברי בפיך קאי על תו' כדאי' בירושלמי, וצ\"ל מהו\"ע שע\"י התו' יהי' לנטוע שמים כו', הלא השמים והארץ כבר נבראו ונשתכללו וא\"כ מהו\"ע שע\"י התו' הוא לנטוע שמים כו'. והנה הרד\"ק פי' דלנטוע שמים וליסוד ארץ קאי על זמן קיבוץ גליות דכנס\"י יהיו אז עולם חדש, וג\"ז צ\"ל הלא התו' נתנה עכשיו שיש עסק התו' גם בזה\"ג ומהו\"ע שע\"י התו' יהי' כנס\"י בבחי' עולם חדש כו'. ולהבין זה ילה\"ק משנת\"ל שהאבות המשיכו תוס' אור להיות גילוי אלקו' ע\"ד מ\"ש והריקותי לכם ברכה עד בלי די עד שיבלו שפתותיכם מלומר די שזהו ריבוי הברכה והשפע, ומ\"מ ה\"ז מה שכבר יש בשרש ומקור שז\"ע ברכה כו'.\nקלד) <b>וביאור</b> הענין הוא, דהנה בפרד\"ס ש\"ח פי\"ג כ' שיש ב' מיני יחודים, הא' הוא להשפיע שפע לקיום העולמות (והוא לחדש הישנות לבד כו'), רק שיהי' במע' עליונה כמו קודם חטא עה\"ד, הב' הוא להמשיך אור חדש ממש כו', ולפי קבלת האריז\"ל היחוד הא' הוא יחוד ישראל סבא ותבונה שנק' או\"א תתאין, והב' הוא יחוד או\"א עילאין שהן עצמו' המוחין כו'. דהנה ידוע שיש בחי' יעקב וישראל סתם הנק' ישראל זוטא, וישראל סבא, וכמ\"ש בזח\"ב דמ\"ג ע\"א ע\"פ כי נער ישראל ישראל זוטא, שמע ישראל ישראל סבא. ובפ' ויקהל דרט\"ז סע\"א שמע ישראל ישראל סבא בגין דאית זוטא דכתיב כי נער ישראל ואוהבהו כו', וב' המדרי' דיעקב וישראל זוטא הן בז\"א (והן ג\"כ בבחי' המוחין הנמשכים בז\"א רק שכ\"ז הוא בפרצוף דז\"א), וישראל סבא הוא בבחי' המוחין כו'. דהנה במאו\"א אות יו\"ד סעי' ל' כ' ישראל נק' מחצה העליון דז\"א, ושם סמ\"ג כ' יעקב נק' חצי פרצוף התחתון דז\"א, והיינו דישראל הוא בחי' ז\"א שלמע' מהחזה והן המדות שמכוסים עדיין בהשכל וההתבוננות המולידם ואינם ניכרים במהות\nומציאות בפ\"ע כו', ויעקב הוא למטה מהחזה שהמדות הן בהתגלות בבחי' מדות מורגשות כו', ויש בהם ג\"כ מוחין רק שהן בבחי' קטנות ולכן המדות הן מורגשות בהתגלות כו', והוא שהמוחין הן רק הטעם של המדה לבד כמו למה יאהב או למה ישנא, ואין בזה התרחבות בהשגת עצם הדבר כ\"א רק שמבין טעם חיוב המדה לבד כו' (וטעם ושכל זה הוא בחי' יעקב כו'), וכמו הפסק דין שבשו\"ע שזהו רק גילוי המדה שזה כשר וזה פסול ויש בזה טעם ההלכה אבל הוא בקיצור רק מה שנוגע להפסק דין לבד, וזהו מה שז\"א מקבל בבחי' חלון לבד וכמו אור השמש המאיר דרך חלון שהוא מצומצם כו'. וכמו כשאדם לומד איזה פלפול עמוק בתלמוד ופוסקים בסברות ובטעמים רבים בהרחבה גדולה כו', ואח\"כ יפסוק הדין כך וכך הרי מה שבא בהתגלות בהפסק דין הוא רק הטעם הקצר וכל ההשגה הגדולה והעמוקה שהי' קודם מתמעט ומתעלם בזה כו'. וכ\"ה בעבודה שהתפעלות המדה היא רק מהטעם של המדה, וכמו לאהבה את ה' אלקיך כי הוא חייך שאינו מבין את ענין האור והחיות האלקי רק שמבין כי הוא חייך דמבשרי אחזה אלק' כו', וכמו שהאדם\nמרגיש בעצמו שיש בו חיות המחי' אותו והעיקר הוא החיות וע\"כ הוא אוהב את נפשו שרוצה גילוי החיות כו', וכמו\"כ הוא מבין שהעיקר הוא האור והחיות האלקי וע\"כ הוא אוהב את האלקו' ורוצה להיות גילוי"],[3601330426,"אלקות כו', וזהו רק טעם המדה והאהבה לבד כו', וגם כשההתבוננות היא בהתרחבות יותר היינו באופן האור והחיות האלקי כו', אך היא בחי' חיצוני' השכל דהיינו בחי' השכל השייך אל המדות שהמדה הנולדה מזה היא רק מהבכן לבד ואינו מאיר אור המוחין בעת התפעלות המדה כו'. אמנם המדות שהן למע' מהחזה הוא שמאיר בהם אור המוחין בבחי' התרחבות לא בבחי' חלון לבד, והוא כשההתבוננות הוא בעומק ופנימי' הענין ובהתקשרות גדולה בהענין עד שהלב מתפעלת בעצמה בעת ההשגה וההתבוננות, ואינו מרגיש את התפעלות הלב מחמת עוצם התקשרותו בשכלו, והאהבה אינה תופסת מקום לעצמה מפני שהיא כלולה בהשכל והיינו שהיא מכוסה באור השכל וההתבוננות כו', והאהבה היא בתוקף יותר שהרי המדה כשהיא בקירוב אל השכל נותן בה השכל חיות ומחזק אותה, וכשהיא בהתכללות שכלו והיא תמיד אצל השכל אזי היא בודאי יותר חזקה רק שאינה מורגשת כו' (והנה הגם שבזה הוא התגברות המוחין מ\"מ ה\"ז בכלל מדות והוא בחי' גדלות המדות שע\"י המוחין דגדלות כו' כי מוחין בעצם הוא שאינו נעשה מזה התפעלות הלב\nלהיות שזהו למע' מענין המדות כו', אבל זה שמתפעל בלב הגם שזהו מהתרחבות המוחין (וכמו אורייתא הוא דקא מירתח בי' שזהו מהתרחבות המוחין בגילוי אור השכל ביותר כו'), וגם אפי' מה שמתפעל בלבו מעומק המושג כו' (וכמו גחין ר\"ש ונשיק כו') וכמ\"ש במ\"א, כ\"ז אינו עדיין עצמו' המוחין ממש דכאשר הענין הוא בעצמו' המוחין ממש אין בזה שום התפעלות כלל, וכאן מאחר שמ\"מ מתפעל בלב א\"ז עצמו' המוחין ממש כ\"א בחי' גדלות המוחין השייכים למדות כו'). ובחי' זו נק' ישראל לי ראש להיות שבמדרי' זו הוא התגברו' המוחין כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והענין דהנה יש ב' מיני יחודים, יחוד ישסו\"ת או\"א תתאין, ויחוד או\"א עילאין, דהנה יעקב הוא למטה מהחזה חו\"ג המגולים, והוא מקיצור הטעם כי הוא חייך, גם בהתרחבות ההשגה אך בחיצוניות המוחין, המדות באין מהבכן והן מורגשים, וישראל למעלה מהחזה חו\"ג המכוסים שבאים מפנימיות המוחין שמאיר גם בלב, והאהבה הוא בתוקף ביותר אך בלתי מורגשת, וכ\"ז פרצוף המדות. </span>\nקלה) <b>אמנם</b> ענין ישראל סבא הן בעצם המוחין שלמע' מהמדות שבלב, והיינו שזהו בפרצוף המוחין עצמן, רק שבמוחין גופא זהו בחי' המדות שבהם דבחי' יש\"ס הוא בחי' מדות שבחכ' ותבונה זהו מדות שבבינה כו', וענין מדות אלו א\"ז שהן בבחי' התפעלות וכדוגמת התפעלות המדות שבלב כו'. דהנה במדות שבשכל יש ב' ענינים, הא' הוא בחי' התפעלות שכלי והיינו מה שבשעת ההשגה וההתבוננות מתפעל בשכלו על האלקו' באהבה או ביראה לפי נושא ההתבוננות כו', שזהו בחי' התפעלות ממש כמו במדות שבלב רק שהן בדקות (וגם בזה י\"ל שיש חו\"ג מגולים ומכוסים דכאשר ההתבוננות הוא בעומק ופנימי' הענין אז ההתפעלות הוא בלתי מורגשת וכאשר היא בחיצוני' לבד ה\"ה מורגשת יותר כו', והיינו מפני שנרגש בזה הבכן דגם בעת ההתבוננות אינו מקושר כ\"כ בהענין המושג ונרגש אצלו יותר העילוי והיוקר כו', דכאשר ההתבוננות הוא בעומק ופנימי' הענין הרי שכלו טרוד בעצם הענין ואינו מרגיש כלל את העילוי והיוקר דאלקו' כו', ובודאי שבהשגה זאת יש בזה עילוי גדול (א שטארקע רייכקייט), אבל אינו עומד"],[3601330427,"בהמורגש הזה, משא\"כ כשההתבוננות הוא בבחי' חיצוני' השכל אין שכלו טרוד כ\"כ בעצם הענין וע\"כ הוא עומד במורגש הבכן שהוא היוקר דאלקו' כו'), וכמו שהוא בחכ' אינו בבחי' התפעלות כ\"א בבחי' דבקות שזהו בבחי' מדות שבחכ' כו' וכמ\"ש במ\"א. אמנם יש בחי' מדות שאינם בבחי' התפעלות כ\"א הן בבחי' הטי' והמשכה שז\"ע מדות להיות שהמדות הן בבחי' התגלות, שזהו ההפרש בכלל בין מוחין למדות דמוחין בכלל הן למע' מבחי' גילוי והתפשטות והמדות הן בבחי' גילוי והתפשטות כו'. וזהו יסוד הענין המבו' בכ\"ד שהמוחין א\"צ לזולת והמדות א\"א בלי הזולת, מפני שעצם ענין המדות הן ענין הגילוי וההתפשטות כו', וע\"כ א\"א להמדות בלתי זולת למי שיתגלה ויתפשט כו', אבל המוחין בעצם מהותם אינם בבחי' הגילוי וההתפשטות כו', ע\"כ אינו מוכרח כלל אל הזולת כ\"א יוכל להשכיל השכלות לעצמו כו'. וסיבת ההפרש הזה הוא מפני שהמוחין הן עצמי' וכל עצם בלתי מתגלה ומתפשט, והמדות הן הארה לבד וההארה היא בבחי' התפשטות והתגלות כו' (וי\"ל שזהו ג\"כ ההפרש בין רצון לעונג, דרצון הוא בבחי'\nמרוצה והמשכה שנמשך לאיזה דבר כו', וע\"ה שזהו המשכת והטיית העצמות כו', מ\"מ זהו מה שהעצם נמשך לאיזה דבר כו', וה\"ז רק הארת העצמו' כו' (ולכן שם רצון שייך בהאור רק כמו שבא בבחי' מקיף לעולמות אבל על האור בעצם אינו שייך שם רצון כו' וכמשנת\"ל פנ\"ז), והעונג אינו בבחי' המשכה והתפשטות, ולכן שייך תענוג גם לעצמו וכמו שמתענג מעצם העצמות שלו כו' וכמ\"ש במ\"א). וע\"כ המוחין גם כמו שהן לעצמו אינם בבחי' התפשטות ובבחי' ירידה אדרבה הן בבחי' עלי' דוקא, וכנודע דבכל עו\"ע הג\"ר שבהעלול הן בבחי' דבקות בהעילה שלמע' ממנו, והוא מה שמשיג את עילתו והוא בבחי' התקשרות ודביקות בהעילה כו', ובד\"כ עצם ענין המוחין הוא שהן בבחי' הבדלה לגמרי מהדבר הנבדל ממנו, וכמו טבע המוחין דגדלות להיות בבחי' הבדלה כו', אך בחי' המדות שבמוחין הן הטיית והמשכת המוחין להיות בבחי' ירידה והמשכה כו', וכמו שכל המטה כלפי חסד או כלפי דין שזהו הטיית השכל, דהרי השכל עצמו הוא השגת הענין בעצם ואין המדות דחו\"ג ניכרים בו עדיין ואינו יודע עדיין איזה מדה יהי' מזה,\nוהמדות הן ירידת השכל להיות מזה הטי' לחסד או לדין כו', וא\"ז עדיין הטעם של המדה כי זהו בעצם השכל עדיין, כי הטעם של המדה הוא שהשגת עצם הדבר מתעלם בזה ואינו נשאר רק הטעם בקצרה, אבל כאן עדיין מאיר אור השכל היינו השגת הענין וכמו שהוא בתוקף ההשגה ה\"ה בא אל המדה ואין המדה מבלבל אל ההשגה כו'. דהנה אנ\"ר שבשעת השגת הענין ה\"ה למע' מהמדה הבאה מזה, ואם בשעת מעשה יתקרב אל המדה הבאה מהשגה זו ה\"ז מבלבל לו אל ההשגה ומתעלם אצלו ההשגה בעת ההיא כו', וענין המדות אלו הוא כח הטיית המוחין אל המדות שאין המדות מבלבלים כלל אל המוחין, והיינו שגם בההטי' אל המדות הוא בבחי' תוקף אור המוחין שמאיר אצלו בגילוי ממש כו' (ובודאי שאינו בשלמות כמו שהוא בההשגה עצמה, ומ\"מ מאיר בזה אור השגה בעצם הענין), רק שבא לזה איך שזה מחייב חסד או דין כו', ובחכ' בחי' מדות שבחכ' הוא איך שמצד התאמתות השכל באה המדה לחסד ולדין או לאיסור והיתר כו', וכידוע בענין שתיק רב שלא מצא טעם והשגה לאיסור, אך לא יוכל לומר להיפך מפני ששכלו מטה כך מצד ההתאמתות שבשכל כו', ובבינה בחי' המדות שבה הוא שמהשגת הענין בעצם בא לידי הטי' לחסד ולדין בטוב טעם בסברות"],[3601330428,"המחייבות כו', וזהו למע' מבחי' המדות שבשכל שהן בבחי' התפעלות שכלי כו' (וגם למע' מההתבוננות והשגה האלקי' שלהוליד ההתפעלות שבלב גם מה שמתפעל ממילא מהתרחבות ועומק ההשגה), שכ\"ז הוא בהשכל השייך למדות. אבל מדות אלו שהן בבחי' הטי' אין בהם שום התפעלות כלל, והכל הוא בעצם השכל שגם בההטי' מאיר אור השכל רק שא\"ז עצם השכל ממש כ\"א שבאור עצם השכל מטה לחסד ולדין כו' (וע\"ד כמו שהרצון מטה את הנפש כמו\"כ בדוגמא כזאת הוא מה שהמדות מטים את אור השכל כו').\n<span data-k=\"ks\"><b>קיצור.</b> אמנם ישסו\"ת הוא פרצוף המוחין והן מדות שבמוחין, יש\"ס מדות שבחכ' ותבונה מדות שבבינה, כי הנה יש ב' בחי' מדות במוחין, הא' התפעלות שכלי, ובזה יש ג\"כ חו\"ג מגולים דהיינו שבשעת ההשגה נרגש היוקר, וחו\"ג מכוסים שמפני טרדת עומק ההשגה גם היוקר אינו נרגש, והב' מדות שאינן בהתפעלות כלל רק הטיית השכל, דעצם ענין המדות הוא הטי' והתפשטות, והוא הטיית עצם השכל כמו הרצון שהוא הטיית עצם הנפש, והיינו שבעצם השכל בא לידי מדה, ומדות שבחכ' היא שבא מתוך ההתאמתות, ובינה היא שמהשגת הענין בעצם עומק הענין בא לידי מדה. </span>\nקלו) <b>וז\"ע</b> שערי בינה שהן שערים נפתחים להיות הטיית והמשכת ההשגה כו', כי בעצם השכל דהיינו בהשגת עצם הענין לא נודע עדיין מה יולד מחמתה כו', וכאשר נפתח ממנו פתח לפסק דין לזכות כו' שזהו שכל המטה כלפי חסד כו', הנה פתיחה זו מעצם השכל וההשגה נק' שער וכמו השער שעומד בסוף החצר כשרוצה לצאת כו', כך מה שהשכל בעצם כמו שהוא במושג יוצא לדון בכח זה לחסד או לדין ה\"ז נק' שער כו', וכמו השגת הנשמה שבג\"ע שזהו מבחי' בינה דמל' דאצי' ה\"ז ג\"כ ע\"י השערים דבינה מה שנמשך מבחי' הבינה ההשגה אלקי' לנשמות ויהיו נהנין מזיו השכינה כו', הרי ענין השערים א\"ז ענין התפעלות שכלי כ\"א מה שבהם וע\"י נמשך ההשגה לנשמות כו'. וההמשכה הוא ע\"י שערים להיות כחו\"ח לפוש\"ד, דנשמות שהן מבחי' החסד מקבלים מהשערים שמבחי' חסד דבינה כו', וכמו\"כ ענין השערים הנ\"ל שבהם המשכת השכל וההשגה עצמה כו', שכ\"ז למעלה מבחי' התפעלות שכלי שזהו ג\"כ בשכל ונק' ג\"כ שערים, והיינו להיות מזה היציאה במדות שבלב להתפעל בלב שזהו יציאה לחוץ יותר דהיינו למדות שבלב\n(ועצם ההשגה מתעלם בזה כו', וגם כללות ענין ההשגה הוא באופן אחר כו' כנ\"ל), וא\"ז מה שעצם ההשגה יוצאה בזה רק ההארה השייכה להמדה כו', משא\"כ ההשגה האלקי' מצד עצמה טרם שתתפעל באה' גם במוח רק שנק' שכל המטה כלפי חסד א\"ז רק מה שיוצא עצם ההשגה האלקי' לאופן פרטי כו', וה\"ז יציאה פנימי' שאינו יוצא עדיין חוץ לעצם השכל כו' (וזהו דאי' בזהר שיש תרעין עילאין ותרעין תתאין דעם היות דתרעין תתאין הן במל', הנה באמת בבינה עצמה יש ב' בחי' שערים הנ\"ל, וז\"ש ב\"פ שאו שערים ראשיכם שהן ב' מיני שערים תרעין תתאין בבחי' יציאה לחוץ מן המוחין להיות תולדות המדות (ומוחין אלו הן השייכים למדות כו'), ותרעין עילאין הן פתיחת אור עצם ההשגה להטות לחו\"ג, וכמו נשמות בג\"ע שנהנין מזיו השכינה זה נהנה כך וזה נהנה כך כו'). וזהו בחי' המדות שבמוחין"],[3601330429,"בכלל, ובפרטיות ענין ישסו\"ת הן בחי' נה\"י דאו\"א, דיש\"ס הוא בחי' נה\"י שבחכ' והוא בחי' כח הגילוי שבחכ', והיינו מה שיש בחכ' הכח להיות בבחי' התפשטות והתגלות חוץ לעצמו של חכ' כו', ויש בזה ב' מדרי' הא' כח הגילוי לעצמו דחכ' בעצם הוא למע' מהשגה כנודע ויש בה הכח להיות בא לידי השגה כו', והב' כח הגילוי אל הנבדל ממנו, והו\"ע כליות יועצות איך להשפיע והוא להמציא ענינים איך להביא את הענין שכלי אל הזולת כו', והן מאזני השכל והחכ' איך שיבוא הדבר חכ' לידי השפעה כו' (גם י\"ל שזהו המדידה בנקודת החכ' מה שאפשר לבא ממנה לידי השפעה אל הזולת כו'). ותבונה ידוע שהו\"ע קליטת הדבר שקולט את ההשגה בכלי מוחו, והוא ביותר בהכלים שכלי מוחו הן כלים לקבל אור שכל לתפוס ולקלוט אותו והו\"ע ההתיישבות בכלים וזהו הנק' תפסן שיש לו חוש לתפוס כל דבר כו', רק שיש תפסן חיצוני והיינו שיש לו חוש רק לתפוס לבד ואינו יודע ומשיג את הענין שתופס רק תופס חיצוני' הענין, וכאן הכוונה שהתפיסא היא בבחי' קליטה והוא שהדבר נתפס ונקלט בכלי שיודע ומשיג את הדבר\nבטוב מאד, והאור מתעלם בזה שאינו מאיר בגילוי כ\"כ אבל הענין בא בבחי' קליטה והתיישבות שיודע את הדבר היטב ומתאחד בכלי מוחו כו', וזהו הכלי לבחי' נה\"י דאבא לידע איך להשפיע את הענין לשנותו ולהביאו בכמה ענינים שונים כו', וז\"ש מים עמוקים כו' איש תבונות ידלנה שדולה ומשקה לאחרים, והיינו שע\"י שנקלט אצלו הענין בטוב ביכולתו להביא את הענין אל הזולת כו' (ובעבודה י\"ל ענין התבונה הוא להיות שבכל השגה אלקי' צ\"ל איזה מדה כו', ויש ענינים שלכאורה אינו נראה בהם השייכות שלהם לאיזה מדה, וענין התבונה הוא שבכל ענין שכלי ה\"ה מוצא את המדה הבאה מזה כו').\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש ואשים דברי בפיך כו' לנטוע שמים כו', דהנה שמים וארץ הן בחי' חו\"ב, ומצינו דמשה אמר האזינו השמים ותשמע הארץ, וישעי' אמר שמעי שמים והאזיני ארץ, ומבו' במ\"א שהן בחי' או\"א עילאין ואו\"א תתאין כו'. דהנה בחי' ישסו\"ת הגם שהן בפרצוף המוחין מ\"מ ה\"ז בבחי' ס' השתל' וכמשי\"ת, ואו\"א עילאין ה\"ז גילוי אור חדש והו\"ע השמים החדשים והארץ החדשה כו', והמשכה זו הוא ע\"י התו' דכל ענין התו' הוא להמשיך גילוי אור חדש דוקא שזהו מבחי' יחוד פנימי דאו\"א כו'. וז\"ש שע\"י ואשים דברי בפיך עי\"ז דוקא לנטוע שמים כו', דהגם שהשמים כבר נבראו ונשתכללו זהו כמו שהוא ע\"פ ס' השתל' בלבד דבכללות הוא בחי' הארה לבד כו', אבל ע\"י התו' הוא לנטוע שמים בחי' שמים וארץ החדשים בחי' או\"א עילאין כו', וז\"ש הרד\"ק דקאי על קבוץ גליות, דהנה אי' בפע\"ח דבחי' פנימיות אבא פנימי' עתיק זה לא נתגלה עכשיו ולעתיד יהי' גילוי זה והו\"ע גילוי עצמי' דאו\"א וכמשי\"ת. וזהו דכנס\"י יהי' אז עולם חדש והיינו גילוי נשמות חדשות שהן מפנימי' עתיק והו\"ע\nהשמים והארץ החדשים כו', וכמ\"ש בלקו\"ת בסופו בד\"ה כי כאשר השמים החדשים, וכ\"ז הוא ע\"י עסק התו' דעכשיו כו', וזהו ואשים דברי בפיך שע\"י עסק התו' עי\"ז לנטוע שמים כו' גילוי בחי' או\"א עילאין שז\"ע השמים והארץ החדשים כו', ונש\"י יהיו אז בבחי' עולם חדש היינו שיתגלו הנשמות החדשות כו'."],[3601330430,"<span data-k=\"ks\"><b>קיצור.</b> וז\"ע שע\"ב הטיית עצם השכל שבא לידי מדה, ולמעלה משע\"ב להולדות המדות, והו\"ע ב\"פ שאו שערים ראשיכם, ובפרטיות יש\"ס מדות דחכ' להביא השכל לעצמו או להמציא עניני ההסבר, ותבונה קליטת הענין, תפסן פנימי, וגם לשנות עניני ההסבר בכמה אופנים. ובזה יובן מ\"ש ואשים דברי בפיך, דשו\"א הן חו\"ב, ודישעי' הן או\"א תתאין ודמשה או\"א עילאין שזהו ע\"י התורה, וזה ואשים דברי כו' לנטוע שמים כו', וברד\"ק דקאי על קבוץ גליות והו\"ע נשמות חדשות.</span>"],[3601330431,"<h3>בס\"ד. ש\"פ בהעלותך, תער\"ג</h3>\n<b>בהעלותך</b> את הנרות אל מול פני המנורה יאירו שבעת הנרות, וצ\"ל מהו פני המנורה שא' אל מול פני המנורה יאירו כו', גם צ\"ל דהול\"ל ששת הנרות דע\"פ פשוט פני המנורה הוא הנר האמצעי, וא\"כ הול\"ל ששת הנרות מהו שבעת הנרות. והנה רש\"י הביא בשם המדרש כשראה אהרן חנוכת הנשיאים חלשה דעתו, א\"ל הקב\"ה חייך שלך גדול משלהם שאתה מדליק ומטיב את הנרות, וצ\"ל במה גדול הדלקת הנרות מקרבנות הנשיאים כו'. ולהבין כ\"ז ילה\"ק משנת\"ל דישסו\"ת הן בחי' מדות דחו\"ב, וא\"ז בחי' מדות שבשכל שהן התפעלות שכלי כ\"א בחי' המדות שבפרצוף המוחין עצמן והיינו הטיית והמשכת המוחין, דהמוחין בעצם הן בבחי' הבדלה ואינן בחי' ירידה והמשכה והמדות הן התגלו' המוחין כו', ובפרטי' ישסו\"ת הן בחי' נה\"י דאו\"א שזהו המשכת המוחין למהות נבדל מהם כו' והו\"ע מים עמוקים כו' איש תבונות ידלנה שדולה ומשקה לאחרים כו'.\nקלז) <b>והנה</b> אי' בע\"ח שי\"ד פ\"ד דישסו\"ת הן באות ה' דש' הוי', ונת' שם דאו\"א עילאין הן באות י' דהמילוי ו\"ד הוא בינה והכל נכלל בהיו\"ד, ואו\"א תתאין הן באות ה' ראשונה שכתיבתו הוא שעושין תחלה יו\"ד ואח\"כ עושין ממנו הה\"א והן ישסו\"ת דבכלל הוא בחי' בינה כו', ונודע דיו\"ד דשם הוי' הוא בחי' אצי' שבאצי' דהיינו עצמיות האצי' כו' ואות ה' בחי' בינה בחי' בריאה שבאצי' כו', דבאבי\"ע שבאצי' בחי' הבינה שהיא ה' ראשונה דש' הוי' היא ברי' שבאצי' וחכ' שהוא אות י' דש' הוי' הוא בחי' אצי' שבאצי' כו'. וידוע דאצי' הוא בחי' גילוי המהות דאלקו' והוא שמאיר שם מהות אור הקו כו', דזהו כללו' ההפרש שבין אצילו' לבי\"ע, דבעולמו' בי\"ע הוא בחי' ידיעת המציאו' לבד ובאצי' מאיר גילוי המהות דאלקו' והיא מהות הקו כו', וע\"ה שהקו בכלל הוא בחי' הארה לבד מעצמו' אוא\"ס כו', ומה שמאיר באצי' הוא רק הארת הקו כו', מ\"מ הארה זו מושגת באצי' מהות ההארה כו', וכמ\"ש במ\"א בענין השגת הנשמו' בג\"ע שנהנין מזיו השכינה שהוא בחי' השגת המהות, דהרי מציאו'\nאלקו' ידוע בעולמו' ג\"כ, וההתחדשות דג\"ע הוא ששם משיגים הנשמות מהות האלקו' כו' וכמ\"ש במ\"א, ע\"ה דכללו' הגילוי בג\"ע הוא רק זיו והארה מאצי' (וכל הארה הוא רק בחי' המציאו' לבד), ומ\"מ הארה זו היא בג\"ע בבחי' השגת המהות כו'. ובאמת מה"],[3601330432,"שבאצי' הוא רק הארת הקו היינו בבחי' החכ' שהיא ראשית ההשתל' שזהו בחי' חיצוני' החכ' כו', אבל בעצמו' החכ' מאיר עצמו' הקו כו', דהקו עם היותו בד\"כ הארה לבד מ\"מ במדריגתו העצמי יש בו עצם והארה כו', ובעצמו' החכ' מאיר עצם הקו כו'. ועוד זאת שהרי הקו גופא יש בו חיצוני' ופנימיות ומה שהקו הוא רק הארה מאוא\"ס ב\"ה זהו בחי' חיצוני' הקו, אבל פנימי' הקו הוא בחי' פנימי' ועצמי' א\"ס ב\"ה. דהנה במ\"א מבו' דהמשכת הקו הוא ע\"ד לעולם ישנה אדם לתלמידו בדרך קצרה, דההשפעה בדרך קצרה אין הכוונה שמעלים ממנו ההשכלה ואינו מגלה לו רק אפס קצהו לבד, כ\"א הכוונה הוא שמשפיע לו כל ההשכלה גם עומק והפנימי' שבההשכלה רק שמשפיע לו בדרך קצרה באופן שיכול לקבל, ובהעלם יש בזה כל העומק והפנימי' כו', ולכן לאחר ארבעין שנין קאים אינש אדעתא דרבי' שזהו עומק ופנימי' כוונתו וכמ\"ש במ\"א, והיינו מפני שבההשפעה שהשפיע לו יש בזה בהעלם כל הפנימי' כו'. והדוגמא מזה יובן בהמשכת הקו דבפנימיותו יש בזה בחי' פנימי' ועצמו' א\"ס ב\"ה, דכשם שנקודת הרשימו הרי לבד מה\nשכוללת כל האור שיהי' נמשך בכללות ההשתל' הרי יש בה בהעלם כל עצמו' האור שאינו בערך ההשתל' כלל כו' וכמ\"ש במ\"א, כמו\"כ הוא בהקו שבבחי' הפנימי' שבו יש בו בחי' העצמות דא\"ס כו', ובעצמות החכ' מאיר בחי' פנימי' ועצמי' הקו כו'. וזהו\"ע שעל התורה נא' כאשר יאמר משל הקדמוני דאורייתא מחכ' נפקת ה\"ז בבחי' משל לא\"ס קדמונו ש\"ע כו', וידוע דמשל הוא ענין הפרסא וכמ\"ש בתו\"א ד\"ה פתח אליהו, ומבו' שם שיש יתרון בהמשכה שע\"י פרסא לגבי ההמשכה שע\"י צמצום, דענין הצמצום הוא סילוק האור והעדרו כו', משא\"כ פרסא הרי מהות האור מתלבש ומתעלם בהפרסא וכמו שמהות הנמשל ממש מלובש בהמשל כו', וא\"כ התו' שנק' משל הקדמוני היינו שבחכ' נמשך האור לא ע\"י הצמצום רק דרך פרסא, והיינו שיש בזה בחי' מהוע\"צ האור כו'. וביותר יובן ע\"פ השטה המבו' כאן דגם בשרש הקו כמו שהוא באוא\"ס שלפה\"צ יש שם ע\"ס שהן ע\"ס הגנוזות באוא\"ס כו', וא\"כ כשם שבחכ' דאצי' שורה אוא\"ס ב\"ה דהיינו בחי' עצמו' הקו כו', כמו\"כ צ\"ל דבחכ' שבע\"ס הגנוזות מאיר בחי' פנימי' א\"ס כו'. וענין הצמצום\nנת\"ל פכ\"ב שזהו רק להיות ספי' פרטי' דהיינו שספירת החכ' תהי' נמשכת ספי' מיוחדת בעצמה והיא היא אותה החכ' שבע\"ס הגנוזות כו', וכמשנ\"ת שם פכ\"ג המשל מתי' ברוך כשמפרידין הב' בפ\"ע שהוא אותו הב' שבתי' ברוך כו', וע\"ה שיש בזה מיעוט האור כמשנ\"ת שם, מ\"מ ה\"ה אותה החכ' כו', וא\"כ הרי בחי' פנימי' ועצמו' א\"ס ב\"ה שבבחי' חכ' דע\"ס הגנוזות נמשך ע\"י פנימי' הקו בבחי' עצמי' החכ' דאצי' כו', וכ\"ז בחכ' דוקא להיות שהחכ' בחי' ראי' כו' (וגם בהשכלה דחכ' העיקר הוא ההנחה שכלית כו' כמשנת\"ל פמ\"ב). אבל בבינה שהיא בחי' השגה הרי כל השגה היא בריחוק מן העצם שאינו מאיר שם העצמו' כ\"א הארה לבד כו', וכמ\"ש בע\"ח דבבינה מאיר אוא\"ס בריחוק מקום כו', ולכן עיקר ההשתל' הוא מבינה דוקא לפי שהיא הארה לבד כו' וכמ\"ש במ\"א. וזהו שהבינה נק' אלקים חיים דמה שהאוא\"ס נק' בש' חיות הרי כבר הוא בבחי' ירידת המדרי' מבחי' עצמותו שהרי בעצמותו אינו שייך לומר שהוא מחי' החיים כו', וגם מה שיחי' הנאצל מאתו ית' (שז\"ע אלקים חיים דבינה שמחי' את הנאצלים בחי' ז\"א ומל' כו'), ה\"ז בא בבחי' ירידת המדרי' מעצמותו כו', דאוא\"ס עצמו מובדל בערך מהשתל' ולא יתכן שם ענין ול'"],[3601330433,"חיות שהוא מחי' כו', וא\"כ הבינה שנק' אלקים חיים ה\"ז רק הארה לבד כו'. וזהו דישסו\"ת נק' בינה בכלל, דהנה נת\"ל פקל\"ה דישסו\"ת הן בחי' מדות דחו\"ב, ונת' דהמדות בכלל הן בחי' גילוי והתפשטות כו', וכמו\"כ בחי' המדות דחו\"ב הו\"ע ההטי' וההמשכה שא\"ז בחי' העצמו' דחו\"ב כו', ובפרט בחי' נה\"י דחו\"ב שהן איך להשפיע ולהתגלות בדבר הנבדל כו', וע\"ה שכ\"ז בעצם המוחין דחו\"ב שלמע' מבחי' מוחין דז\"א כו' כנ\"ל, מ\"מ ה\"ז בחי' התפשטו' והארה לבד כו', וכנודע דתבונה הוא מקור המוחין דז\"א והיינו בחי' נה\"י דאי' שנעשים מוחין לז\"א (ובתוכם גם בחי' נה\"י דאבא כו'). ומובן ע\"פ הנ\"ל דתבונה הוא בחי' קליטת הדבר וע\"י שקולט את השכל בכלי מוחו עי\"ז יכול להביאו לדבר הנבדל דהיינו בחי' המדות שהן מציאו' נבדל בעצם מהמוחין כו' (ונת\"ל פקל\"ו דקליטת הענין זהו כלי לנה\"י דאבא שהו\"ע כליות יועצות איך להשפיע ולגלות כו'). וע\"כ כ\"ז הוא בחי' בינה שהיא בחי' הארה לבד השייך להשתל' כו', אבל בחי' או\"א עילאין שהן אות י' היינו בחי' פנימי' הבינה שהוא בבחי' השגת המהות כמו בפנימי' חכ' והוא בחי' יחוד פנימי דאו\"א שמאיר בזה עצמו' אוא\"ס ב\"ה.\n<span data-k=\"ks\"><b>קיצור.</b> ובע\"ח דישסו\"ת הן אות ה' דשם בינה, ברי' שבאצי', וחכ' אצי' שבאצי' בחי' מהות ועצמות הקו. וי\"ל דחיצוניות הקו הארה ופנימיות הקו עצמות, וע\"ד דרך קצרה, וכמו בנקודת הרשימו יש בחי' העצמות כמו\"כ בפנימיות הקו, ומאיר בפנימיות חכ', ולכן נק' התורה משל הקדמוני פרסא שהעצם מתעלם בזה, וגם דבחכ' דע\"ס הגנוזות מאיר בחי' הפנימיות והעצמות והצמצום דחכ' הגלוי' היא רק מיעוט, אבל בינה הארה השייך להשתל', ולכן נק' אלקי' חיים, וישסו\"ת להיותם ההטי' אל המדות ה\"ז בחי' בינה, ואו\"א עילאין הן פנימיות חו\"ב דפנימיות בינה היא השגת המהות. </span>\nקלח) <b>והנה</b> להבין איך שבהשגה יהי' בחי' המהות כו', הגם שא\"א להבין זאת עכשיו בבחי' השגה גמורה איך ומה, מפני שכל השגתינו עכשיו היא בבחי' המציאו' לבד כו', מ\"מ להבין אפס קצה מזה שיהי' בזה איזה השערה והנחה בשכל, יובן זה עד\"מ כמו בנקודת ההשכלה דעם היותה שכלי בבחי' שכל גלוי, הרי פנימיותה ועיקרה הוא בחי' הנחה שכלי' לבד, וכמשנת\"ל פמ\"ב דבשכל גלוי ע\"ה שזהו שכלי מ\"מ העיקר בזה הוא ההנחה (דער לייג אין שכל וואס בא עם לייגט זעך אז עס איז אזיי). וזהו הסבה מה שאנו רואים לפעמים באיזה המצאה שכלי כאשר מייגע א\"ע באיזה ענין שאינו מובן לו ונופל לו בשכלו שהוא באופן כך וכך, שבעת מעשה כשנפל לו ההמצאה ניחא לו הענין (עס ווערט עם רעכט און עס איז עם זייער גוט), ואח\"כ כשמתחיל לעיין בהשגתו איך ומה הוא ה\"ה מוצא שאינו מובן עדיין (אז עס איז נאך ניט רעכט), ובאמת הרי הי' הענין ניחא לו (ואינו מדברים במי שמוטעה בדמיונו). אך הענין הוא שזה הי' אצלו רק בבחי' הנחה בשכלו (היינו שההנחה שכלי' הי' יותר מהשכלי), ובההנחה שבשכל\nלהיות שזהו למע' הרבה מהשכלי שם באמת הענין ניחא, ובשכלי לא בא הענין עדיין, ולכן אינו בא גם לידי השגה, והעצה הוא שיקשר עצמו (ער זאל זעך צו טראגין) איך הי' אצלו הענין בעת שנפל לו בשכלו בראשית התגלו' הנ\"ל, ועי\"ז יבוא אצלו הענין בבחי' שכל גלוי"],[3601330434,"יותר (דהיינו שיהי' הרגשת השכלי יותר מהרגשת ההנחה), ואז יבוא הענין ג\"כ לידי השגה כו', וזהו ג\"כ מה שיש כמה ענינים שהן למע' משכל המושג, וגבי חכמים גדולים יש להם מקום בשכלם הענינים האלו לא רק בדרך אמונה כ\"א יש להם מקום ממש בשכלם (עס האט א ארט אין שכל) דזהו בבחי' הנחה שכלי', ולכן א\"א גם להם לבאר הענין מפני שא\"ז בבחי' שכלי ממש, אבל בהנחה שכלי' יש לזה מקום כו', ומכ\"ז יובן דבנקודת ההשכלה העיקר הוא ההנחה שכלי' כו'. והנה כאשר באה בהשגה הרי בהתרחבו' ההשגה בריבוי הפרטים ובריבוי הסבר הרי אינו מאיר בזה ההנחה שכלי' שבהנקודה, שהרי גם דקות האור שהי' נרגש בהנקודה מתעלם בהשגת הפרטים דבינה כנודע, וכ\"ש שההנחה שכלי' מתעלמת לגמרי כו'. אמנם לאחר כל ההשגה כאשר בא אל נקודת התמצית של כל ההשגה ועומק המושג שלה איך שמושג עצם הענין מכל ההשגות פרטי', מאיר בזה עצם נקודת ההשכלה כמ\"ש במ\"א, הנה גם ההנחה שכלי' נרגשת בנקודה זו רק שכאן היא בבחי' השגה, ולא בהשגה ממש שהרי כללו' נקודת התמצית אינה בהשגה גמורה בלבושי השגה שהרי\nזהו בחי' האין דבינה, והוא כמו נקודה דאור בלי לבוש, אבל מ\"מ הוא בבחי' השגה, דהיינו שבאופן ההשגה דנקודת התמצית גם ההנחה שכלי' היא בהשגה באופן כזה ובבחי' התיישבות במוחו, דבנקודת ההשכלה (קודם ההשגה) ההנחה שכלי' אינו בבחי' התיישבות כי ההתאמתות דחכ' היא בהתיישבות, אבל ההנחה הנ\"ל הרי א\"ז ענין ההתאמתות כ\"א הנחה שבשכלי א\"ז בהתיישבות כו', ואחר ההשגה כשבאה בנקודת התמצית ה\"ה בבחי' התיישבות כו', וזהו הנקודה פנימי' דבינה שהיא כלי לפנימי' נקודת החכ' כו'. וכידוע דחכ' דבינה נק' נקודה בהיכלא הנה נקודה הפנימי' הנ\"ל היא היכלו ומקומו דנקודת החכ' שנסתרת שם דוקא (היינו ששם באה בבחי' השגה כו'), ונק' נקודה בהיכלא המיוחד לה וכמו ס\"ת בהיכל כו', וכמו ובהיכלו כולו אומר כבוד שהן ל\"ב נ\"ח כו', והוא בחי' פנימי' דבינה שהוא היכל המיוחד ומקומו של נקודת החכ' כו', והו\"ע מיצר ים ומיצר מי דים הוא בחי' ים החכ' ומי הוא בחי' בינה כנודע, ומיצר ים הוא בחי' פנימי' הנקודה דחכ' המתלבשת בנקודה פנימי' דבינה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ויובן זה דהנה בנקודת ההשכלה העיקר הוא ההנחה שכליות, ובבינה היא השכלי וההשגה, ובנקודת התמצית בחי' אין דבינה שמאיר שם נקודת ההשכלה נרגש שם גם ההנחה שכליות, והיא בהשגה כמו השגת התמצית ובהתיישבות. והו\"ע נקודה פנימיות דחכ' בהיכל פנימי דבינה, וז\"ע מיצר ים ומיצר מי. </span>\nקלט) <b>וענין</b> מה שנק' מיצר ים ומיצר מי, יובן זה עד\"מ במשפיע ומקבל יש בזה ג\"כ חיצוני' ופנימי', והחיצוני' הוא שכאשר המקבל שומע רק חיצוני' השכל והצעת העניני' שבהשכל והיינו שכל ענינו הוא לקבל את המושכל כמו שהוא מושג בלבושי ההשגה, ואינו יורד לתכליתו לידע תכלית הכוונה ותמצית המושג כו', גם המשפיע אינו משפיע לו מעומק אותו השכל רק מחיצוני' שלו, וכאשר המקבל שואל דבר מהמשפיע באותו השכל הרי השאלה היא רק בחיצוני' הענין, המשפיע משיב לו מה שבא לו בהשקפה ראשונה הנק' מושכל ראשון, היינו כמו שנופל לו בהשכלה ראשונה שזהו רק חיצוני' הענין, ואינו משתדל לגלות לו עומקו ופנימיותו"],[3601330435,"של הענין כו'. אמנם יחוד פנימי הוא שהמקבל כאשר שומע דבר מרבו ענינו הוא לשמוע נקודת תמצית אור השפע ותכלית כוונת הרב בהענין הזה, שזהו ע\"י הצמצום דוקא שמצמצם ומכווץ כח השגתו, דהנה בהשגה חיצוני' הנ\"ל אין צריך לכווץ כח ההשגה שלו כ\"א הוא בהתרחבו' לקבל חיצוני' הענין לבד כו', משא\"כ באופן ההשגה פנימי' הנ\"ל בהכרח שיצמצם ויכווץ כל כח השגתו שתהי' בלי התפשטו' רוחב ההשגה כלל וכלל אדרבה הוא בתכלית המיצר והצמצום שנשאר רק עצם נקודת כלי ההשגה שלו לשמוע ולקבל עצם כוונת הרב כו', וע\"כ גם המשפיע משפיע לו העומק ופנימי' הענין שבהשכל, וכאשר המקבל שואל אותו בהענין שכ\"ז הוא בפנימי' הענין, אינו משיב לו מה שנופל לו בהשקפה ראשונה במושכל ראשון, כ\"א משתדל לגלות ולהביא מהעומק וההעלם דמקור השכל כו', וזה בא בהמשפיע ג\"כ בבחי' מיצר דכל עומק בא בבחי' מיצר דוקא, וכמו עומק המעין שנובע טיפין טיפין כו'. וזהו דברי חכמים בנחת נשמעים והיינו שלא ימהר להגיד מה שבא לו במושכל ראשון כ\"א אדרבה יעכב ויצמצם עצמו שלא לדבר בהשקפה ראשונה כ\"א\nלהוציא עומק החכ' והפנימי' בהענין כו', וזהו בחי' יחוד פנימי דמשפיע ומקבל שבא במיצר בבחי' נקודה דוקא הן במשפיע והן במקבל כו', ומהמיצר בא אח\"כ לידי מרחב ביותר דע\"י תפיסת תמצית נקודת הענין יוכל להיות אח\"כ התרחבו' הענין ביותר ובעומק הענין ביותר, והיינו שגם העומק בא לידי מרחב בהתרחבו' גדולה בהשגה כו' (ועמשנת\"ל פרק הנ\"ל), והו\"ע יצי\"מ שמן המיצר דוקא נעשה אח\"כ היציאה מן המיצר בהתרחבו' גדולה ביותר כו'. ולמע' הו\"ע וחכם בבינה שזהו בחי' נקודה פנימיות דבינה שמקבלת בחי' פנימיות הנקודה דחכ' כו', וי\"ל שז\"ע הבן בחכ' שזהו כמו עד\"מ נקודת ההשכלה דחכ' רק שהוא בחי' הפנימי' שלה, דהיינו בחי' הנחה שכלי' כו' (וכמשנת\"ל שם שא\"ז ההתאמתות דחכ' שהיא למע' מהשכל והוא בחי' חכ' שבחכ' כו', וההנחה שכלי' להיותה שכלי' ה\"ז בחי' הבן בחכ', והשכלי שבהנקודה הוא בחי' יסו\"א וההנחה הוא בחי' הבן כו'), והיא שמתלבשת בבחי' פנימי' בינה שהו\"ע וחכם בבינה כו'. ועיקר ענין יחוד פנימי דאו\"א הוא שהבינה היא ג\"כ בבחי' השגת המהות, כמו החכ' שהיא\nבחי' ראיית המהות כמו\"כ הבינה בבחי' פנימי' שבה הוא בחי' השגת המהות כו', וכמו ההשגה שיהי' לעתיד שיהי' במהות הא\"ס ויהי' בבחי' השגה ממש כו' (עמשית\"ל פ'), והו\"ע טעמי תו' שיתגלו לעתיד שיהי' זה בבחי' השגה ממש במהות אלקות כו', והוא גילוי עונג העצמי שיהי' לעתיד ע\"י הבינה כו', וכמו התגלות עתיק שבבינה כו', רק שזהו הארה לבד ולעתיד יתגלה עצם העונג ויבוא לידי השגה גמורה ע\"י הבינה כו'. וזהו מ\"ש על לעתיד והניף ידו על הנהר דבינה שיהי' התגלו' בחי' עדן שזהו עצם התענוג שבפנימי' חכ', דפנימי' אבא פנימי' עתיק, ויהי' בבחי' השגה ע\"י הבינה דפנימי' בינה הוא ג\"כ פנימי' עתיק כו' (והחכ' הוא בבחי' ראי' ובינה היא בבחי' השגה כו'). וזהו שיהי' רק הנפה על הנהר ולא שיחרים אותו (כמו הלשון ים דכתי' בו והחרים כו'), והיינו שיהי' השגה לעתיד ויהי' בבחי' השגת המהות ממש כו', ולמע' הוא בחי' עצמו' הקו (ועיקרו הוא פנימי' הקו הנמשך מפנימי' ועצמי' א\"ס כו', וכמשנת\"ל פקל\"ז) המתלבש בפנימי' חו\"ב כו', והוא שמעצמו' הקו נאצל בחי' החכ' שהוא\nלהשכיל (י\"ל הכוונה ראי' שזה יהי' ענין ההשכלה דלעתיד) במהות הקו, ואח\"כ נאצל בחי' הבינה שהוא להשיג ולהתבונן במהות הקו הזה כו'."],[3601330436,"<span data-k=\"ks\"><b>קיצור.</b> וענין מיצר ים ומי הו\"ע יחוד פנימי דמשפיע ומקבל, כשהמקבל לוקח וקולט עצם כוונת הרב שזהו ע\"י הכיווץ להיות בעצם נקודת כלי השגתו, והמשפיע משפיע לו עומק השכל, וכשצריך להשיב לו על שאלתו העמוקה הוא מעומק מקור השכל, וכל עומק בא בבחי' מיצר, וזהו הבן בחכ' להביא עצם ההנחה שכליות, וחכם בבינה לקבל בפנימיות הבינה, ועיקר יחוד פנימי דאו\"א הוא בחי' השגת המהות כנ\"ל, וזאת תהי' ההשגה דלעתיד, וזהו והניף ידו על הנהר דבינה דבחי' עצמיות הקו שבפנימיות החכ' יהי' בבחי' השגה בפנימיות בינה. </span>\nקמ) <b>ומעין</b> ודוגמא מזה עכשיו הו\"ע ידיעת והשגת אלקו' מהדברים המוחשים כו', דהנה שכל אנושי הוא שנפל בדרך שבירה מבחי' הכלים דאצי' דמבחי' כלי הבינה דאצי' נתהווה בינה אנושית כו', והיינו כח ההשגה שבנפש להשיג בעניני' הרחוקים מאד בהשתל' הקו, והוא בחי' כח הפועל האלקי שבא בהתלבשו' ממש בהנפעל שזהו מבחי' חיצוני' הכלים דמל' דמל' דעשי' כו' (והוא החיות שבבחי' כח כו' וכמ\"ש במ\"א), ובזה שייך השגה ממש בשכל אנושי ע\"י הדברים הגשמי', דהיינו שע\"י שמשיג את הנפעל שזה הוא רואה ומשיגו היטב ה\"ה משיג את הכח הפועל וגבוה מעל גבוה כו', והיינו שכל הדברים הגשמי' הן כמו משל אל הנמשל להכח האלקי, והמשל הוא הנמשל ממש כו'. ואחר ההשגה שיודע ומשיג פרטי הנמשל מהמשל כאשר מוצא כל פרטי הנמשל בהמשל יבוא אח\"כ להשגת הנמשל בבחינת השגה מוחשי' כו', ואז הוא כלי ומכון לבחי' בינה עילאה שהוא ההשגה במהות הקו כו', ואע\"פ שאין ערוך ביניהם עכ\"ז מאחר שנפל ממנו בשבירה ה\"ה יכולה להתעלות למקור חוצבה כו', והיינו דוקא באופן ההשגה הנ\"ל שבתחלה\nיבין את הנמשל מהמשל בכל פרטיו, ואח\"כ כשמוצא פרטי הנמשל בהמשל מזדכך אצלו המשל (ונראה לו כמו כח אלקי כו', ור\"ל באומרו כמו כח אלקי הוא לפי שא\"ז שרואה אותו אלקו' ממש כמו הרואה את הנולד מאין ליש כו' וכמ\"ש במ\"א, להיות שכ\"ז הוא בהשגה לבד, אבל מ\"מ מזדכך אצלו הענין כ\"כ ומתאחד אצלו כ\"כ המשל עם הנמשל עד שנראה ונרגש אצלו כמו כח אלקי כו'), ומתחדש בזה השגה מוחשי' באלקו' כו', ועי\"ז הוא כלי לבחי' השגת המהות שיהי' לעתי' כו'. וי\"ל שזהו השלמות שיהי' לעתיד מעבודת הבירורים דעכשיו והוא התיקון בדברים התחתוני' הגשמי' ובעצם הגוף כו', שזהו תכלית הכוונה בירידת הנשמה למטה, וכידוע דהנשמה עצמה א\"צ תיקון וירדה למטה רק לתקן ולזכך את הגוף והנה\"ב והוא לפעול בהנה\"ב שלא יומשך אחרי העניני' החומרי', וכל עניני' החומרי' דהיינו מה שמוכרח יהי' בכוונה לש\"ש, הן באכו\"ש שלא יהי' למלאות תאוות נפשו כ\"א לקיום גופו בכדי ללמוד ולהתפלל, וממילא הוא נזהר מן המותרות דמה שהוא מותר לו ה\"ז רק מצד התאוה, כ\"א מסתפק בהכרחי' לבד וזה גופא הוא\nבכוונה לש\"ש, וכאשר לומד ומתפלל בכח האכילה ה\"ז נכלל בקדושה כו'. וכמו\"כ הוא בעסק מו\"מ שאין כוונתו להרבות הון וגם לא בלי שום כוונה, כ\"א בכדי שיוכל לקיים את המצוות כמו מצות הצדקה וללמד בניו תורה וכה\"ג, שעי\"ז מתבררים הדברים הגשמי' שעוסק בהם ועולים ונכללי' באלקו' כו', וגם הנה\"ב מתברר ומזדכך מזה, ובמצות הצדקה נעשה הבירור ביותר מבכל המצות כמ\"ש בסש\"ב פל\"ז מפני שהריווח בא לו ביגיעת כל הכחות שלו ומתברר כללו' הנה\"ב"],[3601330437,"בזה כו', וע\"י העבודה בבירור ותיקון הנה\"ב וכל הדברי' התחתוני' ה\"ה נעשה כלי ומכון לבחי' ההשגה דלעתיד בבחי' מהות אלקו' כו'.\n<b>וע\"פ</b> הנ\"ל יובן מ\"ש בהעלותך את הנרות אל מול פני המנורה כו', פני המנורה זהו בחי' פנימי' החכ', דהנה אור המנורה בכלל זהו בחי' החכ', וכנודע ההפרש בין אור המנורה לאש המזבח, דאש המזבח הוא בחי' המל' ובשרשו הוא בחי' בינה (בחי' חיצוני' בינה) שבבחי' התלהבו' ורשפי אש כו', ואור המנורה הוא בחי' חכ' והו\"ע השמן שהוא בחי' חכ' כו', והיינו בחי' פנימי' החכ' שז\"ע שמן משחת קדש המושח את הקודש בחי' ח\"ס, ובחכ' זהו בחי' פנימי' ועצמי' החכ' כו', ואהרן המשיך בחי' זו בנש\"י דאהרן אותי' נראה שהמשיך בחי' ראי' כו', ובאו אותי' נראה בצירוף שם אהרן (לא בצירוף נראה), לפי שאהרן הוא בחי' בינה וכידוע דמשה ואהרן הן חו\"ב, אבל זה בחי' פנימי' בינה בחי' השגת המהות כו', וזהו דאהרן פעל בחי' אה\"ר בנש\"י ואה' היא ע\"י השגה דמבחי' ראי' דחכ' העיקר הוא בחי' היראה כו', וכל אה' בא ע\"י השגה כו', ואהבה דאהרן הוא מבחי' השגת המהות כו', וכנודע ההפרש בין אה' דאברהם לאה' דאהרן, דאה' דאברהם הוא ע\"י השגה שזהו מבחי' חיצוני' בינה, ואה' דאהרן\nהוא מבחי פנימי' בינה כו' ועמ\"ש בלק\"ת ד\"ה בהעלותך הא' (ושם מבו' שזהו מבחי' ראי' וע\"י המרירות כו' וכמ\"ש במ\"א). וזהו בהעלותך את הנרות, נרות הן נש\"י ואהרן מעלה את הנרות שממשיך בהם בחי' אה' שע\"י השגת המהות כו', וז\"ש יאירו שבעת הנרות שהן ז' מדות דשרש נש\"י הוא מהז\"מ וכמ\"ש בלק\"ת שם, ואהרן מעלה את השבעה נרות שממשיך בכל נש\"י בחי פנימי' בינה כו'. וזהו חייך שלך גדול משלהם, דחנוכת הנשיאים הוא בעבודת הקרבנות שע\"ג מזבח החיצון שזהו בחינת חיצוני' בינה כו' וע\"כ שלך גדול שאתה מדליק ומטיב את הנרות המשכת בחי' פנימי' בינה שזהו למעלה באין ערוך כו'. וזהו בהעלותך את הנרות להמשיך בהם בחי' האה' כו', אל מול פני המנורה בחי' פנימי' חכ' ופנימי' בינה כו', יאירו שבעת הנרות כל הז' מדרי' שבנש\"י כו', ועז\"א חייך שלך גדול משלהם שאתה ממשיך בהם בחי' השגת המהות כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ומעין זה הוא ידיעת אלקות במוחש, דהנה שכל אנושי הוא בדרך נפילה מכלי הבינה להשיג דברים המוחשים, ומהנפעל יבין כח הפועל, ובהשגה טובה בפרטי הנמשל בהמשל, רואה זה בהמשל ונעשה אצלו כמו כח אלקי והשגה זו עולה למקור חוצבה כלי הבינה שהיא השגת המהות, וי\"ל שזהו השלימות דלעתיד שיהי' ע\"י הבירורים דעכשיו. ובזה יובן מ\"ש בהעלותך את הנרות, פני המנורה פנימיות חכ', ואהרן פנימיות בינה, והוא המשיך בחי' זו בנש\"י. </span>"],[3601330438,"<h3>בס\"ד. ש\"פ קרח, תער\"ג</h3>\n<b>ויקח</b> קרח בן יצהר בן קהת כו', וארז\"ל בגמ' סנהדרין דק\"ט ע\"ב קרח שנעשה קרחה בישראל, בן יצהר בן שהרתיח עליו את כל העולם כצהרים, וצ\"ל מהו\"ע מחלוקת קרח שעי\"ז נעשה קרחה בישראל, ומהו\"ע שנעשה קרחה כו', גם מהו\"ע שהרתיח עליו כו' כצהרים. והנה ברש\"י הביא בשם המדרש לא הזכיר בן יעקב שבקש רחמים על עצמו שלא יהי' נזכר במחלקותם, וכמ\"ש בסודם כו' ובקהלם אל תחד כבודי, והיכן נזכר על בני קרח בהתייחסם על הדוכן כו', משמעות הענין הוא דהתייחסות על הדוכן ומחלוקת קרח הן ענין א' בעצם רק שהן הפכים זמ\"ז, ולכן מדמין הענינים זל\"ז דבהמחלוקת לא נזכר והיכן נזכר בהתייחסם כו', וצ\"ל מה שייכות הענינים זל\"ז כו', גם צ\"ל מפני מה הי' צריך יעקב לבקש רחמים ע\"ז שלא יהי' נזכר במחלקותם כו'. ולהבין כ\"ז ילה\"ק משנת\"ל דישסו\"ת הן מדות דחו\"ב ואין זה בחי' מדות שבשכל שהן בבחי' התפעלות שכלי שזהו מה ששייך למדות, כ\"א הן בחי' המדות שבפרצוף המוחין עצמן וענינם הוא התפשטות והתגלות המוחין, דמוחין בעצם הן בבחי' הבדלה לא בבחי' ירידה והמשכה,\nוהמדות הן הטיית והמשכת המוחין כו', ובפרטי' הן בחי' נה\"י דאו\"א שזהו להביא את המוחין לידי מציאות נבדל מהם שהן המדות כו', ונת' שהן בחי' הארה לבד מן המוחין מאחר שהן רק הטיית והמשכת המוחין לא המוחין עצמן ממש כו', וא\"כ ה\"ה באות ה' דשם הוי' כמ\"ש בע\"ח דבד\"כ הן בחי' בינה שהיא רק הארה לבד דכל השגה הוא בריחוק מן העצם כו', וע\"כ הבינה עיקר מקור ההשתל' להיותה בחי' הארה לבד כו', ובחי' ישסו\"ת שהן בחינת הארה ה\"ז בחי' בינה בד\"כ כו', אבל או\"א הן בחי' עצמות המוחין והו\"ע בחי' פנימי' אבא פנימי' עתיק וכן פנימי' בינה פנימי' עתיק כו'.\nקמא) <b>וע\"פ</b> הנ\"ל יובן ההמשכה שהמשיכו האבות וההפרש בין המשכת האבות לההמשכה דמ\"ת, דגבי האבות כתי' וארא אל אברהם כו' באל שדי שכל הגילוים שלהם היו בחי' אל שדי, שגם שם הוי' שנא' כמה פעמים אצל האבות ה\"ז הכל המשכת בחי' אל שדי, והיינו דהאבות המשיכו מבחי' או\"א תתאין בחי' ישסו\"ת שזהו בחי' בינה שהיא מקור ההשתל' כו', וז\"ע אל שדי, וידוע דשם אל שדי הוא בבריאה והוא בחי' בינה המקננת בבריאה כו', וידוע דהפרסא שבין אצי' לבריאה הוא מחיצוני' בינה שז\"ס לבוש החשמל דשרשו מחיצוני' בינה ומלביש לזו\"נ מצדדיהן ומתחת רגליהן כו' וכמ\"ש בע\"ח, וכמ\"ש מזה בתו\"א ד\"ה והבדילה הפרוכת כו'. וזהו שם שדי שאמר לעולמו די, פי' לעולמו קאי על עולם האצי' וכמשנת\"ל פק\"ל דמשארז\"ל שהי' העולם מרחיב עצמו כו' אין הכוונה על העולם ממש היינו על מציאות העולם, דכל מציאות יש ומוגבל א\"א שיהי' בבחי' בל\"ג, כ\"א הכוונה על ההארה האלקי' המהווה את העולם והוא בחי' חסד דאצי', וכמ\"ש בסש\"ב ח\"ב בפי' הגדול הגבור דמדת החסד הוא בחי' התפשטות החיות להוות\nולהחיות עולמות ונבראים עד אין שיעור כו', ובזה יכול להיות ההתפשטות בבחי' בל\"ג וממילא גם הנבראים היו לא בבחי' מציאות יש כו' וכמשנ\"ת שם, ועז\"א שאמר לעולמו היינו עולם האצי' די מלהתפשט ולהתגלות בבחי' אור האצי'"],[3601330439,"והו\"ע הפרסא להעלים ולהפסיק האור דאצי' ויהי' התהוות נבראים בע\"ג כו', והו\"ע הגבור שנת\"ל שם, ושם אל הוא בחי' החסד זהו מה שע\"י הפרגוד מאיר לחוץ היינו הגילוי שבעולם הבריאה כו', וכ\"ז הוא בחי' אור של תולדה בלבד כו', והאבות המשיכו את שם אל שדי כמו שהוא באצי' בבחי' בינה דאצי', וזהו דשדי הוא מל' ברכות שדים בחי' חלב שדי אמו כו', דהנה בפרד\"ס כ' דאל שדי הוא בחי' יחוד יסוד ומל', ובשרשו י\"ל שזהו יחוד בחי' ישסו\"ת דבד\"כ זהו בחי' בינה כנ\"ל, ומזה נמשך ריבוי השפע בעולם שז\"ע ברכות שדים ורחם להיות ההשפעה בריבוי כו'. וכמו ברוך ה' אלקי ישראל מן העולם ועד העולם מעלמא דאתכסיא לעלמא דאתגלי', דבעדאתכ\"ס מאיר גילוי אור ועש\"ז נק' אתכסי' להיותו מכוסה ונעלם לגבי למטה לפי שמאיר שם אור שאינו בגדר גילוי עדיין לגבי למטה, וכידוע דמה שיכול להיות בבחי' גילוי למטה הוא אור מצומצם דוקא, אבל אור שהוא בבחי' גילוי ה\"ה בבחי' העלם למטה כו', ובעדאתכ\"ס מאיר האור בבחי' גילוי, וע\"כ הוא מכוסה ונעלם לגבי למטה כו', וידוע דעדאתכ\"ס ועלמא\nדאתגלי' הן בחי' ברי' ויצי' דכתי' יוצר אור ובורא חשך שהבריאה נק' חשך מפני האור שמאיר שם דמשו\"ז הוא בבחי' חשך והעלם לגבי שלמטה כו'. וכמו עד\"מ באדם מחו\"ד שהמח' הוא כח נעלה הרבה יותר מהדבור, שהרי המח' היא לבוש הראשון המלביש את השכל שקרוב יותר להשכל ומאיר בו אור השכל מה שא\"א שיתלבש בלבוש הדבור, וכמו תוקף נביעת אור השכל שא\"א להתלבש בדבור, דכשם שבמדות הרי תוקף אור המדות א\"א להתלבש בדבור וכנראה בחוש דבתוקף התפעלות המדות אינו יכול לדבר, כמו\"כ בתוקף נביעת השכל א\"א להתלבש בדבור וה\"ז מתלבש בלבוש המח' כו', ועכ\"ז נק' המח' חשך לגבי הזולת, שהרי גם כשיחשוב אדם כל היום כולו לא ידע הזולת כלל, רק בעומק המח' יודע הזולת שהוא חושב אבל מה הוא חושב אינו יודע כלל, וע\"ה שהמח' הוא ג\"כ לבוש לבד אל השכל לגלותו ולהובילו ממקור השכלתו להיות מושג ומובן כו', עכ\"ז ה\"ז רק לגבי עצמו לא לגבי זולתו כלל, וא\"כ לגבי הזולת ה\"ז נק' בשם חשך, ולא כמו הדבור שמאיר עיני הזולת כאשר יבין הדבר שכל ע\"י שמסביר לו בדבור כו', משא\"כ במח' כו',\nוהיינו לפי שבמחשבה מאיר אור השכל שאפשר להתגלות רק לעצמו ולא לדבר הזולת עצמו כו'. וכמו\"כ הדוגמא בעולם הברי' שמאיר שם אור שאפשר להתגלות בעולם כזה שאינו בבחי' מציאו' עדיין, וכנודע דברי' הוא בבחי' אפשרות המציאו' לבד כו', אבל בהתגלות המציאו' אא\"ל גילוי זה כו', וכמו המח' שלעוצם הבהירות אא\"ל הגילוי אל הזולת בבחי' קירוב כ\"א ע\"י לבוש שני שהוא לבוש הדבור, ורק לעצמו יכול להיות הגילוי ע\"י המח' לפי שאדם קרוב לגבי עצמו, ופי' קרוב לגבי עצמו שאין כאן מציאו' שחוץ להעצמו' שלו כו', דקורבה זו דאדם קרוב כו' ה\"ז יותר גם מקורבת שני אחים או אב ובנו שקרובים ביותר, ומ\"מ לא יהי' מושג השכל אל הבן ע\"י מחשבת האב כ\"א לגבי עצמו לבד, והיינו מפני ששני קרובים ה\"ה דבר נוסף על עצמותו, משא\"כ לגבי' שאינו דבר נוסף על עצמותו כו'. והגם שבאמת ה\"ז ג\"כ דבר נוסף על העצם שהרי השכל אינו עצם הנפש כ\"א כח בפ\"ע וה\"ז שהנפש משכלת בכח שחוץ לעצמו' הנפש כו' וכמשנת\"ל פמ\"ט, וכמו\"כ ההשכלה המושגת והשכל המשיג ה\"ה ב' דברים, וכ\"ש שהשכל דנה\"ט הוא דבר נוסף על השכל דנה\"א, ובפרט כלי המוחין שהן דבר נוסף כו', ומ\"מ כ\"ז מתאחד"],[3601330440,"בעצמותו כמו שאינו דבר נוסף כלל על העצם כו'. והדוגמא מזה יובן בעולם הבריאה שהוא בבחי' קירוב אל האין האלקי המהווה אותו להיות שהוא בחי' יש הראשון שהאין האלקי נושא ע\"ע א\"כ ה\"ה קרוב בתכלית, והגם כי לכאו' הוא דבר נוסף על עצמי' בחי' האין, מ\"מ להיות שהוא רק בבחי' אפשרות המציאו' לא בבחי' המציאו', א\"כ הרי לא יש כאן עדיין מציאות זולת ה\"ה מתאחד עם האין האלקי כאלו אינו דבר נוסף כו'. ובאמת א\"א לחלק כלל בין האין האלקי להיש, שהרי בלתי בחי' האין א\"א כלל לבחי' היש להיות בבחי' מציאו' כלל, וא\"כ כל ענין מציאו' היש הוא האין המקיים אותו כו', וע\"ה שכ\"ה בכל העולמות, אמנם בעולם הברי' ה\"ז בגילוי יותר כו', וע\"כ מאיר שם האין האלקי כמו עד\"מ המח' לגבי עצמו שאינו דבר נוסף כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והנה האבות המשיכו גילוי בחי' או\"א תתאין, וזה\"ע אל שדי שם דעולם הברי', וידוע דהפרסא היא מחיצוניות בינה וזהו שא' לעולמו די, ואל הוא גילוי בחי' הבינה כמו באצי', וזהו שדי מל' ברכת שדים, והוא גילוי בחי' עדאת\"כ, ויבאר תחלה דעדאת\"כ עולם הברי' שנק' חשך מפני הגילוי דשם, וכמו מח' שהוא לבוש הראשון כמו\"כ בריאה קרוב אל האין, וכמו אדם קרוב לעצמו, וכמו השכל עם היותו כח ה\"ה מתאחד כמו לא דבר נוסף, וכמו\"כ ברי' מתאחד כאלו אינו דבר נוסף. </span>\nקמב) <b>אמנם</b> בד\"כ ג' עולמו' בי\"ע נק' עדאת\"ג ונק' עולם הזה שהן בבחי' גילוי כו', וכמ\"ש בלק\"ת ד\"ה ראו כי ה' נתן לכם, ועדאתכ\"ס הוא עולם האצי' דהאור דאצי' אא\"ל בגילוי בבי\"ע כו', ועד\"מ אור השמש שהוא אור גדול מאד שמאיר לארץ ולדרים עלי' עד שפועל פעולות נפלאות שמצמיח כל התבואות כמ\"ש ממגד תבואות שמש, וכן מרפא חולים כמארז\"ל אדלי יומא אדלי קצירא, וזה עצמו הוא סבת מה שאין יכולים להסתכל בהשמש שמחמת ריבוי בהירות האור א\"א לכלי העינים להסתכל בו אם לא ע\"י המצאו' זכוכיות רבות שהן כלי האצטרלוגין שבהם וע\"י מביטים בהשמש לראות אורו, וגם זה לא בכיוון ממש להסתכל בדרך ישר בהשמש עצמו, ורק ע\"י אספקלריא הבלתי מאירה יכולים לראות כו', וסבת הדבר הוא ריבוי האור שבו, שהרי הלבנה שאורה מועט יכולים להסתכל בה מי שיש לו ראי' בריאה וחזקה כו'. וכמו\"כ יובן הדוגמא בבחי' שמש הוי' שהוא בחי' אצי' דבד\"כ הוא בחי' שם הוי', דהאור דאצי' אא\"ל בגילוי בבי\"ע, ורק מה שע\"י בחי' המל' דאצי' יכול להיות איזה גילוי לידע את בחי' האצי' כו',\nוהיינו מצד עוצם האור והגילוי דאצי' ה\"ז מכוסה ונעלם מעולמות בי\"ע כו', ובאצי' גופא בחי' ז\"א ומל' הן עדאתכ\"ס ועדאת\"ג, וכידוע דז\"א נק' קדוש לגבי בי\"ע והו\"ע קדוש הוי' כו', להיות דז\"א הוא סוף עולם הא\"ס ע\"כ הוא רק בבחי' סובב ומקיף לגבי בי\"ע כו' וכמ\"ש במ\"א, וההארה האלקית שנמשך לבי\"ע הוא מבחי' מל' דאצי' כו', ועיקר בחי' עדאתכ\"ס באצי' גופא הוא בחי' בינה, וכמ\"ש בזהר בפי' מן העולם ועד העולם מעלמא עילאה לעלמא תתאה דהיינו מבינה למל' כמ\"ש במ\"א. ויובן זה עד\"מ ממה שאנו רואין שכאשר האדם בא בשנים יותר נחשכים עיניו, וסבת הדבר הוא כנודע שכלי העין היא נקודה אחת מאירה מאד מצד אחת,"],[3601330441,"ומג' רוחותיה ומעמו\"ט היא בלתי מאירה, והנקודה האמצעית ה\"ה מכוסה בכסוים רבים כגלדי בצלים זעג\"ז וכמ\"ש בזהר באד\"ר, וכנודע גם מספרי הנתוח, וכאשר האדם בא בשנים ע\"י שמשתמש הרבה בכלי העין נחסרים מעט מעט הכסוים ונעשה האור רב, וריבוי האור ה\"ז סבה שא\"י לראות, שהרי הראי' הרוחניות באמת אינה בערך לראות דבר גשמי ורק ע\"י הכסוים שמתעלם האור ה\"ה רואה דבר גשמי, וכשנחסרים הכסוים ונעשה ריבוי אור א\"י לראות כו', ונמצא כמו במח' לגבי הזולת יובן במשל הזה לגבי עצמו, שמחמת ריבוי האור ביותר ה\"ז בבחי' העלם גם לגבי עצמו כו'. ובזה יובן מה שקראו חז\"ל לסומא בשם סגי נהור, שלכאו' זה כלועג לרש ח\"ו, אך באמת הוא כן שזהו מסבת ריבוי האור, שע\"פ הרוב סבת העדר הראי' הוא מצד שנחסרו הכסוים ונעשה ריבוי אור כו'. והדוגמא מזה הוא בעולם האצי' שהוא עולם שלעצמו כבי' כמ\"ש כל הנק' בשמי ולכבודי דקאי על עולם האצי' שהוא בבחי' שמי המיוחד כו', ובחי' בינה דאצי' היא בחי' עדאתכ\"ס באצי' גופא כו', וזהו מה שבינה נק' ביום ההוא שסתום ונעלם כו', דנה\"י\nדאימא הן מקור ומוחין לז\"א, דמוחין דז\"א אינם בחי' נה\"י דאימא ממש כו', וכמשנת\"ל פקל\"ה דמדות שבשכל וגם בחי' נה\"י שבהם שהן דפרצוף המוחין ה\"ז למע' מהמדות גם מבחי' המוחין שלהם כו', וכ\"ש בחי' מוחין דאי' שלמע' מהמדות כו', וע\"כ בחי' בינה בכלל היא בבחי' עדאתכ\"ס לגבי ז\"א כו', והאבות שהמשיכו מבחי' עדאת\"כ במדרי' היותר עליונה היינו מבחי' בינה דאצי' ה\"ז ריבוי הברכה והשפע בבחי' גילוי אלקות בעולמות כו'. וז\"ע והריקותי לכם ברכה עד בלי די עד שיבלו כו', דכאשר נמשך ממקור ההשתל' האור בגילוי כו', הרי המוגבל יבלו שפתותיו מלומר די שזהו ריבוי אור ביותר כו', שהרי ע\"פ ס' השתל' ע\"פ מא' קו המדה מה שנמשך מאצי' לבי\"ע ה\"ה רק הארה דהארה לבד בחי' אור של תולדה כו', וכאשר נמשך ממקור ההשתל' הגם שגם אז אינו דומה הגילוי באצי' להגילוי שבבי\"ע, שהרי ההמשכה היא מ\"מ ע\"פ ס' השתל' דד' עולמו' אבי\"ע כו', שהרי זהו מקור ההשתל' עכ\"פ דכללות ההמשכה הוא רק הארה לבד כמשנת\"ל פקל\"ז דממילא יש בזה חילוקי מדרי' בפרטי ההמשכות בעולמות כו', מ\"מ ה\"ז\nבחי' גילוי אור ביותר כו', דע\"פ מא' קו המדה מה שמאיר בבי\"ע הוא בחי' אור של תולדה לבד, והמשכת האבות היא להיות גילוי אור האצי' כו'. וכמו קודם חטא עה\"ד שהי' למטה גילוי אלקו' דעיקר שכינה בתחתונים היתה כו', וצ\"ל שא\"ז ע\"י המעמד ומצב דזו\"ן עפ\"י ס' ההשתל', שהרי מבו' בע\"ח שער מיעוט הירח דאז היו זו\"ן בבחי' אב\"א עדיין, והגם דבחי' מל' היתה בבחי' פרצוף וקבלה גם מה\"ס הראשונות דז\"א, מ\"מ הכל הי' רק בבחי' אחורי הז\"א ואינו בערך דמשו\"ז יהי' גילוי אלקו' למטה, אלא צ\"ל שזה הי' בבחי' תוס' אור לאדה\"ר, וכמו האור שנברא ביום ראשון שהי' אדה\"ר מביט בו מסוף העולם ועד סופו, דהיינו בחי' עדאתכ\"ס ועדאת\"ג כו' וכמ\"ש במ\"א, דכ\"ז נראה שהי' בבחי' תוס' אור כו'. ואפשר י\"ל עפמ\"ש במק\"מ בזח\"א דל\"ה ע\"א בשם כהאריז\"ל דהתהוות אדה\"ר הי' ע\"י זיווג זו\"ן בהיכלי או\"א בבחי' פב\"פ כו', והגם דהתגלות נשמת אדה\"ר הי' כשירדו למקומם והיו בבחי' אב\"א כמש\"ש, מ\"מ י\"ל דמשו\"ז הי' לו האור והגילוי באין ערוך לגבי הגילוי שבהעולם כו', וזהו מה דעיקר שכינה\nבתחתונים היתה די\"ל שא\"ז ע\"פ ס' ההמשכה כ\"א בבחי' תוס' אור כו'. והנה האבות המשיכו גילוי אוא\"ס כמו שהי' בתחלת הבריאה קודם חטא"],[3601330442,"עה\"ד ועוד למעלה מזה, והיינו שהמשיכו בחינת יחוד ישסו\"ת, ולא רק כמו שזו\"נ עולים באו\"א כ\"א מבחי' יחוד או\"א ממש, כי מתחלת הבריאה הרי ואדם אין כו' שלא הי' עדיין עבודה וההמשכה הי' מצ\"ע כו', והאבות המשיכו ע\"י העבודה ע\"כ המשיכו ממדרי' עליונה יותר כו' (ובמ\"א מבו' פי' ואדם אין דבחי' אין שזהו בחי' האור דבחי' זו נק' אדם כו', לא הי' עדיין גילוי זה רק ההמשכה הי' מבחי' הכלים לבד כו', וי\"ל שזהו מה שע\"פ ס' ההשתל' הרי רק כלים דאצי' נעשים נר\"ן לבי\"ע, אבל אור הקו גם בחי' חיצוני' הקו אינו מאיר בבי\"ע כו', וגם קודם החטא שהי' גילוי אלקות למטה ה\"ז רק מבחי' זו\"נ כמו שקבלו האור ביחודם באו\"א כו' כנ\"ל, והרי זו\"ן בכלל הן בחי' גרמוהי ששם התגברות הכלים כו', והאבות המשיכו את האור ומבחי' או\"א שזהו בחי' חיוהי כו'). וזהו והריקותי לכם ברכה עד בלי די עד שיבלו כו' שהמוגבל יבלו שפתותיו מלומר די, דכאשר נמשך משרש ומקור ההמשכה ה\"ז ריבוי השפע בבחי' תוס' אור כו', דע\"פ ס' והדרגה הרי האור מתמעט ממדרי' למדרי' דגם במדרי' דעו\"ע ה\"ז\nמיעוט רב וכמו ממוחין למדות כו', דמעלת המוחין ה\"ה למע' מאד מהמדות כו'. וזהו שע\"פ מא' קו המדה ההמשכה היא ממהות למהות שמתמעט האור הרבה בזה וכמשי\"ת, אבל כאשר ההמשכה הוא משרש ומקור ההשתל' אין ההמשכה ע\"פ מא' קו המדה כו', ונמשך האור כמו שהוא במקורו ושרשו ה\"ז תוס' מרובה כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ובד\"כ בי\"ע עדאת\"ג ואצי' עדאת\"כ שאינו מאיר בבי\"ע, וכמו אור השמש שא\"א להסתכל בו כ\"א אספשא\"מ, כמו\"כ גילוי הארת אצי' הוא רק ע\"י המל', והעיקר הוא בינה דאצי', ועד\"מ סגי נהיר שמפני ריבוי גילוי אור הראי' הרוחניות אינו רואה בעצמו, כמו\"כ באצי' שנק' שמי המיוחד בי הנה בחי' בינה היא מכוסה ונעלם, והאבות המשיכו גילוי הבינה בבי\"ע, והיינו שהמשיכו מקור ההשתל', וז\"ע ברכה עד בלי די, וכמו בתחלה דעיקר שכינה בתחתונים היתה, וכמו אור שנברא ביום ראשון, וי\"ל מפני שהי' יחוד זו\"נ בהיכל או\"א, והאבות המשיכו גילוי או\"א ממש, גם י\"ל דבתחלת הברי' הי' הכל מבחי' הכלים, וזהו ואדם אין, והאבות המשיכו בחי' האור דאו\"א. </span>\nקמג) <b>ולפ\"ז</b> מה ששם שדי הוא ל' די פי' וענין די הוא כמו די מחסורו שמתמלא החסרון שלא יהי' שום חסרון כלל, דהנה התהוות העולמות הי' ע\"י חסרון האור דמבחי' גילוי אור אא\"ל התהוות המציאו' כ\"א מבחי' חסרון האור כו', והיינו ע\"י שנחסר אור האצי' שאינו מאיר גם בשרש ומקור דבי\"ע כו', וכנודע דפנימי' המל' מעלמת על האורות דאצי' ורק חיצוני' המל' הנק' ארץ הוא שנעשה מקור לבי\"ע כו', ובחי' זו נק' יבשה שזהו ע\"י התעלמות המדרי' העליונות וכמ\"ש יקוו המים כו' ותראה היבשה כו', דע\"פ פשוט הוא כאשר נקוים ומתעלים המים אז תראה היבשה כו', ובזח\"א די\"ח ע\"א מפרש יקוו ל' קוין והן בחי' המדות, וכאשר יתכנשון אל מקום אחד בחי' יסוד כדין ותראה היבשה דא ה' תתאה דא אתגלו וכל שאר אתכסו כו', והו\"ע בנין המל' מהגבו' שצ\"ל צמצום שלא יתגלה פנימי' המדות כו', דהיינו כאשר המים נקוים למקום א' ואינם מתגלין עדיין במל' כדין ותראה היבשה כו' (ובפרד\"ס פי' יבשה הוא ע\"י החטא, והיינו שע\"י התעלמו' האור הוא"],[3601330443,"סבת החטא כו' וכמשי\"ת). וכמו עד\"מ החול שעל שפת הים שהוא יבש מהמים ונעשה חלקים נפרדים ע\"י שהים שואב הלחלוחית כו', והו\"ע והים עומד עליהם מלמעלה בבחי' התנשאות והסתלקות להעלים אור האצי', ועי\"ז בחי' חיצוני' המל' שחסר מאור האצי' ונק' יבשה נעשה מקור לבי\"ע כו', וכ\"ה בשרש הראשון שע\"י סילוק והעלם האוא\"ס נעשה מקור לעולמו' וכללו' ההשתל' מבחי' מל' דמל' דא\"ס כו'. וכידוע בענין אתה הוא הוי' לבדך דחשיב כאן ג' ענינים והכל במדרי' שלפה\"צ, דאתה הוא בחי' עצמו' א\"ס ב\"ה הנק' עצמו' המאור, ונא' ע\"ז אתה שהוא בהתגלות בכל מקום וש\"ש שגור בפי כל כו', וענין ההתגלות בזה הוא שמתגלה כמו שהוא בהעלמו להיות שזהו למע' מהעלם וגילוי כו', והיינו שהכל יודעים את העצמיות ואין שום אחד משיגו כו', והוא היינו בחי' אוא\"ס ששייך בזה העלם וגילוי להיותו רק גילוי מן העצמות כו', והוי' הוא בחי' התפשטו' האור, דבאוא\"ס גופא הוא בחי' אור השייך אל העולמות כו', וזשארז\"ל בפדר\"א עד שלא נבה\"ע הי' הוא ושמו בלבד, דעד שלא נבה\"ע היינו לפה\"צ, דע\"י הצמצום\nכבר הי' ברי' שז\"ע אדם דברי' דכללות כו', ועד שלא נבה\"ע הוא בחי' אצי' דכללות כו', הי' הוא ושמו שזהו ב' מדרי' שבאצי', דכשם שבאצי' הפרטי' יש ב' מדרי' חו\"ב וזו\"ן דחו\"ב הן נסתרות לה' אלקינו, וו\"ה הן והנגלות כו', כמו\"כ באצי' דפרטיות הו\"ע הוא ושמו בחי' עצם האור והתפשטו' האור שהי' אוא\"ס ממלא מקום החלל כו', ועז\"א אתה הוא הוי' לבדך, שכ\"ז הוא כמו שהוא לבדו הוא באוא\"ס שלפה\"צ כו'. אך מבחי' גילוי האור אא\"ל התהוות העולמו' וע\"ז הי' הצמצום שנסתלק ונתעלם האור כו', וז\"ש אח\"כ את עשית את השמים כו' את חסר ה', שנחסרו הה' פרצופים מבחי' הכתר עד המל' דא\"ס שז\"ע הצמצום שהי' באוא\"ס, ונשאר רק בחי' מל' שבמל' לבד שנעשה מקור לעולמות כו'. והנה החסרון שבמל' בשרש הראשון זהו סבת מיעוט הירח, דזה שיש מילוי וחסרון הלבנה הוא מצד חסרון האור במל', דמשום דסיהרא לית לה מגרמה כלום רק מה שמקבלת אור מהשמש ע\"כ יש בזה מילוי וחסרון כו' וכמ\"ש במ\"א, ומצד חסרון האור יכול להיות אחיזה לחיצונים, דכאשר יש גילוי אלקות א\"א להם לקבל וכידוע בענין\nאם בן הוא כו', ורק מבחי' המל' מפני חסרון האור יכול להיות אחיזה כו', וכמ\"ש בזח\"א דקמ\"ו ע\"א דכד סיהרא חסרא חויא בישא אתתקף כו'. וכמו בנפש הרי תוקפא דגופא חולשא דנשמתא, הרי ידוע דהתחלה היא החולשא דנשמתא שזאת היא הסבה לתוקפא דגופא כו', דכאשר הכחות דנה\"א הן בהתגלות וכמו בעבודה בתפלה שמביאים לידי גילוי הכחות דנה\"א בהתבוננו' אלקי ובהתעוררו' אהוי\"ר כו', אז הכחות דנה\"ב הם בהעלם, וכמ\"ש בסש\"ב גבי בינונים שהנה\"ב שלהם בשעת התפלה הוא כישן, ומבו' שם שיכול להיות כבינוני המתפלל כל היום כו', וע\"ה שזהו בהתפשטו' הנה\"ב לבד לא בעצם מהותו היינו שבעצם מהותו יתבטל כו', שזהו ע\"י עבודה גבוה ונעלה יותר והיא מדרי' הצדיקים כו', מ\"מ הרי ההתפשטו' שלו מתעלם שנעשה בו חלישות עי\"ז, וכידוע דע\"י העדר הפועל נחלש הכח, וכ\"ש בהעדר ההתפשטו' שע\"י עבודה כו'. אך בהעדר עבודה שאין הכחות דנה\"א בהתגלות באים ומתגלים הכחות דנה\"ב ומתגברים כנ\"ל ופועלים חלישות בהכחות דנה\"א כו', ובתחלה הוא בדברים המותרים, והיום אומר לו כך ולמחר כך כו', וז\"ש אין אדם עובר עבירה אא\"כ נכנס בו רוח שטות שמכסה על האמת, דהאמת הן הכחות דנה\"א, והרוח שטות הוא רוח"],[3601330444,"התאוה דז\"מ רעות וה\"ז מכסה ומעלים על האמת דנה\"א כו', והסבה לזה הוא העדר העבודה כו' כנ\"ל וכמ\"ש במ\"א. וז\"ש ונפש כי תחטא ואי' בזהר ע\"ז תווהא דאיך שייך שהנפש יחטא שהרי החטא הוא מצד הנה\"ב, והאמת הוא שהחטא הוא מהנה\"ב, אבל זה שייך במדרי' נפש שאין בזה גילוי אור ועי\"ז יכול להיות חטא כו', וידוע שגם הנפש נסרך ונדבק בזה כו', וכמו\"כ הוא כבי' למע' דע\"י דסיהרא חסרא בבחי' העדר האור כו', עי\"ז חויא בישא אתתקף כו'. אך ענין די מחסורו הוא שמתמלא החסרון ומאיר בה גילוי אור אז אין מקום ליניקת החיצונים אדרבה שגם למטה מאיר גילוי אור כו', וז\"ע שאברהם התחיל להאיר דעד אברהם הי' העולם מתנהג באפלה שלא הי' נראה ונגלה אלקו' כלל מצד התגברו' ההעלם וההסתר מהקלי' כו', ואברהם התחיל להאיר שהודיע אלקות בעולם והמשיך גילוי אלקו' בעולם כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ולפ\"ז ש' שדי הו\"ע די מחסורו, דהתהוות העולמות הוא ע\"י חסרון האור דאצי', מל' נק' יבשה שזהו ע\"י יקוו המים התעלמות האור, ובשרשו הו\"ע הצמצום, אתה הוא ה' לבדך ג' מדרי' לפני הצמצום, אח\"כ אתה עשית חסר ה', והו\"ע מיעוט הירח, ועי\"ז חיויא אתתקף, וכמו חולשא דנשמתא הוא סיבת תוקפא דגופא, דע\"י עבודה נחלש החומריות, ואברהם התחיל להאיר מילוי החסרון. </span>\nקמד) <b>והענין</b> הוא דהנה בפי' שם שדי מלבד משארז\"ל בגמ' ובמד\"ר כנ\"ל, פי' המפרשים שהוא מל' שוד משדי יבא, והיינו שהוא משדד המערכות, ופי' הרמב\"ן ז\"ל שממנו באים הנסים המוסתרים המלובשים בלבושי הטבע כו'. וכנודע שיש ב' מיני נסים, הא' נסים נגלים וכמו יצי\"מ וקי\"ס וכה\"ג, שנראה ונגלה לעין כל שהוא היפך הטבע ונגלה בזה אלקו' בגילוי ממש כו', ונסים אלו הן מש' הוי' בעצם שלמעלה מבחי' מקור לעולמות, וכידוע דמש' הוי' אא\"ל התהוות היש וכמ\"ש בראשית ברא אלקים דהתהוות העולמו' הוא משם אלקי' דוקא, אבל מש' הוי' אא\"ל ההתהוות, וע\"כ ע\"י גילוי ש' הוי' מתבטל הטבע לגמרי כו'. והב' נסים שהן מלובשים בדרכי הטבע, שאין הטבע מתבטל לגמרי, ומ\"מ עצם הנס הוא מלמע' מהטבע כו'. דהנה הנהגת הטבע שזהו ההנהגה שע\"י המזלות הרי כ\"ז הוא מאלקו', וכמ\"ש במ\"א שהן רק כגרזן ביד החוצב בו כו', רק שזהו האור האלקי שבא בבחי' צמצום מאד עד שמתלבש בהמזלות שמסתירים על האור האלקי כו' (וזה מחסד ה' עלינו בכדי שיהי' החסד וההשפעה מאתו ית' חסד גשמי לפ\"ע\nהמקבלים כו', וכמ\"ש מזה במ\"א בד\"ה וברכך ה\"א באורך), ושרש המזלות הוא משמרי האופנים וגבוה מעל גבוה עד שמקבלים מבחי' רוח פיו ית' שהוא כדרך וס' ההשתל' ע\"פ מא' קו המדה ממדרי' למדרי' שמתמעט ומתצמצם האור מאד כו' עד שבא בבחי' הסתר לגמרי בהמזלות כו', וז\"ע טבע שהוא מל' טבעו בים סוף דהיינו שהאלקו' נטבע בזה (פארטרונקען) ואינו נראה ונגלה כלל כו'. אבל כאשר מאיר משרש ומקור ההמשכה והיינו שנמשך שלא בדרך עו\"ע ממש כו', עי\"ז הוא משדד המערכות להיות בזה נס, דנס הוא ל' הרמה והגבהה וכמו וישימהו על הנס כו', והוא היפך ענין הטביעה כ\"א להיות האלקו' בבחי' הגבהה, והיינו שנראה בזה ג\"כ גילוי אלקות וכמ\"ש ראו כל אפסי ארץ את ישועת אלקינו רק שמלובש בלבושי הטבע,"],[3601330445,"וכמו בנס דאסתר שהי' מלובש בטבע באה' אסתר, ובאמת הרי ראו בזה גילוי אלקו' איך שנהפך הדבר לגמרי וכמ\"ש ונהפוך הוא אשר ישלטו היהודים כו', והיינו שהנס בעצם הוא מש' הוי' (דכל גילוי אלקו' הוא מש' הוי' שהוא בחי' האור כו'), רק שזהו מהארת הוי' המלובש בש' אלקים ע\"כ הוא מלובש בדרכי הטבע כו'. ושרש ב' בחי' נסים הנ\"ל הן מהב' יחודים דאו\"א, דנסים נגלים הן מיחוד פנימי דאו\"א שזהו בחי' או\"א עילאין, ונסים נסתרים הן מיחוד חיצוני דאו\"א, שזהו בד\"כ בחי' יחוד דישסו\"ת והוא בחי' מקור ההשתל', דכאשר נמשך האור משרשו ומקורו ה\"ז בחי' נס שנמשך מזה גילוי אלקו' כו', וז\"ש במד\"ר בפי' שם שדי שדי באלקותו לכל ברי', ופי' שדי באלקותו היינו שהי' מזה נסים ג\"כ כו'. והנה ידוע שגם יחוד חיצוני דאו\"א הוא שנמשך מאוא\"ס שלמע' מאו\"א, שהרי כל ההמשכות דחו\"ב הן מבחי' הכתר שזהו בחי' אוא\"ס הסובב שלמע' מהשתל' כו' כנודע, רק ששרש ההמשכה הזאת היא מבחי' חיצוני' הכתר שהוא שרש ומקור הנאצלים כו', ובשרשו הוא האוא\"ס שלפה\"צ דהיינו האור שבבחי' א\"ס ששיער\nבעצמו להאיר בבחי' מדה וגבול כו', ומשם נמשך תוס' אורות בקו כו'. ולפ\"ז י\"ל שזהו\"ע מה דאי' במד\"ר עוד פי' בשם שדי שאין העולם ומלואו כדאי לאלקותו, דפי' העולם ומלואו הוא עצם העולמו' והאור שהוא בבחי' ממכ\"ע, וכאשר נמשך מבחי' סוכ\"ע הרי אין העולם ומלואו כדאי לפי שאין ערוך בחי' הגבול לגבי בל\"ג כו', ומשם נמשך מילוי החסרון בבחי' מל', וזהו ג\"כ מ\"ש כי אין מחסור ליראיו, דאין מחסור ליראיו דשרש מילוי החסרונות הוא מבחי' הכתר כו'. וזהו המשכת האבות שהמשיכו מבחי' שרש ומקור ההשתל' דההמשכה היא משם שלא ע\"פ ס' ההשתל' דקו המדה כו', ונמשך האור והגילוי בבחי' המל' שז\"ע די מחסורו שמשלים החסרון כו', ועי\"ז המשיכו גילוי אלקו' למטה כו'.\n<b>ועפ\"ז</b> יובן משארז\"ל על קרח שנעשה קרחה בישראל, דהנה על ויקח קרח ת\"א ואתפליג קרח, ואי' בס' נועם אלימלך שז\"ע יהי רקיע ויהי מבדיל כו', דההבדלה בין מ\"ע למ\"ת הוא ההבדלה בין ההמשכה מאימא עילאה לז\"א ובין ההמשכה לבחי' מל', והו\"ע הנסירה דקודם הנסירה הי' כותל א' לשניהם דהיינו שהשתוו בהמשכה כו' ואח\"כ ננסרו, והכוונה בזה להיות יחוד פב\"פ וכו' וכמ\"ש במ\"א (ועמ\"ש מזה בד\"ה תקעו עת\"ר). אך קרח רצה בההבדלה עצמה והוא שלא יהי' גילוי אור בבחי' המל', וזהו ואתפליג שהוא חטא דור הפלגה, וכמ\"ש במ\"א ההפרש בין דור המבול לדור הפלגה, דדור המבול חטאו בבחי' מל' וכמ\"ש כי השחית כו' על הארץ והו\"ע ושפחה כי תירש גבירתה כו', ודור הפלגה כפרו בשם הוי' והו\"ע תחת עבד כי ימלוך כו' שלא רצו בהגילוי דש' הוי' שעי\"ז נמשך גילוי אור במל', והם רצו דוקא בחסרון האור וכענין אם בן הוא כו' וכנ\"ל. וזה הי' ג\"כ חטא קרח רק שכאן הי' בענין חו\"ג שרצה התגברות הגבו' להיות העלם כו', וה\"ז ההיפוך לגמרי מהמשכת האבות שהמשיכו להיות מילוי האור במל',\nוהוא רצה בחסרון האור כו', ולכן חלק על הכהונה דכהן איש החסד הוא בחי' גילוי אור והוא לא רצה בזה כו'. וזהו שנעשה קרחה והוא מקו\"פ והיינו בחי' העדר האור כו', והנה קרחה הוא מריטת השערות, וי\"ל ע\"פ משנת\"ל פקל\"ג בענין אל עולם שזהו עד\"מ השערות שהן מהחיות של המוח רק שנעשה שערה שהוא כמו דבר נבדל"],[3601330446,"לגמרי מן האדם, וכמו\"כ הוא שהנבראים הן הן ההארה האלקית עצמה שנתעבה ונתגשמה ונעשה מציאו' נברא כו', וזהו שגילה אברהם והמשיך עי\"ז גילוי אלקו' בעולם כו', וקרח עשה קרחה מריטת השערות שהוא רצה בעצם המציאו' והישות של העולם כו'. וענין בן יצהר שהרתיח עליו כו' כצהרים, י\"ל שזהו התקון והו\"ע התגברות אור השמש והיינו גילוי בחי' שמש הוי' שהמשיכו האבות כו', או שזהו עוד למע' מזה והוא המשכת משה שהמשיך ע\"י התו' שהוא התגברו' אור השמש ביותר כו', וזהו שהרתיח עליו העולם כצהרים בחי' תוקף האור כו'. וזהו שבקש יעקב רחמים שלא יהי' נזכר במחלקותם להיות שזהו היפך לגמרי מהמשכת האבות ופעולתם כו', והי' צריך לבקש רחמים ע\"ז לפי שההמשכה שלהם הוא עכ\"פ ממקור ההשתל' וכמשי\"ת, דבזה יכול להיות חסרון כו', ע\"כ הי' צריך לבקש רחמים ע\"ז כו', והיכן נזכר בהתייחסם על הדוכן דעבודת הלוים הוא להמשיך מבחי' בינה בחי' עדאתכ\"ס וכמ\"ש ועבד הלוי הוא כו', וזהו שאומרים שירה על היין והו\"ע יין המשמח אלקים, וענין המשמח אלקי' שנמשך גילוי הוי' באלקים,\nוהיינו מבחי' שם הוי' המלובש בש' אלקים, דאל\"כ אינו שייך לו' המשמח כו' מאחר שהוא למע' לגמרי מש' אלקי' כו', אלא הוא ש' הוי' שמלובש בש' אלקי', והשמחה הוא שיהי' גילוי ש' הוי' והוא כענין נסים נסתרים הנ\"ל, וידוע שיש בחי' אמת הוי' ואמת דאלקים, ויין המשמח אלקי' הוא בחי' האמת דאלקי' להיות בזה גילוי שם הוי' כו', וא\"כ בעצם ענינם א' הוא רק שהן הפכים שקרח לא רצה הגילוי והשירה הוא להיות הגילוי כו', וזהו שנז' בהתייחסם על הדוכן שגם כמו שמלובש בשם אלקים יהי' גילוי אלקות כו'.\n<span data-k=\"ks\"><b>קיצור.</b> דהנה שדי הוא שמשדד המערכות, כי יש נסים נגלים שמש' הוי' בעצם, והוא גילוי בחי' או\"א עילאין, ונסים נסתרים, טבע מש' אלקים, והנס הוא גילוי ש' הוי' ע\"י ש' אלקים, והוא גילוי מקור ההשתל' שלא בדרך עו\"ע, והו\"ע יחוד ישסו\"ת, וזהו שדי באלקותו, ושרש ההמשכה מבחי' חיצוניות דאוא\"ס, וזהו שאין העולם ומלואו בחי' ממכ\"ע כדאי לאלקותו בחי' גילוי סוכ\"ע, וזהו די מחסורו. ובזה יובן ענין ויקח קרח ואתפליג שרצה בההבדלה שיהי' חסרון אור והו\"ע קרחה, וע\"ז בקש יעקב רחמים שיהי' מילוי החסרון.</span>"],[3601330447,"<h3>בס\"ד. ש\"פ חקת, תער\"ג</h3>\n<b>וידבר</b> ה' אל משה כו' זאת חקת התורה אשר צוה ה' כו' ויקחו אליך פרה אדומה תמימה כו', וצ\"ל מהו כל האריכות באומרו זאת חוקת התו' דהול\"ל דבר אל בנ\"י ויקחו כו', מהו אריכות ההקדמה זאת חוקת כו'. ובמד\"ר אי' ר' יצחק פתח כל זה נסיתי בחכמה אמרתי אחכמה והיא רחוקה ממני, כתי' ויתן אלקים חכמה"],[3601330448,"לשלמה ותבונה הרבה מאד כו' כחול אשר על שפת הים, מהו כחול כו' כשם שהחול גדר לים כך היתה החכ' גדר לשלמה, מתלא אמרין דעה חסרת מה קנית, דעה קנית מה חסרת כו', ומאריך בענין חכמת שלמה ומסיים אמר שלמה על כל אלה עמדתי ופרשת פרה אדומה חקרתי ושאלתי ופשפשתי והיא רחוקה ממני, וזהו כל זה נסיתי בחכמה אמרתי אחכמה בפ' פרה אדומה והיא רחוקה כו', וצ\"ל מהו\"ע פרה אדומה שגם שלמה בחכמתו לא עמד עלי', דכל הענינים עמד עליהם ופרה אדומה אמרתי אחכמה והיא רחוקה כו', וגם מהו אמרתי אחכמה דמאחר שהיא רחוקה שלמע' מהשגה איך רצה להתחכם בה כו'. גם צ\"ל מהו\"ע דעה קנית מה חסרת דקאי על שלמה והלא מ\"מ הי' חסר בהשגת פ' פרה אדומה, וא\"כ מהו\"ע מה חסרת כו'. ולהבין כ\"ז צלה\"ק משנת\"ל דהמשכת האבות שהמשיכו גילוי אלקו' בעולם הוא מה שהמשיכו משרש ומקור ההשתל' דההמשכה היא משם שלא ע\"פ ס' השתל' דקו המדה, דע\"פ מא' קו המדה ההמשכה היא בבחי' מיעוט עד שבמל' אינו מאיר גילוי אור כו', והאבות שהמשיכו משרש ומקור ההשתל' המשיכו בחי' גילוי אור במל' שעי\"ז המשיכו גילוי אלקו' למטה כו'.\nקמה) <b>ולהבין</b> זה בתוס' ביאור, ילה\"ק איך שבהמשכת האור בס' השתל' דע\"ס יש הפרש באופן ההמשכה שלצורך אצי' ולצורך בי\"ע והיינו דבההמשכה בע\"ס גופא מחו\"ב לז\"א ומז\"א למל' יש הפרש אם ההמשכה היא לצורך אצי' עצמו או שההמשכה היא לצורך בי\"ע כו'. דהנה לפעמים נק' ההמשכה ממדרי' למדרי' בשם אותי' דאותי' הן גילוי וכמו אתא בקר, ואתא מרבבות קדש, והוא שמאותי' שבעליון הוא הגילוי אל התחתון, ולפעמים נק' ההמשכה בשם שערות וכדאי' בע\"ח דשערות דז\"א נעשים מוחין לנוק' כו'. והענין הוא דהנה ידוע שבכל ספי' יש נקודה ספי' פרצוף, נקודה היא העצמי' והנקודה כללי' של הספי' והוא בחי' כתר שבה שכוללת כל הט\"ס וממנה נמשכים ומתגלים כו', וכמו בחכ' הנקודה היא בחי' כתר שבחכ' והוא הרצון להתחכם שזה כולל ההתחכמות שע\"י שרוצה להתחכם ישכיל ויתחכם כו', דזהו שארז\"ל לעולם ילמוד אדם במקום שלבו חפץ, דכאשר לבו חפץ בהענין ישכיל ויתחכם בו ויבין וישיג כו', וי\"ל ג\"כ דהנקודה העצמי' היא עצם נקודת החכ' מה שביכולתו לבא על כל דבר חכ' כו', ואי\"ז מה\nשביכולתו להשכיל ולהתחכם בכל דבר שכל וחכ' שזהו בכח המשכיל כשהוא בהמשכה טובה ביכולתו להשכיל כו' וכמ\"ש במ\"א, ונקודה הוא בכח החכ' עצמה, והוא מה שביכולתו לבא על כל דבר חכ' היינו להבינו ולהשיגו כו', רק שהוא בעצם כח החכ' קודם שמבין ומשיג עדיין כו'. וכמו שמבו' במ\"א בענין ידיעה עצמי' שיודע עצם כח חכמתו שיבא על הענין כשיבא לפניו דעכשיו עדיין לא בא הענין לפניו רק שיודע שכשיבא הענין לפניו ידע אותו, שא\"צ להשכיל דבר בשביל זה היינו להמציא איזה השכלה לצורך זה כ\"א לידע ולבא על הדבר ההוא כו', והיינו הידיעה בעצם כח חכמתו שביכולתו לבא על כל דבר חכ' כו', וזהו הנקודה העצמי' דחכ' מה שביכולתו לבא כו'. וכן בחסד הנקודה כללי' היא הרצון להתחסד דמשו\"ז ה\"ה מתעורר תמיד להטיב חסדו ומרגיש כל חסד והטבה כו', או שהוא עצם נקודת הנדיבות שבלב דביכולתו להתחסד בכל מיני חסד כו'. וספירה הוא התגלות הט\"ס שבכל ספי', וכמו נקודת ההשכלה (בכ\"מ מבו' דנקודת ההשכלה הוא בחי' יסוד"],[3601330449,"שבחכ' ונז' ג\"כ לעיל פמ\"א, וי\"ל שזהו נקודת ההשכלה שבאה בהשגה דבינה, והכוונה כאן על עצם נקודת ההשכלה היינו המצאת הדבר לעצמו, דגם בחי' הבן בחכ' הוא ע\"י הירידה מעצם המצאת הדבר כו' ועמשית\"ל בד\"ה וה' אמר המכסה אני הב'), והכח שיש בהנקודה בזה שתבא לידי השגה שזהו בחי' הבן בחכ', ומדות שבחכ' שהרי גם בחכ' יש בה מדות רק שאינם ניכרים כלל כו', וכח ההתגלות שבחכ' כו', גם י\"ל שזה\"ע ההתאמתות שבחכ', ומדות שבבחי' התאמתות וכמו שתיק רב כו' וכמ\"ש במ\"א ונת\"ל פקל\"ה, ונקודת ההשכלה ובחי' הנחה שכלי' שבה כמשנת\"ל פקל\"ח. ופרצוף הוא בחי' אבי\"ע שבכל ספי', והיינו בחי' המדרי' פרטי' ומובדלות שבהספי' כו'. דהנה ד' מדרי' אבי\"ע הן מדרי' נבדלות זמ\"ז, דאצי' נבדל בערך מבי\"ע דהרי אצי' הוא אלקו' ממש, משא\"כ בי\"ע הן בבחי' יש ודבר כו', ולכן נמשל האצי' לאש, וכמ\"ש כי ה\"א אש אוכלה כו' דכמו שאש מובדל מכל היסודות כמו\"כ אצי' מובדל מבי\"ע כו', וכן ברי' מובדל מיצי' שהרי ברי' אינה עדיין בבחי' מציאו' רק אפשרות המציאות ויצי' הוא התגלות המציאות\nכו', וע\"כ המה רחוקים זמ\"ז כו', וז\"ע אבי\"ע שבכל ספי' שהן מדרי' נבדלות כו', ובחכ' י\"ל שזהו עד\"מ כמו ענינים המסתעפים מן השכל שהן ענינים נבדלים מגוף השכל, דהנה פרטי הענינים שבהשכל ה\"ז גופו של ההשכלה שמתחלקת לפרטי הענינים שבה כו', אבל הענינים המסתעפים יכול להיות שהן ענינים נבדלים לגמרי מהשכלה זו כו'. והנה אי' בע\"ח דאבי\"ע הן ד' מדרי' דצח\"מ, דומם הוא עשי' וצומח יצי' דמ\"ש אז ירננו כל עצי היער קאי על מלאכים דיצי' כו', וחי ברי' ומדבר אצי' כו', דד' מדרי' דצח\"מ הן ג\"כ מובדלים זמ\"ז, דמדבר מובדל מכולם ביתרון מעלת השכל שבו שבזה הוא למעלה מכולם שאינו נמצא בשום א' מהם, והגם דבהמה יש לה קצת דעת וכמ\"ש ידע שור קונהו ובורחת מן האש וכה\"ג, הנה זה ענין טבעי לברוח מדבר המזיק, ומה שידע שור כו' זהו דעת הנקנה לבד לא דעת שכלי ממש, כי דעת ושכל לא נמצא רק באדם וע\"כ הוא מובדל מכל הנבראים זולתו כו', והחי מובדל ג\"כ מהצומח בהנפש החיונית שבו, דדומם וצומח הן בקירוב זל\"ז שהרי הדומם יש בו ג\"כ חיות והיא נפש הדוממת, והצומח\nבעצם מהותו הוא דומם רק שיש בו נפש הצומחת, והיינו שהחיות שבו אינו מצומצם כ\"כ כמו בדומם והוא בבחי' התגלות יותר וע\"כ יש בו התפשטו' קצת שצומח מקטנות לגדלות, אבל בעצם מהותו הוא דומם. אבל החי אינו בבחי' דומם כלל היינו שגופו אינו דומם (עמ\"ש בתו\"א ד\"ה להבין הטעם שנשתנה כו' בפ' בראשית), והצומח אינו מערכו כלל, דנפש החי הוא נפש ממש כמ\"ש במ\"א, לא כן הצומח והדומם שהנפש שבהם הוא בחי' חיות לבד לא נפש ממש כו', והמדבר מובדל בערך מהחי כו' כנ\"ל.\n<span data-k=\"ks\"><b>קיצור.</b> ובה\"ע ילה\"ק ההפרש בין ההמשכה בהע\"ס לצורך האצי' ולצורך בי\"ע, דלפעמים נק' ההמשכה בשם אותיות ולפעמים בשם שערות, דהנה יש נקודה ספי' פרצוף, נקודה בחי' כתר שבספי' שהיא הכללית או העצמיות של הספי' וכמו ידיעת עצמו שבחכ' שבכח חכמתו לידע, וכן בחסד, וספי' הוא הי\"ס שבחכ' כמו עצם נקודת ההשכלה, והבן בחכ', ומדות שבחכ' או ההתאמתות או ההנחה שכליות, ופרצוף הוא אבי\"ע, וי\"ל הסתעפות השכל, והן דצח\"מ, שמדבר מובדל לגמרי, וחי מובדל מצומח, וצומח ודומם הן בערך זל\"ז.</span>"],[3601330450,"קמו) <b>והנה</b> במדבר יש ג\"כ ד' מדרי' דצח\"מ, דמדבר בכלל הוא שכל, שבזה יתרון המדבר בשכל ודעת שבו כו' כנ\"ל, ומתחלק ג\"כ לד' מדרי', דבפרטי' יש הרבה מדרי', אך בד\"כ נחלק לד' מדרי' דצח\"מ כו', והדומם הוא שכל שבמעשה הנמוך מכולם, והוא ההתחכמות במלאכות ואומנות לעשות איזה כלי ולתקנה שתהי' בהידור או מלאכת הציור וכה\"ג בשארי אומנות שבמעשה הגשמי', דע\"ה שיש בזה השכלה עכ\"ז ה\"ה מלובשת כולה בדברים חומריים וה\"ה השכלת החומר, והיינו שההשכלה היא חומרי' וה\"ה נמוך במע' ומדרי' השכל, דהרי השכל הוא הכח היותר נעלה בנפש והוא בדקות וברוחני' בעצם, ושכל המעשה הוא שבא בהגשמה עד שאין בזה העילוי שבשכל דהיינו הרוחני' שבו, כי ההשכלה בדבר חומרי גם השכל בזה הוא חומרי, וכמו בעניני' שכלי' הרי כל שהענין נעלה ונפלא ההשכלה בו בבחי' הפשטה ואינו נתפס בגשם כ\"כ, דגם אם מלובש בלבושי השגה ה\"ז בלבושים דקים ורוחני' כו', וכל שהענין נפלא ביותר ההשכלה בו בבחי' הפשטה יותר עד שיש ענינים שאינם באים בלבושי השגה והן בבחי' השערה שכלי' לבד\nכו', ולכן מי שהשגה שלו מגושמת בעצם הרי יש כמה ענינים שאינו יכול להשיגם, דמפני הגשמת שכלו ה\"ה תופס כל דבר בהגשמה, וענינים נעלים שאינם יכולים לבא בהגשמה אינו משיגם בהשגתו כו', והענין שאינו נעלה בעצם ה\"ה בא בלבושי השגה בהגשמה. הרי שלפ\"ע מעלת השכלי לפ\"ע זה הגשמת הענין או הדקות שבו כו', ושכל המעשה הוא שבא בהגשמה שאין בו העילוי והדקות שבשכל עד שכמעט אינו נחשב בכלל השכלה מפני שאין בו המעלה שיש בשכל שהוא הרוחניות כו'. ולמע' מזה הוא באומנות גופא השכלת הדבר, והיינו ההמצאה עצמה איך לעשות לא עצם עשיית הכלי וכמו ההמצאה לעשות כלי המורה על השעות וכדומה, אף שגם זה השכל מלובש בגשמי' עכ\"ז הוא בחי' מוחין דגדלות דעשי' כו', להיות שההשכלה בזה היא מופשטת קצת מן הגשם מאחר שאינה בעשיית הדבר כ\"א רק ההמצאה (ויכול להיות שא\"י לעשות הדבר כ\"א להמציא איך לעשות כו'), וה\"ז בחי' צומח שבשכל דצומח הוא דומם בעצם מהותו רק שהחיות הוא בהתגלות במקצת כנ\"ל, וכמו\"כ הוא בשכל דצומח שבשכל הוא ג\"כ ההשכלה בגשמי' רק שאינו מלובש ממש\nבהגשמי וע\"כ יש בו יותר הרוחני שבשכל כו', ובכלל זה הוא ג\"כ ההשכלה בעניני' טבעים הנק' חכמת הטבע, וכמ\"ש הרמב\"ם ז\"ל דמע\"ב זהו חכמת הטבע היינו ההשכלה בהדברים שכבר נתהוו, ומעשה מרכבה הוא ההשכלה במה שלפני הטבע כו', וחכ' הטבע להיות שזהו בהדברים שנתהוו ה\"ז רק בחי' צומח שבשכל, וכמו חכמת התכונה איך שיעור גודל השמש ואופן הילוך הגלגלים וכה\"ג, כ\"ז הוא בכלל בחי' צומח שבשכל כו'. ולמע' מזה הוא ההשכלה שבדבור והוא השכל שבקטן לצרף ולחבר אותיות ולדבר, והגם שלכאו' זהו השכלה פחותה לגבי השכלות הנ\"ל, אמנם במעלת ומדרי' השכל ה\"ז למע' מהשכלות הנ\"ל, והוא בחי' חי שבשכל. דהנה אי' בע\"ח דהסבה מה שהתינוק גם לאחר שנה אע\"פ שמבין כל דבר ומ\"מ אינו יכול לדבר, הוא מפני שלא נשלם בו עדיין בחי' מוחין דיניקה, שהרי התינוק יש לו קול ויש לו ג\"כ המוצאות שהם כלים להאותי', ואנו רואים בחוש שתינוק קטן מוציא מפיו אותיות מיוחדות הרי יש בו אותי' ג\"כ, ואעפ\"כ אינו יכול להוציא מפיו גם דבר שהוא מבין היטב וכמו בשר ודגים וכה\"ג, אע\"פ שמבחין ויודע היטב שזה בשר וזה דגים ומ\"מ א\"י להוציא הדבר בפיו, והיינו מפני שבכדי להוציא מפיו הרי"],[3601330451,"צריך לצרף ולחבר אותי' שזה מגביל ומתאר את הדבר, וכל זמן שעצם הדבר אינו בבחי' התיישבות בשכלו אינו יכול להגביל את הדבר, כי ידיעתו שיודע שזה בשר ה\"ז אצלו רק בבחי' מקיף לא בהתיישבות ממש ומשו\"ז אינו יכול להגיד זאת (עס זאגט זעך ניט). ולכן אנו רואין שיש הפרש בין תינוק המיושב או בלתי מיושב, דתינוק שהוא מיושב מתחיל קודם לדבר והבלתי מיושב יכול להיות שגם במשך שנים כשצריך להגיד דבר ה\"ז בא בשהיית זמן, דגם שיודע את הדבר מה שרוצה להגיד וחושב בזה ומ\"מ אינו מגיד תיכף מה שחושב רק בשהיית זמן, והיינו מפני שאין הדבר בהתיישבות אצלו ע\"כ צריך שהיית זמן עד שמתיישב אצלו הענין ואז מדבר בזה כו'. וכמו\"כ בתלמיד השומע דבר מרבו ומבין את השכל ומ\"מ אינו יכול להגיד אותו תיכף עד שמחשב הדבר בפ\"ע והוא כי מתחלה הגם שיודע את הדבר ה\"ז בבחי' מקיף עדיין, וע\"י שחושב בזה בפ\"ע מתיישב אצלו הענין ואז יכול להגיד את ההשכלה, ובפרט להחליף באותי' אחרים ושגם הזולת יבין מאתו, כ\"ז צריך שהיית זמן ותפיסא והתיישבות יותר כו', וכ\"ה בגדול מה שאינו\nיכול לגלות השכלתו ולהסביר אל הזולת הוא מפני שאין הענין אצלו בבחי' תפיסא ממש כו' (וכידוע דהאותי' הן מהנפש ונמשכים ע\"י הגילוים מהנפש, וכשהגילוים הם בבחי' התיישבות בכלים אז מתגלים ומצטרפים האותי' שהן כלים אל הגילוי כו'), רק שבתינוק ניכר הדבר יותר דקודם שנעשה בו שלמות הזאת להיות בבחי' התיישבות א\"י לדבר, ואי' בע\"ח שזהו בחי' אלקים דקטנות והוא שעדיין חסר לו אותי' י\"ה דאלקים ונשאר צרוף אלם, וז\"ע שלמות מוחין דיניקה, דענינו הוא דמה שיודע ומשיג יהי' זה בבחי' השגה גמורה בבחי' התיישבות ותפיסא ועי\"ז נעשה בו שלמות זאת שיוכל לצרף ולחבר להביא אור שכלו כו', ובמשך היניקה עדיין לא יש שלמות זאת כ\"א בכלות ימי היניקה ה\"ה נשלם בזה דהשכלה שלו היא בבחי' התיישבות, ועי\"ז יכול לצרף ולחבר אותי' כו'.\n<span data-k=\"ks\"><b>קיצור.</b> המדבר כלול מדצח\"מ, שכל שבאומנות הוא בחי' דומם שמלובש בדבר חומרי ואין בו רוחניות השכל, כי לפי הענין המלביש כן הוא אופן אור השכל, והמצאת הדבר עצמו הוא בחי' צומח וכן חכמת הטבע, ושכל שבדבור לצרף אותיות שזה תלוי בהתיישבות הענין, דהמקיף אינו בא בדבור, וכמו השומע דבר שכל דוקא כאשר חושב הענין ומתיישב אזי יוכל לדבר בו וגם להחליף אותיות, ובתינוק ניכר הדבר, והוא ע\"י שנשלם במוחין דיניקה. </span>\nקמז) <b>והנה</b> השכלה זאת שבדבור ה\"ה למע' מהשכלה דצומח ודומם מב' טעמים, הא' שהאותי' הם רוחני' מרוחני' הנפש וממילא ההשכלה בזה היא רוחני' כו', דכשם שיש הרחק רב בין דומם וצומח ובין החי, כמו\"כ ההרחק וההבדל רב בין השכלת הדומם וצומח שזהו בדברים גשמי' להשכלה שבחי שז\"ע האותי' שהן בחי' חי, וכמ\"ש ויהי האדם לנפש חי' ות\"א לרוח ממללא שההשכלה בזה היא מבחי' רוחני' כו'. והב' שזהו ע\"י המשכת כח עליון שלמע' מהנפש שנמשך בהנפש להיות נשלם בשלמות זו, דהרי שלמות הדבור תלוי בהשלמות שההשכלה תהי' בבחי' התיישבות שז\"ע מוחין דיניקה הרי נשלם בדבר שלא הי' בו קודם. והוא דמקודם לא הי' בו בחי' מוחין דיניקה ולא הי' בו שלמות הנ\"ל, וע\"י שנשלם בו בחי' מוחין"],[3601330452,"דיניקה נשתלם בשלמות הנ\"ל, וידוע דכל גילוי איזה כח שבנפש ובפרט איזה שלמות (שזה יותר מגילוי לבד שהוא רק מה שמתגלה יותר מכמו שהי' מקודם, אבל ענין השלמות הוא שמשתלם בדבר שלא הי' מקודם היינו שנתחדש בו דבר כו'), הנה בכדי שיהי' הגילוי או השלמות ה\"ז ע\"י שנמשך מלמע' מהנפש בהנפש כו', וכמו\"כ השלמות דמוחין דיניקה ה\"ז שלמות שנשלם האדם במה שלא הי' בו קודם, ה\"ז בריאה בידי שמים שיש בזה המשכה מלמע' מהנפש להיות בו שלמות זו, משא\"כ שכל המעשה אין זה שלמות שנשלם באיזה דבר, והעיקר תלוי זה בלימוד ובהרגל שמלמדים אותו מלאכה ואומנות. דהנה השכלת הדבור הנ\"ל אינו תלוי בלימוד, שבאם נמצא בו שלמות הנ\"ל דמוחין דיניקה יבא הדבור ממילא ומעצמו (רק ע\"י ההרגל מתקרב הדבר), ובאם ח\"ו אינו נמצא בו שלמות זו אינו מועיל הלימוד, אבל בשכל המעשה אם לא ילמדו אותו לא ידע מעולם כי לא יבוא הדבר מעצמו, ואם ילמדו אותו יבא הדבר בכל עת וזמן, והיינו מפני שא\"ז שלמות בעצם לומר שנשלם באיזה שלמות שיבוא הדבר מעצמו ולא נתחדש בזה דבר מהנפש שלא הי' בו\nקודם, כי כבר ישנה להשכלה זו בכחו, וע\"י הלימוד וההרגל ה\"ה יודע אותה, כי באמת תינוק שיכול לדבר יש בכחו להשכיל השכלה זו היינו השכלת החומר שהיא נמוכה מהשכלת הדבור, רק שזה אצלו בכח ולא בפועל מפני שאינו יודע ולא הורגל בהדברים שהשכלה זו מתלבשת בהם או מפני חלישות כחו וכה\"ג, וה\"ז עד\"מ חכם גדול ששומע ענין שכלי בלשון שאינו מכיר אותו, הרי יש בכח שכלו להבין את הענין אלא שחסר לו הכלים במה ליקח את הענין, דהיינו שיכיר האותי' והתיבות, וזהו שחסר לו האמצעים לבד לא עצם הענין, ואח\"כ כשלומד הלשון ויודע את הענין הרי לא נתחדש לו בזה איזה שלמות בשכלו בעצם שהרי הי' ביכולתו לידע את הענין מקודם ג\"כ אם הי' יודע את הלשון, אבל במוחין דיניקה הרי נתחדש אצלו שלמות בשכלו שלא הי' בו קודם והוא שנשלם במוחין דיניקה כו', ונמצא דהשכלת הדבור ה\"ז למעלה הרבה מהשכלת החומר וה\"ז בחי' חי שבשכל כו'. אמנם בחי' מדבר הוא ההשכלה האמיתי' והיינו עצם ענין ההשכלה להשכיל ולהתחכם כו', ועיקר ענין מדבר הוא ההשכלה באלקו' והיינו ההשכלה וההשגה במה\nשלפני הטבע, והוא בהאין האלקי המהווה את היש ואיך הוא אופן ההתהוות כו', דההשכלה בזה מופשט מן הגשם, שהרי זהו ההשכלה ברוחני' האלקי וממילא ההשכלה היא רוחני' ממש שזהו אמיתי' ענין השכל כו', וביותר כשההשגה היא בהשגה גמורה כאלו רואה ממש ה\"ז בבחי' הפשטה לגמרי כו', ובפרט ההשגה שבמדרי' עליונות יותר באלקו' שכ\"ז הוא בבחי' הפשטה לגמרי מן הגשם ומופשט מבחי' הגבלה כו', וע\"ה שבשכלי אינו שייך בחי' בל\"ג, הענין הוא שמופשט מהגבלה וישות וה\"ז בתכלית הרוחני' כו'. ובעבודה ענין הד' מדרי' דצח\"מ, הנה בחי' דומם הוא מעהמ\"צ בפו\"מ בקבעומ\"ש, וענין הקב\"ע בזה הוא שבהכרח ובעול ממש שמכריח א\"ע בזה וכמשא כבד הוא עליו כו', וכמו עבד פשוט שאינו רוצה בשום עבודה ושירות דעבדא בהפקירא ניחא לי' ועושה רק משום עול ויראת האדון שעליו, וכמו\"כ הוא ברוחני' שאינו רוצה בקיום המצות ועושה רק בדרך עול והכרח כו', וזה הן בסו\"מ והן בוע\"ט, דבסו\"מ מה שאסרה לנו התורה א\"ז מרוחק ממנו שיהי' הדבר מופרך אצלו איך יעשה זאת ח\"ו (וויא וועט ער טאן מי טאר דאך ניט), רק שמכריח א\"ע לבלי לעשותה, ויש שזה בדברים האסורים ממש ר\"ל, ובדקות"],[3601330453,"הוא בדברים המותרים והוא הכפי' בפו\"מ שהרי ע\"י עבודה ה\"ה ניתק באמת מהענינים החומרים שאינו רוצה בהם, ולפי\"ע העבודה כ\"ה ההעתקה מהחומרי' כו'. אבל בזה הוא שרוצה בכל הדברים ויש לו שייכות גדולה רק שכופה א\"ע בכח שלא יעשה הדבר בפועל כו', וכמו\"כ בועש\"ט הוא שאינו רוצה בקיום המצות ואין לו שום חיות בזה רק מכריח א\"ע לעשות המצוה בפו\"מ כו'. ובחי' הצומח הוא כשיש לו קצת חיות בקיום המצות ע\"י הידיעה וההרגש שמקיים רצה\"ע ומשלים רצונו ית', דבאמת עי\"ז יכול להיות גם שמחה של מצוה, וכמ\"ש במ\"א עד\"מ מלך שמצוה לאדם פשוט לעשות דבר ה\"ה שש ושמח בזה שמשלים רצון המלך, כמו\"כ הרי כאו\"א מישראל נצטווה בקיום המצות וזהו רצונו ית', הרי צ\"ל מזה שמחה גדולה מאד בנפשו, אמנם עכ\"פ כשיש בו קצת הרגש שמקיים ומשלים רצונו ית' יש לו קצת חיות בקיום המצות בסו\"מ ועש\"ט שאין הדבר כבד עליו כו', אך המקיימם באמת הוא האוהב את ש' הוי' וחפץ לדבקה בו כו' כמ\"ש בסש\"ב ח\"א פ\"ד דאהוי\"ר הן מקור רמ\"ח מ\"ע ושס\"ה ל\"ת דכשיש לו אה' אמיתית באלקו' ה\"ה חפץ בקיום\nהמצות שעי\"ז הוא נדבק ויש לו חיות גדול בזה כו', וכן ע\"י יראה בסו\"מ כו', והיינו באהוי\"ר בהתגלות הלב הבאים ע\"י התרחבות ההשגה וההתבוננות באלקו' כו', וזהו בחי' חי כו', דכמו החי יש בו נפש ממש כמו\"כ הוא שיש בזה ריבוי אור וחיות אלקי' כו'. אמנם מדבר הוא העבודה בבחי' מוחין, דהנה בחי' חי שהו\"ע אהוי\"ר שע\"י השגה כו' ה\"ז בחי' מוחין השייכים למדות כו', אבל מדבר הוא בחי' עצם המוחין שלמע' מהמדות והוא בבחי' התקשרות ודבקות באלקות שאינו בבחי' שייכות לדבר שלמטה ממנו כו', כ\"א אדרבה הוא בבחי' תכלית האחדות והדבקות בלמע' באלקות כו'. ובסש\"ב פל\"ח כ' דד' מדרי' דצח\"מ, דומם הוא מעהמ\"צ בלי כוונה, וצומח מובן שם שהן מצות התלויות בדבור וביטוי שפתים כשהן בלי כוונה, ובחי' חי הן האהוי\"ר מוסתרת והן האוי\"ר שבתבונת מוחו ותעלומות לבו כו', ומדבר הן האהוי\"ר שבהתגלות הלב הבאה ע\"י השגה והתבוננות כו', וי\"ל שזהו מה ששייך לקיום המצות, אמנם בעצם העבודה בחי' המוחין השייכים למדות הן בחי' ומדרי' החי, ובחי' מדבר הוא העבודה בבחי' מוחין בעצם בבחי' דבקות ממש באלקו' והוא כענין בחינת מרכבה כו', וכמש\"ש בפל\"ט שזהו מדרי' ברי' ואצי' כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והיתרון בהשכלת הדבור שהוא בדבר רוחני, ועוד שזהו שנשלם בדבר שלא הי' בו קודם, משא\"כ בשכל המעשה שהוא רק לימוד, וכמו למוד הלשון שבו מלובש השכל, וכל שלימות הוא ע\"י המשכה מעצם הנפש, ומדבר שבשכל הוא עצם שכלי בהשכלת אלקות, ובפרט בהפשטה שכן הוא במדרי' הנעלות באלקות, ודצמ\"ח בעבודה, דומם הוא קיום המצות בעול ומשא, או כפי' בפועל, צומח הוא כשיש לו חיות קצת ושמחת הנפש, חי כשקיום המצות הן באהוי\"ר, ומדבר הוא העבודה דעצם המוחין, ובסש\"ב דדומם מעשה, צומח דבור, חי אהוי\"ר המוסתרת, מדבר אהוי\"ר בהתגלות, וזהו השייך לקיום המצות, ובעצם העבודה י\"ל כנ\"ל. קמח) והנה כל הד' מדרי' הנ\"ל שבשכל הכל הוא שכל הנבראים שאין ערוך כלל הנברא לגבי בורא, ומ\"מ צ\"ל שכל מדרי' אלו ישנם ג\"כ באלקות</span>"],[3601330454,"<b>והיינו</b> במדרי' האצי' כו', דשכל הדומם שרשו למע' ג\"כ בחי' דומם וכן בבחי' צומח חו\"מ כו', והגם דשם הכל הוא בבחי' א\"ס כו', מ\"מ הרי בההארה וההשפעה למטה להיות נשפע ממנה שכל הנבראים, אם ישפיע שכל האצי' היינו שכל המדבר תהי' ההארה ממדרי' אצי' שבו, ואם ישפיע שכל צומח תהי' ההשפעה ממדרי' נמוכה שבו בחי' צומח שבו כו'. וממש כמו שההפרש וההבדל רב למטה בנבראים בין שכל המדבר דהיינו שכל אצי' לשכל צומח ודומם, כמו\"כ ההרחק וההבדל רב למע' בין המהווה ומשפיע שכל האצי' ובין המהווה ומשפיע שכל הצומח והדומם כו'. והענין הוא דהנה ידוע דמקור התהוות העולמו' הוא מבחי' מל' דאצי', והנה מצינו ל' עשי' בעולמו' וכמו ששת ימים עשה הוי' וכתי' ויעש אלקי' כו', ולפעמים כתי' ל' דבור וכמו בדבר ה' שמים נעשו וארז\"ל בעש\"מ נבה\"ע כו', והענין הוא דדבורו של הקב\"ה חשיב מעשה, והיינו שיש ב' מדרי' בחי' הדבור ומה שדבור נחשב מעשה, ומבו' במ\"א שזהו ההפרש בדבור היינו בבחי' המל' דכשמקבלת מבחי' יסוד (היינו בחי' חיצוני' יסוד לאחר התעלמות האורות בו כו'\nוכנ\"ל פקמ\"ג) ה\"ז נקרא בשם מעשה, וכשמקבלת מהת\"ת נק' בש' דבור כו'. והנה כח המעשה הוא כח נבדל שהרי בא בדבר נבדל ממנו לגמרי שאינו ממהות האדם כלל, והיינו מפני שבנפש הוא ג\"כ כח נבדל כו', וכמו\"כ הוא למע' שהרי עולם העשי' הוא בבחי' יש ודבר נפרד ממש כו', וע\"כ גם כח המעשה הוא בחי' כח נבדל כו', וז\"ש על כל שבח מעשה ידיך וכתי' כי אראה שמיך מעשה אצבעותיך כו', שכ\"ז הוא בחי' דומם בחי' עשי' מרכ\"ד עד סוכ\"ד כו'. ובחי' הדבור הוא ג\"כ לבוש הנפרד שהרי מתגלה אל הזולת כו', ומ\"מ אינו כמו העשי' שהרי גם הזולת הוא מין האדם עכ\"פ, והיינו בחי' הצומח שהוא ג\"כ בחי' כח נבדל רק שמ\"מ יש בזה גילוי יותר מבחי' דומם כו', ומבחי' הדבור שבמל' הוא הגילוי בעולם היצי' שזהו בחי' צומח כו'. ובעולם הברי' מאיר גילוי אור עליון יותר וכמ\"ש בע\"ח דנקודת המל' עצמה בקעה את הפרסא ויורדת בברי' כו', שזהו גילוי אור האצי' כו', וע\"ה שא\"ז מהות אור האצי' ממש וכמש\"ש בע\"ח שער סדר אבי\"ע פ\"א דמ\"מ נק' בש' ברי' כו' יעו\"ש סוף הפרק, מ\"מ ה\"ז גילוי אור והוא בחי'\nחי כו'. ובחי' מדבר הוא בחי' המל' כמו שהיא באצי', דזהו מה שלפעמים נק' המל' בשם מדבר כו' וכמ\"ש במ\"א. והנה שרש ההתהוות הוא מבחי' חסד דאצי' וכמשנת\"ל פק\"ל בשם הסש\"ב ח\"ב דכל הדברים הנשפעים ומתהווים מאין ליש הוא ממדת חסדו של הקב\"ה שהוא בחי' התפשטו' וגילוי החיות להוות ולהחיות עולמות ונבראים עד אין קץ כו', וכמו\"כ גם כל השכליים שנתהוו הוא מבחי' המוחין שבחסד כי החסד כלולה ג\"כ מע\"ס כו' כנודע, וכמו שהחסד הוא בבחי' פרצוף יש בו אבי\"ע דמזה הוא שרש ומקור בחי' הד' שכלי' דאבי\"ע בכל המדרי' עד למטה בהתחלקות בחי' השכל דדו\"צ וחי ומדבר כו', וכ\"ה במדרי' שלמע' מהחסד דמבחי' אבי\"ע שבהם נמשך בחי' השכלי' דאבי\"ע למטה כו'. וכמשארז\"ל יודע הי' בצלאל לצרף אותי' שנבראו בהם שמים וארץ כו', דהנה בדבר ה' שמים נעשו, אמנם צירוף האותי' ז\"ע השכלת הדבור שלמע' מהאותי' כו', והוא בחי' שכל שבבריאה בחי' חי שבשכל ונמשך מבחי' בינה שבחסד, ומשם הי' שרש נשמת בצלאל שז\"ע בצל א\"ל היית כו', וע\"כ הי' יודע לצרף אותי' כו', דבנין ביהמ\"ק הי' בדוגמא\nשלמע' וכדאי' במד\"ר תרומה פל\"ג דכל מה שברא הקב\"ה למע' ברא למטה כו', ובצלאל שהי' יודע לצרף אותי' כו' הי' ע\"י בנין ביהמ\"ק כו'."],[3601330455,"<b>ולמע'</b> מזה הוא חכ' שלמה דכתי' וה' נתן חכ' לשלמה, ונתינה זו הוא ג\"כ מבחי' חסד עליון והיא מבחי' חכ' שבחסד (ובד\"כ חכ' שלמה היא מבחי' ח\"ת ושרשה מבחי' חכ' שבחסד כו'), דנשמת שלמה למטה הי' נשמה דאצי' ממש והחכ' שלו היא השכלה עצמי' באלקו' לא רק לצרף אותי' כו', והיתה השכלתו בבחי' א\"ס עד שהי' צריך ג' אלפים משל שיהי' קצת השגה בחכמתו, וזהו בחי' שכל המדבר שהוא בחי' אצי' כו'. וכן השגת המלאכים שיעור גבול השגתם נמשך ונתהווה מאין ליש מבחי' החסד דאצי' ויש במלאכים בד\"כ ב' מדרי' יוצר משרתים ואשר משרתיו כו', דיש מלאכים שנק' עומדים וכמ\"ש שרפים עומדים כו', והוא שעומדים משי\"ב ואינם מתבטלים בהשגה שלהם והו\"ע אמירת קדוש שמשיגים בחי' אוא\"ס שקדוש ומובדל כו', דלבד זאת שמשיגים את האור והחיות האלקי המתלבש בתוכם להחיותם, שז\"ע עומדים ממעל לו לגבי ש' אד' שזהו החיות שלהם שמתלבש בפנימיותם וכמו אד' בם כו', ה\"ה משיגים ג\"כ בחי' אוא\"ס הקדוש ומובדל כו' (והוא בחי' נקודת המל' שבברי' כו' כנ\"ל), ואינם מתבטלים בהשגה זאת כו', ויוצר\nמשרתיו הם המלאכים שמתהווים בכל יום ע\"י הבירורי הניצוצות שנש\"י מבררים למטה ועולים ונכללים בבחי' מל', ועז\"נ מצמיח חציר לבהמה, בהמה גימט' ב\"ן והוא בחי' מל' וחציר הן בחי' מלאכים הנ\"ל שנכללים בבחי' מל' כי התהוות שלהם הוא שנבראו בהשגה מוגבלת, וכאשר מאיר להם קצת גילוי יותר מבחי' המל' ה\"ה מתבטלים שעולים ונכללים בבחי' מל' כו', וזהו דאי' בזהר ע\"פ הנ\"ל בהמה רבה דרביעא על אלף טורין ובגמיעא חדא לחיכת לון, וכמו עד\"מ הבהמה שותה בגמיעא והוא שע\"י חוזק רוח פי' אל המים כשחוזרת הרוח נמשכים המים אל פי' כו', וכ\"ה במלאכים הנ\"ל שע\"י הגילוי שנמשך עליהם מבחי' המל' ה\"ה עולים ונכללים כו'. אבל המלאכים שנק' עומדים הוא שיכולים לקבל את האור ואינם מתבטלים בהשגתם כו', והיינו מפני ששרשם ומקורם הוא ממדרי' גבוה יותר דבד\"כ זהו ב' המדרי' דצומח וחי כו'. ועפ\"ז יובן מה שלפעמים נק' ההמשכה בשם אותי' ולפעמים בשם שערות, דהנה האותי' הן מהות הקול ממש אלא שהקול הוא פשוט וכשמתחלק להברת האותי' נשתנה קצת מהותו מפני חיתוך האותי' והגבלתם\nאבל עדיין הוא כמעט במהותו כו', וזהו בחי' חומר האותי'. והנה האותי' הם כלים לאור וכמו אותי' המח' הן כלים לאור השכל שהרי אא\"ל התפשטות והתגלו' השכל בלא מח' הרי יש הארת השכל באותי' המח', וה\"ז הארה לבד לא עצמות השכל מ\"מ ה\"ז הארה השייכה אל העצם וכמו אור וזיו השמש שהוא הארה לבד ומ\"מ ה\"ז מעין העצם כו', וזהו שההמשכה היא מבחי' אצי' שבעליון בחי' מדבר דאצי' הוא בחי' אור הדבוק ומיוחד במקורו כו', אבל כשההשפעה היא מבחי' צומח שבעליון הו\"ע השערות שהן מבחי' מותרי מוחין שנמשך מהם הארה כל דהו ונעשים שערות, שזהו מבחי' פסולת שבמוחין שנבדל מעצם המוחין ונעשים מהם שערות שהן כדבר נבדל דכשחותכין אותן אינו מרגיש כאב כו', וכמו עד\"מ כתיבת איזה שכל באצבע היד הרי האצבע אין לו שום שייכות אל השכל רק ע\"י כמה ממוצעים מתחבר נפש המשכלת עם נפש החיונית ונמשך הארה דהארה ומתלבש בכח התנועה שבדם שבאצבע שכ\"ז בא בבחי' נבדל לגמרי מן השכל כו', ולכן באמת תוכן כוונתו א\"א להביא בכתב וכמו תוונא דלבא לא כתבי אינשי כו', וכמ\"ש בסש\"ב פ\"נ וא\"א לבאר ענין זה היטב במכתב כו', ובדבור יכול לבאר יותר תוכן כוונתו וג\"ז לא כמו"],[3601330456,"שהוא אצלו, רק במח' והשערת השכל יכול לבא על פנימי' הכוונה, וכמ\"ש בסש\"ב שם רק כל איש נלבב ונבון המשכיל על דבר ומעמיק לקשר דעתו ותבונתו בה' ימצא טוב ואור הגנוז בנפשו המשכלת כו', והוא דהשכל הנ\"ל הוא בחי' דו\"צ שאינו בערך לגבי שכל החי וכ\"ש בחי' מדבר כו', וזהו ההפרש בהשתל' הספי' עצמן אם לצורך אצי' או לצורך בי\"ע, דלצורך אצי' עצמה היא בבחי' אצי' שבכל המדרי' דעם היות שהיא ג\"כ הארה לבד מ\"מ יש לה שייכות אל העצם כו', אבל מה שנמשך באצי' גופא בבחי' השתל' מן חו\"ב לז\"א ומז\"א למל' לצורך בי\"ע ה\"ז רק מבחי' דצ\"ח שבעליון שבא בבחי' נבדל מן העצם כו'.\n<b>וע\"פ</b> הנ\"ל יובן מש\"א שלמה אמרתי אחכמה והיא רחוקה כו', דהנה מ\"ש דעה קנית מה חסרת קאי על בחי' שכל דאצי' בחי' מדבר דזהו מעלת המדבר בבחי' שכל ודעת כו', ועז\"א דעת קנית מה חסרת שעי\"ז נשלם כל חסרון כו', דמה שהמל' היא בבחי' חסרון אור זהו בההמשכה שלצורך בי\"ע שההמשכה היא הארה נבדלת וע\"כ בבחי' מל' הוא בחי' העדר האור, אבל בההמשכה שבבחי' אצי' לא יש בחי' חסרון גם בבחי' מל'. והענין דהנה ידוע דה\"ס הראשונות דמל' הן תמיד בבחי' גילוי אור ומה שיש חסרון אור זהו בה\"ס האחרונות כו', וכידוע המשל מהלבנה שיש בה מילוי וחסרון היינו בחצי הכדור שכנגד חלל העולם, דחצי כדור העליון מאירה תמיד מן השמש רק חצי כדור התחתון אינו מאיר כו', ובר\"ח שאז מולד הלבנה היינו התחלת האור בחצי כדור התחתון והולכת ומאירה עד ט\"ו לחדש שאז מאיר כל חצי כדור התחתון ג\"כ כו', וכמו\"כ הוא למעלה בבחי' מל' דה\"ס הראשונות דמל' שזהו בחי' המל' כמו שהיא באצי' יש בה תמיד גילוי אור וזהו שהמל' היא בחי' מדבר כו', ובחי' חסרון האור הוא בה\"ס האחרונות\nדהיינו כמו שהמל' נעשה מקור לבי\"ע כו'. והנה בימי שלמה קיימא סיהרא באשלמותא שהי' האור והגילוי גם בה\"ס האחרונות, והיינו כנ\"ל להיות דשלמה הי' נשמה דאצי' המשיך את האור כמו שהוא במדרי' האצי', וע\"כ הי' הגילוי בכללו' בחי' המל' גם בה\"ס האחרונות כו', וזהו דעת קנית בחי' דעת דאצי' מה חסרת שלא יש שום חסרון כלל כו', ומ\"מ פרשת פרה אדומה לא עמד עלי'. דהנה באגה\"ק סי' כ\"ח כ' דענין קידוש מי חטאת הוא בחי' קדש העליון הנק' טלא דבדולחא, ושם בשם הזהר שהיא בחי' ח\"ע ומו\"ס כו', דמו\"ס הוא בחי' חכ' שבכתר וח\"ע זהו בחינת חכ' דאצי' והיינו בחי' עצמות החכ' ממש לא בחי' הארה לבד כו', וע\"כ לא עמד שלמה ע\"ז דעם היות שהי' בבחי' אצי' הרי כ\"ז הוא רק הארה לבד, אבל עצמות החכ' ה\"ז למע' מע' כו', וע\"ז לא עמד בחכמתו כו', ומ\"מ אמרתי אחכמה להיות שהיא הארה שמעין העצם ע\"כ אמרתי אחכמה כו', אבל לא עמד עלי' כו'. וא\"ז סותר למש\"א מה חסרת דמאחר שזהו מה שמובדל בערך מהשתל' א\"ז חסרון בסדר השתל' כו', דהנה באור דס' השתל' גופא בחי' העדר האור הוא\nחסרון וגילוי האור ה\"ז מילוי החסרון כו', אבל מה שמובדל בערך מהשתל' הרי ההעדר א\"ז חסרון בהשתל' כו', וכמ\"ש במ\"א בענין מה הי' העולם חסר כו' בא שבת כו'. וזהו שהקדים ואמר זאת חקת התורה דחקה היא שלמע' מטו\"ד, ואין הכוונה שהוא למע' מטו\"ד לגמרי רק שאין זה דעת שבעולם דהדעת שבעולם הוא בחי' הדעת שבס' השתל' ודעת זה הוא שמובדל מסדר השתל' והוא בחי' עצמות החכ' ממש כו'. וזהו וידבר ה' אל משה כו'"],[3601330457,"זאת חקת התורה כו', שמצות פרה אדומה הוא בחי' חוקה דשלמה לא עמד עלי', שהיא בבחי' דעת דאצי' והיא בחי' הדעת שממשיך מבחי' חיצוני' חו\"ב שהוא בחי' הארה לבד ואמרתי אחכמה להיותה מעין העצם כו', והיא רחוקה כו' וזהו זאת חקת התורה שלמע' מטו\"ד, ואו' חקת התורה דוקא דתורה הוא בחי' חכמה והיינו שזהו ג\"כ דעת רק שהיא למעלה מהשתל', וע\"י תורה ומצות נמשך בחי' עצמות החכמה ממש כו'.\n<span data-k=\"ks\"><b>קיצור.</b> והדוגמא למעלה בבחי' מל' מקור התהוות, דבורו של הקב\"ה חשיב מעשה כשמקבלת מחיצוניות היסוד, דמעשה הוא כח נבדל ה\"ז בחי' דומם, ודבור שזהו כשמקבלת מת\"ת זהו בחי' צומח שמאיר ביצי', עצם נקודת המל' הבוקעת את הפרסא ומאיר בברי' זהו בחי' חי, ומל' כמו שהיא באצי' זהו בחי' מדבר. וזהו אבי\"ע שבמל'. וכ\"ה בהספי' שלמעלה, יודע הי' בצלאל לצרף אותיות בחי' שכל שבברי', וחכמת שלמה שכל האצי', ובמלאכים יוצר משרתים המתהווים מהבירורים ונכללים במל' זהו בחי' צומח, ואשר משרתיו העומדים משימ\"ב שמקבלים את האור הן בחי' חי, וזהו ההמשכה שבבחי' אותיות שהן בחי' כלים ובהם מאיר הארת השכל שמעין העצם זהו בחי' אצי', ושערות הוא ההמשכה דבחי' צומח, וכמו אותיות הכתב, וזהו דההמשכה לצורך אצי' הוא מבחי' אצי' שבכל ספי' ולצורך בי\"ע הוא מבחי' דצ\"ח. ובזה יובן מ\"ש זאת חקת התורה, דעה קנית בחי' אצי' שבכל ספי', והוא חכמת שלמה. וזה ממלא החסרון שבמל', קיימא סיהרא באשלמותא, ועל פר\"א לא עמד שזה חכ' שלמע' מאצי', וא\"ז חסרון מפני שמובדל, וזהו חקה.</span>"],[3601330458,"<h3>בס\"ד. ש\"פ בלק, תער\"ג</h3>\n<b>כי</b> מראש צורים אראנו כו', ואי' במד\"ר בא פט\"ו מראש צורים אלו האבות, מוצאים אנו מתחלה הי' המקום מבקש לכונן את העולם ולא הי' מוצא עד שעמדו האבות, משל למלך שהי' מבקש לבנות מדינה כו' בא ליתן היסוד והיו המים עולים מן התהום ולא היו מניחים כו' ומצא שם צור גדול אמר ע\"ז אני קובע את המדינה כו', כך מתחלה כו' והי' האלקים מבקש לכונן את העולם ולא היו הרשעים מניחים כו' כיון שבאו האבות וזכו אמר הקב\"ה על אלו אני מכונן את העולם שנא' כי לה' מצוקי ארץ וישת עליהם תבל כו'. ולכאורה המדרש תמוה דמהו\"ע שהי' הקב\"ה מבקש לכונן כו' ולא הי' מוצא כו', ומהו\"ע לכונן שא\"ז בריאת והתהוות העולם כו'. וגם אומרו מוצאים אנו משמע שזה דבר פשוט שהי' המקום מבקש לכונן כו' והיכן מצינו זאת, דעל ברה\"ע אמרו במדרש ע\"פ שוקיו עמודי שש שוקיו זה העולם שנשתוקק הקב\"ה לבראותו כו', אבל היכן מצינו שהי' מבקש לכונן את העולם כו', ומהו הפשיטות בזה כ\"כ שהי' מבקש לכונן כו'. גם מהו\"ע ולא היו הרשעים מניחין אחרי שהי' מבקש לכונן איך לא היו מניחין כו', גם אומרו עד שבאו האבות וזכו כו' מפני מה האבות דוקא זכו לזה שעליהם אני מכונן כו'. גם"],[3601330459,"צ\"ל דקדוק ל' וזכו דלכאו' הול\"ל סתם עד שבאו האבות כו'. גם צ\"ל אומרו שהי' המקום מבקש כו' דשם המקום אינו רגיל כ\"כ בדרז\"ל מפני מה או' ש' המקום כו'. ולהבין כ\"ז ילה\"ק משנת\"ל שבס' השתל' בע\"ס דאצי' יש הפרש בין השתל' שלצורך האצי' ובין ההשתל' שלצורך בי\"ע, והיינו דבהשתל' הע\"ס גופא אינו דומה ההשתל' דלצורך בי\"ע לההשתל' שלצורך דאצי' כו', דלצורך האצי' ההמשכה מספי' לספי' הוא בחי' אור שמעין העצם כו', וההמשכה בהע\"ס שלצורך בי\"ע הוא בבחי' הארה נבדלת כו'. ונת' שבכל ספי' יש אבי\"ע שהן ד' מדרי' דצח\"מ שגם במדבר יש ד' מדרי' אלו כו' והיינו שגם בשכל יש ד' מדרי' אלו כו', ודומם וצומח הן בבחי' נבדל וכמו שכל שבעשי' ושכל שבטבע כו', וחי הוא בחי' המוחין רק שזהו בחי' שכל שבדבור, ולמעל' יותר הן בחי' המוחין השייכים למדות כו', ומדבר הוא בחי' עצמות המוחין כו'. והדוגמא מזה שגם באצי' (שזהו בחי' מדבר בכלל) יש בכל ספי' ד' מדרי' אלו, ועיקר בחי' אצי' הוא בחי' עצמות המוחין וההמשכה שלצורך בי\"ע הוא בחי' דומם וצומח שבמדבר וגם בחי' חי שבמדבר שא\"ז עצמות המוחין כו'.\nקמט) <b>ולהבין</b> בתוס' ביאור איך שההמשכה בע\"ס דאצי' גופא שלצורך בי\"ע הוא בבחי' הארה נבדלת כו'. הענין הוא דהנה ידוע שיש ב' אופנים בעו\"ע, הא' שהעלול הוא מהות נבדל מהעילה רק שנמצא כלול בהעילה וההתגלות שלו הוא ע\"י העילה, אבל בעצם מהותו הוא מהות נבדל מן העילה כו', וההשתוות שלהם הוא רק מה ששניהם הם מציאות רוחני וע\"כ העלול הוא כפי אופן העילה דעם היותו מהות אחר בעצם מ\"מ ה\"ה מצטייר ומתגלה כפי אופן העילה כו', דלהיותו מציאות רוחני וההתגלות שלו הוא ע\"י העילה ע\"כ הציור וההתגלות שלו הוא כפי אופן העילה כו', אבל בעצם הוא מהות אחר נבדל מהעילה כו'. והב' הוא שהעלול הוא התפשטות העילה ואינו מהות אחר ממנו כו', וכמו הענף המתפשט מן האילן שהוא ממהותו של האילן רק שאינו גופו של האילן כ\"א ענף המתפשט ממנו אבל אינו מהות נבדל כו', וכמו\"כ יש בעו\"ע שאין העלול נבדל מן העילה ויש שהוא בבחי' מהות נבדל ממנו והוא מ\"מ בבחי' עו\"ע כו' (ועמשנת\"ל פל\"ט). ויובן זה עד\"מ משכל ומדות ומחדו\"מ שכולם הם בבחי' עו\"ע וכנודע דמדות מן\nהשכל הן בבחי' עו\"ע כו', דלידת והתגלות המדות באה מן השכל דכאשר מבין בשכלו שהדבר טוב לפניו ה\"ה מתעורר באה' וכאשר מבין שלא טוב לפניו הדבר אינו רוצה בו כו', והתגלות המדות הן לפי אופן השכל (והיינו בחי' הדקות והחומרי' של המדה והו\"ע התוקף והחלישות כו') דלפי אופן השכל המחייבם את המדות כך המה המדות כו', וכן מחדו\"מ הן בבחי' עו\"ע כו', דמחדו\"מ הן לבושים לנר\"ן שבנפש שהן שכל ומדות וכח ההודאה שבנשמה שזהו בחי' נפש כו', שמהן משתלשלים הלבושים דמחדו\"מ בדרך עו\"ע כו'. והענין הוא דהנה מחדו\"מ המבו' כאן אין הכוונה אותי' המח' ואותי' הדבור ואותי' המעשה שהן אותי' הכתב כו', כ\"א הכוונה על כח המח' וכח הדבור כו', דהנה ידוע דמה שהאותי' באים מן המוצאות אחה\"ע מן הגרון גיכ\"ק מן החיך כו', א\"ז שעצם התהוותם הוא מהמוצאות כו', והיינו שנא' שמקודם אינם נמצאים האותי', ובהמוצאות הוא שנתהוו האותי' דכאן נמצאו וכאן היו כו', שהרי גם הבע\"ח יש להם המוצאות ואינם יכולים לדבר וכן האלם יש לו כל המוצאות כו',"],[3601330460,"אלא דעיקר האותי' הן בעצם הנפש והוא כח ההתגלות שבנפש, ויש כ\"ב מיני כחות התגלות בנפש דכל ההמשכות וההתגלות שבנפש הוא ע\"י כח ההתגלות שבו כו', וכמו ההמשכה מכח השכל שבנפש ומכח המדות שבנפש הכל הוא ע\"י האותי' שבנפש שזהו כח ההתגלות שבנפש כו', וכאשר באה ההמשכה וההתגלות מן הנפש הנה האותי' (שזהו כח הגילוי של ההמשכה ההיא) נמצא כלול בהאור וההמשכה שמהנפש כו', דתחלת ההמשכה וההתגלות הוא ע\"י האותי' שהוא כח ההתגלות כו', ואח\"כ נמצאו כח הגילוי שהן האותי' כלולים בההמשכה וההתגלות כו', ואח\"כ כשבאים בהמוצאות נעשים בבחי' מציאות במורגש שע\"י הוא הגילוי ממש כו', אבל עיקר האותי' הוא כח ההתגלות שנמצא בעצם הנפש וכן בהגילוים מהנפש כו', שהרי הדבור שמהמוצאות לבד יכול להיות גם בבע\"ח וכמו עוף הזרזיר או הפופגאי שמלמדים אותו לדבר, ומ\"מ אינו בכלל מדבר לפי שאין בהם כח ההתגלות כ\"א שמלמדים אותם להניע המוצאות ועי\"ז באים האותי', ולכן א\"י לדבר רק מה שמלמדים אותם כו', וא\"ז ענין הדבור דענינו הוא כח ההתגלות ועי\"ז בא הדבור מהמוצאות\nכו'. ונמצא מובן איך שאותי' המחדו\"מ הן בדרך עו\"ע שהרי נמצאים כלולים בהאור והגילוי שמהנפש ובאים מהן בדרך ממילא כו' (ועמשנת\"ל פקמ\"ז), ואותי' המח' שייכים יותר אל המוחין ואותי' הדבור שייכים יותר אל המדות כו' (ולכן אותי' המח' הן בדקות יותר כו'), ומ\"מ ה\"ז בבחי' מהות אחר מהכחות שבנפש (שזהו ההמשכה מהנפש) ובבחי' נבדל מהם כו', שהרי בנפש הוא רק כח ההתגלות שבנפש (שהוא כח נבדל כו'), וכמו\"כ בההמשכות שמהנפש ה\"ז רק בחי' הגילוי שלהם לא עצם מהות הכח כמו השכל או המדות כו' (והגם שהמדות הן ג\"כ התגלות כו', זהו מפני שהן הארה לבד כו', וכמשנת\"ל ד\"ה ואשים דברי בפיך, אבל בעצם מהותם הן בחי' חו\"ג וכה\"ג, והאותי' עצם מהותם הוא כח ההתגלות כו'), וכמו\"כ המדות הן מהות נבדל מן המוחין שה\"ה כחות אחרים לא שכל כו', וכל ענין המדות הו\"ע ההרגשה דהרגשת עצמו הוא יסוד המדות ואא\"ל שום מדה כמו אה' או יראה בלי הרגשת עצמו כו' (וזהו שהדעת הוא חיות המדות ופנימיותן כו' וכמ\"ש במ\"א), וגם המדות הן בבחי' התפעלות כו', דבמוחין אינו שייך כ\"ז\nשאינם בבחי' הרגשה אדרבה הן בבחי' ביטול והנחת עצמותו כו' (וכמא' כל גיא שוטה כו' וכמו ראית איש חכם בעיניו כו'), ובכדי לבא על אמיתית השכל זהו דוקא כשלא יש הרגשת עצמו כו', וכן המוחין אינם בבחי' התפעלות אדרבה ההתפעלות מבלבל אל המוחין כו', וכן הרגש עצמו מבלבל אל המוחין כו' וכמ\"ש במ\"א, הרי שהמדות הן מהות נבדל מן המוחין כו', ומאחר שהן מהות נבדל הרי גם הארת המוחין שמאיר בהמדה אינו עצמו' המוחין כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ויקדים איך שיש ב' אופנים בעו\"ע, הא' שהעלול מהות נבדל מהעילה, וכמו מדות שנולדים מן השכל ולפי אופן השכל, וה\"ה מהות אחר שהן בבחי' הרגש עצמו ובהתפעלות, והמוחין הן ביטול והנחת עצמותו ובלי התפעלות, וכן כח המחו\"ד הן עו\"ע משכל ומדות, דכח מחו\"ד הוא כח ההתגלות שבנפש שע\"י הוא ההמשכות והגילוים מהנפש, וכן ההמשכות יש בהם כח הגילוי וזהו כח המחו\"ד, וא\"כ ה\"ז בדרך עו\"ע, והרי האותיות הן מהות נבדל מהנפש והגילוים, וממילא גם הגילוי שבהם הוא הארה נבדלת.</span>"],[3601330461,"קנ) <b>ויובן</b> זה בעבודת ה' שע\"י התבוננות אלקי ה\"ה בא לידי התעוררות אהוי\"ר כו', שזהו תכלית הכוונה שיהי' התעוררות הלב באהוי\"ר, כי ע\"י אהוי\"ר בהתגלות הלב הוא הזיכוך ובירור החומריות דנה\"ב ותיקון כל הענינים וגם עי\"ז הוא קיום המצות כדבעי למהוי בסו\"מ וע\"ט כמ\"ש במ\"א באורך, וזהו כל תכלית האדם בעולם שבשביל זה הוא ירידת הנשמה בגוף כמ\"ש במ\"א. ואהוי\"ר הוא שיהי' ע\"י התבוננות דוקא כו', דמתחלה צ\"ל ההתבוננות בענין התהוות יש מאין בכללות הענין איך שכל דבר יש נתהווה מאין אלקי המהווה אותו כו', וזה מובן מהיש עצמו דכאשר אנ\"ר מציאות יש בהכרח לומר שנתהווה מאין כי אא\"ל יש מיש עד בלי תכלית כו', לבד זאת שא\"א להיות יש מיש בלי אין באמצע וכמ\"ש במ\"א, הנה שיהי' יש מיש עד בלי תכלית הוא בלתי אפשר כו' (שהרי כל ענין היש הוא ההגבלה ואיך אפ\"ל בלתי תכלית לו שזה היפך מהותו כו', ובהכרח שיש לו קץ היינו התחלה כו' וכמ\"ש הרמב\"ם במו\"נ בהקדמות דיש מיש בלי תכלית לו הוא שקר גמור כו'), ובהכרח שנתהווה מלא דבר דהיינו בחי' האין\nהאלקי כו', וגם דכל מציאות יש הוא מורכב שכ\"ה בכל מציאות שנברא בהכרח שיש בו הרכבה גם החומר הראשון הוא מורכב (ורק לגבי הד' צורות שמתהווים ומצטיירים ממנו הוא פשוט לגביהם, אבל בעצם הוא מורכב כו'), והיינו שמורכב מהיסודות ומורכב מגוף ונפש חומר וצורה, וכל דבר המורכב א\"א שיהי' מציאותו מעצמו מאחר שצריך לעוד דבר כו', וא\"כ הרי מהיש עצמו מוכרח שנתהווה מאין אלקי כו', וזהו ההשגה וההתבוננות כללי דהתהוות היש הוא מאין כו'. וצ\"ל ההתבוננות בפרטי' היינו באיכות האין האלקי המהווה את היש כו', והוא דעם היות דענין התהוות היש מאין הוא בדרך אין ערוך דהיינו בבחי' ריחוק כו' (דמשו\"ז נתהווה בבחי' יש כו'), מ\"מ בהכרח ג\"כ לומר שיש קירוב ושייכות האין אל היש שיהי' ממנו התהוות היש כו' (דזהו ההפרש בין אמיתי' שרש ההתהוות שמן העצמות דהוא לבדו בכחו ויכולתו כו' שזהו בבחי' אין ערוך לגמרי וכמא' אין ערוך לך בעוה\"ז כו', ובין ההתהוות מהאין האלקי שזהו מ\"מ בבחי' קירוב והו\"ע הרצון להוות כו', ובחי' מל' דאצי' הוא הרצון להוות בפועל כו',\nכמ\"ש מזה בדרוש יו\"ט של ר\"ה, רס\"ו), ומאחר שצ\"ל האין בקירוב אל היש בהכרח שיש בזה ס' השתל' איך שהאין האלקי נמשך ממדרי' למדרי' עד שיהי' בבחי' מקור ליש כו'. וזהו אריכות ההתבוננות דב\"ש כו', דברוך שאמר והי' העולם הוא בחי' אמירה דא\"ק כו', ולמע' יותר ברוך שאמר קאי על מל' דא\"ס והו\"ע האמירה דמל' דא\"ס להיות התהוות א\"ק בחי' אדם דברי' דכללות כו', וזהו שאמר והי' העולם דמל' דא\"ס נעשה כתר ועתיק לא\"ק כו', וגם ברוך שאמר הוא אמירה דא\"ק והי' העולם זהו שמל' דא\"ק נעשה כתר ועתיק לאצי' כו' וברוך הוא זהו בחי' כתר הפרטי דאצי' כו', ואח\"כ חושב פרטי המדרי' דע\"ס דאצי' עד ברוך מרחם על הבריות שזהו בחי' מל' דאצי' שנעשה כתר ועתיק לברי' כו', ואח\"כ חושב פרטי מדרי' דבי\"ע כו'. דכ\"ז הוא ירידת האין האלקי שיורד ממדרי' למדרי' עד שנעשה בבחי' אין המקור ליש כו'. וכ\"ז הוא בבחי' אור האלקי השייך אל העולמות והיינו מה שנמדד מאוא\"ס ב\"ה להיות בבחינת שייכות אל העולמות שיש בזה חילוקי מדרי' בס' ההמשכה כו', ומפני זה יש ג\"כ חילוקים בהעולמות\nשנתהוו מהאין כו', דהרי בירידת האין האלקי ממדרי' למדרי' הרי בכל מדרי' ומדרי' נתהוו מזה עולמות שהן לפי אופן דהאין האלקי כו', וזהו הן בעולמות"],[3601330462,"בי\"ע הכללים דא\"ק הוא אדם דברי' דכללות, ויש אדם דיצי' ואדם דעשי' דכללות כו', והן בעולמות בי\"ע הפרטים כו', וכ\"ז הוא בההארה האלקי' שאחה\"צ שיש בזה חילוקי מדרי' כו', והחילוק הוא באופן הגילוי דבמדרי' העליונה האין הוא בבחי' גילוי אור יותר כו' (וכמו בברי' שמאיר גילוי האין האלקי כו' וכמ\"ש במ\"א), ובמדרי' התחתונה א\"ז בבחי' גילוי אור כ\"כ וע\"כ נעשה בבחי' מקור ליש כו'. והנה בהתבוננות זאת הגם שלא יהי' מזה איזה מדה פרטי' הרי נעשה מזה הקירוב לאלקו' בכלל והו\"ע החקיקה מבחוץ כו', והיינו שע\"י ההתבוננות וההרגש בנפשו בהאין האלקי המהווה את היש כו', ובפרט באיכות האין האלקי ובפרטי התהוות שנעשה מזה כו', ה\"ה מתקרב מאד לאלקו' וניתק מן כל הענינים החומרים כו', וה\"ה יוצא בזה ממעמדו ומצבו הראשון ומתעלה במדרי' עליונה יותר כו'. ובכדי שתהי' החקיקה מבפנים זהו ע\"י ההתבוננות בבחי' הגילוי שבעולמות כו', והיינו בבחי' אור וחיות אלקי המתלבש בתוכם להחיותם וכמ\"ש ואתה מחי' את כולם כו', והוא איך שכל נברא יש בו חיות אלקי המחי' אותו\nכו', דכשם שאין דבר עושה א\"ע כמו\"כ אין דבר חי מעצמו כ\"א מהאלקות המחי' אותו כו', ומבשרי אחזה אלק' וכמו שהאדם מרגיש בעצמו שיש בו נפש המחי' אותו ושהעיקר הוא הנפש דכל תנועת החיונית שלו הוא מהנפש ובצאת הנפש מהגוף ה\"ה נשאר כאבן דומם כו', וכמו\"כ יבין בעולם שרואה שהעולם חי הרי יש בו חיות המחי' אותו והחיות הוא אלקות, וכמ\"ש וה' אלקים אמת הוא אלקים חיים, דענין אמת הוא מה שהוא בבחי' קיום נצחי כו' ואמיתי' ענין קיום נצחי הוא עצמות א\"ס דמציאותו מעצמותו כו', וכמו\"כ הוא בהאור שהוא דבוק ה\"ה מעין העצם שהוא ג\"כ בבחי' קיום נצחי כו', וכנודע בענין הוא קיים ושמו קיים דהוא קאי על העצמות ושמו קיים הוא בחי' האור כו' וכמ\"ש במ\"א. ויש חילוק באופן הדבקות אם הוא דבוק בעצם או שהדבקות הוא בבחי' ההתחדשות שמתחדש תמיד ממקורו כו' וכמ\"ש במ\"א, דג\"ז הוא בחי' דבקות כו', וע\"כ הוא בבחי' חיות להחיות כו', וזהו שהחיות הוא האלקו' המחי' כו' ואם ח\"ו יסתלק החיות יהי' אין ואפס כו', דא\"ז כמו חיות הנפש בגוף שאין התהוות הגוף מהנפש כו' אבל\nהעולם הרי התהוותו הוא מהאור האלקי וע\"כ בהסתלק כו'. ובאמת הן ב' מדרי' באלקות והוא בחי' אין האלקי המהווה את הנבראים והאור האלקי המחי' אותם כו', ומ\"מ גם קיום מציאותם תלוי בהאור האלקי המחי' מפני שהמשכת הכח האלקי המהווה הוא ע\"י האור המחי' להיותו בחי' גילוי כו' וכמ\"ש במ\"א. אך זה אינו נוגע להתבוננות זאת, והעיקר בהתבוננות זאת הוא שכל נברא יש בו אור וחיות אלקי המחי' אותו ושהעיקר הוא האור האלקי כו', שע\"י ההתבוננות והעמקת הדעת שיורגש הענין בנפשו ה\"ה מתעורר ומתפעל באה' שאוהב את ה' וחפץ לדבקה בו והוא שתהי' דבקות נפשו רק בהאור האלקי כו', ורוצה שהאור האלקי יאיר בגילוי בנפשו ובעולם כו', וכמו האדם ע\"י שמרגיש שהעיקר הוא הנפש ה\"ה רוצה בגילוי אור הנפש, ובפרט כשהוא חלוש ומעונה ה\"ה תאב מאד לגילוי אור וחיות הנפש כו', כמו\"כ כאשר מבין ומרגיש שיש חיות אלקי המחי' ושהעיקר הוא אלקות כו', ה\"ה רוצה בגילוי האור האלקי כו', ובפרט בריבוי ההעלמות שאין האור האלקי נגלה ה\"ה תאב מאד אל הגילוי כו'. וביותר כאשר מתבונן באופן\nהאור והחיות האלקי שבעולמות דג\"ז מבשרי אחזה דכמו בנפש יש נר\"נ שבנפש, כמו\"כ באלקו' יש ג' בחי' נר\"ן המתלבש בעולמות, וע\"י השגת ענינים אלו בנפש יבין"],[3601330463,"כמו\"כ באלקות כו', ועי\"ז תהי' האה' והרצון ביותר שירצה בהאלקות ובגילוי האור כו' ולא כמו שנראה ונגלה בעולם שנראה רק הישות והאור האלקי אינו נגלה כו', רק רצונו שיהי' גילוי האור האלקי כו', ולפעמים יהי' מזה מרירות הנפש והוא ממה שהנראה בעולם הוא היפך האמת לגמרי כו', וביותר מההסתר שבנפשו שההרגש עצמו אצלו הרבה יותר מההרגש אלקי כו' ע\"ז יתמרמר מאד בנפשו כו'. אך בעבודה ישרה היינו בעבודה כדבעי למהוי צ\"ל מהתבוננות הנ\"ל העבודה בשמחה (והמרירות צ\"ל קודם התפלה בתקון חצות כו' וכמ\"ש במ\"א) שמתעורר באהבה לאלקו' ורוצה בהגילוי אור כו', וכן רוצה מאד בעסק התורה וקיום מצותי' שעי\"ז נמשך ומאיר האור האלקי וע\"כ נותן א\"ע בקיום התומ\"צ כו', וכמו\"כ בכל הדברים המוכרחים תכלית כוונתו הוא בהאלקו' שבזה, וכמו באכו\"ש דלא על הלחם לבדו יחי' כו' כ\"א על כל מוצא פי ה' כו', שזהו המוצא פי ה' שבמאכל שבזה יחי' האדם ויתוסף בו אור וחיות אלקי בתו' ועבודה כו'. והנה ע\"י ריבוי היגיעה והשקידה במשך זמן באופן העבודה הנ\"ל בהתבוננות האור והחיות\nהאלקי שבעולמות ובאופן האור כו', עד שכ\"ז מתאחד ומתעצם אצלו שעומד בדרגא זו בעבודתו כו', הנה יכול לבא אח\"כ למדרי' גבוה יותר והוא שבא להשגה אחרת שלמע' מהשגה הנ\"ל, והיינו איך שכ\"ז הוא רק הארה לבד שבאין ערוך לגבי עצמות כו', וזהו ג\"כ ענין שאמר והי' העולם איך שכל העולמות נבראו באמירה א' לבד כו', דהגם דממך הכל כתי' ומ\"מ ה\"ז רק בחי' אור וזיו מן העצמות כו', ולאו דוקא בעולמות תחתונים לבד אלא שגם האור שבעולמות עליונים ה\"ז רק הארה שאינו בערך העצמות כו', ועי\"ז נעשה תוקף הרצוא להכלל בעצמות אוא\"ס כו', והיינו לא זו בלבד שאינו רוצה בחיצוני' העולמות אלא שגם בהגילוים א\"ז תכלית רצונו כ\"א תכלית חפצו ורצונו הוא בעצמות אוא\"ס ב\"ה, וזהו בב' אופנים או שרוצה להכלל בעצמות בבחי' כליון כו', או שרוצה שיהי' המשכת העצמות ומשו\"ז נותן א\"ע בקיום התומ\"צ אך לא בשביל המשכת ההארה כ\"א שיהי' עי\"ז המשכת העצמות כו'. ולמע' מזה הוא כאשר ההתבוננות היא בההפלאה והרוממות דעצמות אוא\"ס כו', דהנה בהתבוננות הקודמת הרי כל ההשגה שלו וההתעסקות\nשלו (זיין גאנצער פארנעם) הוא בההארה אלקי' רק שזהו שמתבונן איך שזהו הארה לבד כו', אבל כאן הרי ההתבוננות הוא בעצמות אוא\"ס שהוא מופלא ומרומם וכמ\"ש והקדוש בשמים ובארץ כו', וע\"י ההתבוננות וההרגש דהפלאת ורוממות הא\"ס יבא לידי יראה ופחד ה' כו', וכמו עד\"מ במלוכה למטה שכל ענין המלוכה הו\"ע היראה וכמ\"ש שום תשים עליך שתהא אימתו עליך הרי צריכים לרומם את המלך שעי\"ז דוקא הוא היראה כו' וכמארז\"ל, כמו\"כ למע' ע\"י ההתבוננות בהפלאת ורוממות הא\"ס נעשה מזה היראה ופחד ה' כו'. אך תחלה צ\"ל ההשגה בההארה האלקי' שישיג היטיב פרטי המדרי' בעצם מדריגתן ומעלתן שיש בזה מדרי' גבוהות ונעלות מאד, ומזה יבין ההפלאה והרוממות דאוא\"ס ויבא לידי יראה כו', ויש ג\"כ יראה הבאה מההתבוננות בבריאת והתהוות העולמות שמכחו ויכולתו ית' בהתהוות העולמות נופל היראה והפחד כו', וכמ\"ש יראו מה' כל הארץ כו' כי הוא אמר ויהי כו' וזהו יר\"ת כו', והיראה שמצד הרוממות הוא בחי' יר\"ע כו'. וכאשר ההתבוננות היא בעצמות אוא\"ס שהוא נמצא למטה כמו למע' כו', דהגם דעצמות אוא\"ס מובדל לגמרי מעולמות התחתונים והעליונים כו', ה\"ה הנותנת שנמצא למטה כמו למע' וכמ\"ש"],[3601330464,"המגביהי לשבת המשפילי לראות בשמים ובארץ, דלהיותו מגביהי לשבת לכן המשפילי לראות כו', ועי\"ז יהי' יראה פנימי' יותר כו', וגם לזה צריכים ההתבוננות בההפלאה והרוממות דאוא\"ס דמזה יבין איך שמשפילי לראות שנמצא למטה כמו למע' ממש כו', וגם משום עצם היראה צ\"ל לזה השגת והתבוננות רוממותו ית' כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ובעבודה הרי תכלית הכוונה שיהיו המדות אהוי\"ר וע\"י התבוננות דוקא, ותחלה יתבונן בהתהוות היש שמוכרח שהוא מאין, להיותו מוגבל ומורכב, ואח\"כ באיכות ההתהוות שהוא באין ערוך, ומ\"מ הוא בבחי' קירוב ושייכות האין אל היש (דאין ערוך לך דוקא), וזה ע\"י ההשתל' וזהו ברוך שאמר מל' דא\"ס, וה\"ע עתיק לא\"ק, ברוך הוא כתר הפרטי, ואח\"כ בהשתל' ע\"ס עד המל', ולפי אופן האין הוא היש, ובהתבוננות זאת נעשה הקירוב לאלקות והוא החקיקה מבחוץ, ואח\"כ איך שבכל דבר יש חיות אלקי והעיקר הוא החיות, ומבשרי אחזה, ועי\"ז ירצה מאד בהגילוי אלקות, ובפרט מחמת ההסתר, ובכל דבר ירצה בהאלקות שבזה (ולפעמים יהי' מזה המרירות, אך זה צ\"ל קודם התפלה), וכאשר יתעצם בזה יגיע איך שהכל רק הארה וזהו ברוך שאמר אמירה א', וירצה להיכלל בעצמות, או המשכת העצמות ע\"י המצות, ולמעלה מזה ההתבוננות בהפלאת ורוממות אוא\"ס שמזה תהי' היראה, ויר\"ת מכחו ית' בהתהוות, ומההתבוננות איך שעצמות אוא\"ס הוא למטה כמו למעלה הוא יראה פנימית יותר.</span>\nקנא) <b>והנה</b> בכל אופני העבודה הנ\"ל שמההתבוננות נעשה התעוררות המדות כו', הרי מה שמאיר בהמדות א\"ז מעצמות המוחין כו' שהרי המוחין בעצם הם ההשגה שכלי' (דער פארשטאנד פון דעם ענין) ושיונח הענין היטב במוחו (עס זאל זעך גוט א(לייגין דער ענין), שלזה צריך לידע ההקדמות והענינים פרטים שבהם יבין את הענין האלקי כו', וצ\"ל הרגש האלקי בההתבוננות הן בתחלת ההתבוננות צ\"ל הנטי' והידיעה בכלל שזה ענין אלקי כו' (וע\"ד מ\"ש בסש\"ב בענין לימוד התו' שקודם הלימוד צריך להתבונן שזה חכמתו ורצונו ית', וכמו\"כ הוא בהתבוננות רק שכאן הוא בבחי' ידיעה בכלל, אבל צ\"ל נטיית ונתינת נפשו לזה כו'), ואח\"כ בעת ההתבוננות צריך שירגיש את האלקו' שבזה (לא רק השגה לבד כו') וכמ\"ש במ\"א, אבל מ\"מ ה\"ז השגה לידע ולהשיג את הענין היטב כו', דכל ענין ההשגה אינו מאיר בהמדה (רק בבחי' מקיף כמרחף מלמע' כו'). וכמו בההתבוננות בהאור וחיות אלקי שבעולמות הרי מה שמאיר בהמדה הוא רק שיש אור וחיות אלקי בכל נברא ושהעיקר הוא האלקו' כו', אבל הכרחיות הדבר שיש\nבהם חיות אלקי ושהחיות הוא האלקות ואיך שמבלעדו הי' אין ואפס כו', שזהו ההשגה שכלי' בזה כו' הרי כ\"ז אינו מאיר בהמדה כלל (רק בבחי' מקיף לבד כו'), ובאמת עיקר התעוררות המדה הוא מההרגש האלקי שנרגש בנפשו ע\"י ההתבוננות כו', כי הנה\"א יש בו בעצם הנטי' וההמשכה לאלקות (א צי צו אלקו'), וכשמרגיש אור אלקי ה\"ה נמשך באה' ורצוא כו', והמוחין הן שמביאים ומגלים את האור האלקי שיהי' בגילוי במדות כו'. וזהו הסבה מה שלפעמים גם שמתבונן בטוב ומ\"מ אינו מתפעל בלב שזהו מפני שלא יש ההרגש האלקי כו', והרי גם ההרגש האלקי אינו דומה כמו שהוא במוחין לכמו שהוא במדות כו', דלבד זאת שההשגה אינה מאירה בהמדות"],[3601330465,"כנ\"ל הנה גם ההרגש האלקי (שבאמת זהו עיקר חיות המדה ובמדות שבמוחין הוא שההרגש האלקי הוא בבחי' פנימי' דמשו\"ז הן בבחי' התעוררות והתפעלות אמיתי כו'), הרי במוחין הוא בבחי' גילוי ובמדות הוא בבחי' ריחוק ובבחי' מיעוט כו' (וי\"ל דמ\"ש בע\"ח דאוא\"ס מאיר בכתר וחכ' בקירוב מקום ובבינה בריחוק מקום ובז\"א דרך חלון כו', ומבו' בהדרוש שע\"ז המא' שהכוונה הוא על אור הא\"ס שמאיר בכו\"ח בקירוב ובבינה כו' (ובז\"א שבדרך חלון צ\"ל שהוא בבחי' ריחוק ג\"כ כו'), י\"ל דע\"ד החסידות הו\"ע ההרגש האלקי איך שבא ויורד ממדרי' למדרי' כו'), ולכן המדות הן בבחי' התפעלות ואם הי' ההרגש האלקי בהם בגילוי ממש לא היו בבחי' התפעלות, וכמו פנימי' הלב שאינו במורגש וע\"ה שזה ג\"כ בבחי' התפעלות מ\"מ אינו בהתפעלות מורגשת והמדות שבלב הן בהתפעלות מורגשת כו', וזהו מפני שההרגש האלקי הוא בהם בריחוק ובבחי' מיעוט כו'. וכן גם המדות שבשכל הן בבחי' התפעלות רק שזהו התפעלות שכלי כו' והיינו שהן ג\"כ בבחי' מציאות כו', וכמ\"ש במ\"א בענין וצפונך תמלא בטנם שהן המדות שבשכל\nואו' ע\"ז תמלא בטנם להיות שהן בבחי' מציאות וכמו הולד בבטן האם כו' שג\"ז הוא ירידה ממהות השכל כו', וכ\"ז הוא מפני שהמדות הן מהות נבדל מן המוחין ע\"כ גם גילוי המוחין שבהם הוא הארה נבדלת שאינו מעצמות ומהות המוחין כו' (ועי\"ז הן נמצאים בבחי' מהות נבדל עם היותם בבחי' עו\"ע כו'). וגם כללות בחי' המוחין שמהם נעשה התעוררות המדות א\"ז עצמות המוחין רק חיצוני' המוחין והן המוחין השייכים למדות כו', דזה שהשכל מחייב מדות הוא רק חיצוני' המוחין כו', דעצמות המוחין הוא בחי' שכלי לבד שלא יהי' מזה התעוררות המדות כו'. ומורגש זה במה שאנו רואים החילוק בין השגה להתבוננות דבהשגה מאיר אצלו השגת הענין לבד, ובהתבוננות נרגש אצלו המדה כו', והיינו לפי שהוא בחי' חיצוני' המוחין וה\"ז ירידה מעצם מהות המוחין כו', וכ\"ז הוא לפי שהמדות הן בבחי' מהות נבדל מן המוחין, ע\"כ כללות המוחין השייכים למדות הן בחי' חיצוני' המוחין ומה שמאיר מהמוחין אל המדות הוא רק הארה נבדלת ממהות המוחין כו'. והאופן הב' בעו\"ע הוא שהעלול הוא רק התפשטות העילה,\nויובן זה בהשפעת השכל מהמשפיע אל המקבל שמשפיע לו מהות שכל, דעם היות שזהו ג\"כ רק הארת המוחין דעצמות ומהות המוחין א\"א להשפיע כו' (והיינו דלבד שא\"א להשפיע מהות המוחין כמו בהולדה הרי ג\"כ מהות ההשכלה כמו שהוא אצלו א\"א להשפיע כו' וכמ\"ש במ\"א), מ\"מ הרי גם ההארה היא מהות שכל כו'. ומהו מהות העלול הנה לפעמים מבו' שזהו ההשפעה היינו השכל הנשפע שזהו ודאי רק התפשטות העילה לבד כו', ולפעמים מבו' ששכל המקבל הוא העלול, ומה ששכל המשפיע תופס תחלה את שכל המקבל ולפי אופן כזה משפיע לו כו' זהו התכללות העלול בהעילה כו', הרי כ\"ז הוא מהות שכל כו', וגם ירידת והמשכת השכל שמוריד אותו ומלבישו בכמה לבושים עד שיובן גם לתינוק שזהו בחי' האורך שבשכל כו', הרי כ\"ז הוא מהות השכל שנמשך ממדרי' למדרי' כו' (ואף שזהו למטה ממדרי' שכל השייך אל המדות מ\"מ במדרי' השכל ה\"ז למע' במדרי' כו' (שזה במדרי' מדבר שבשכל וזהו במדרי' חי כו'), וגם יכול להשפיע לו עצמות השכל כו'), וזהו בחי' עו\"ע שבשכל גופא שהעלול הוא כמהות העילה כו'. אמנם במוחין ומדות\n(דתכלית הכוונה הוא להוריד מהות האור גם במדות כו') הו\"ע שכל המטה כלפי חסד ושכל המטה כלפי דין שכ\"ז הוא מהות"],[3601330466,"שכל עדיין רק מה שהוא בבחי' הטי' והתגלות לחו\"ג ה\"ז בחי' מדות שבשכל כו' וכמשנת\"ל פקל\"ו שזהו בכלל בחי' פרצוף המוחין כו', ואפי' כשבא במדות דכשר פסול כו', הרי יש בזה ממהות אור השכל והוא הקיצור של האריכות והפלפול הקודם שזהו ג\"כ מהות שכל כו', וגם בהפסק דין יש בזה כל האריכות דהטעמים וסברות כו', דכ\"ז הוא מהות שכל כו'. ובעבודה הו\"ע פנימי' המדות שמאיר בהם אור המוחין בגילוי וה\"ה כמהות המוחין שאינם בבחי' הרגשה ובבחי' התפעלות כו', וכמ\"ש במ\"א (ובמ\"א מבו' שא\"ז עדיין בחי' הגדלות ממש וכמבו' בענין גחין רשב\"י ונשיק כו' ונז' ג\"כ לעיל), והעיקר הוא במדות שבחכ' שהן בבחי' דבקות כו', ועם היות שהמוחין בכלל הן בבחי' דבקות מ\"מ בפרטי' המדרי' הרי בינה הוא בבחי' התפעלות ומדות שבחכ' הן בבחי' אחדות ודבקות כו', וכן שכל המטה כלפי חסד או גבו' מבו' במ\"א שהן מדות שבחכ' כו', וכמו\"כ יובן למע' שזהו בחי' פנימי' המדות דאצי' כו', דהנה כתי' זכור רחמיך וחסדיך כי מעולם המה, דמדות שייכים אל העולמות כו', והיינו חיצוני' המדות כו', אבל פנימי' המדות אינם שייכים אל העולמות והן מדות עצמי' דאצי' כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ובכ\"ז הרי עצם השכל והכרחיות הדבר אינו מאיר בהמדה, רק היוצא מזה, והעיקר הוא ההרגש האלקי, שבמוחין הוא בגילוי ובמדות בריחוק ומיעוט, וי\"ל שזהו דאוא\"ס מאיר בכו\"ח בקירוב ובז\"א דרך חלון, ולכן המדות הן בהתפעלות וכ\"ז מפני שהן מהות נבדל ע\"כ גם השכל שבזה הוא רק הארה נבדלת, ובכללות רק חיצוניות המוחין, והאופן הב' בעו\"ע הוא שהעלול ממהות העילה, וכמו בהשפעת השכל דעם היותו הארה ה\"ז ממהות השכל, וכן שכל המקבל הוא מהות שכל, וכן במדות שבשכל שהן בבחי' הטיית עצם השכל, ובעבודה הוא פנימיות המדות שהן בבחי' דביקות, והעיקר הוא במדות שבחכ', ולמעלה הוא עצמיות המדות דז\"א שלמעלה מהעולמות.</span>\nקנב) <b>והענין</b> הוא דהנה החוקרים אומרים שלמעלה לא יש בחי' המדות כלל, דהרי המדות הן התפעלות שמתפעל בחסד וכה\"ג כו', ולמע' אינו שייך ענין ההתפעלות כו', וע\"כ או' שלמע' הוא רק פעולת החסד או פעולת הגבו' אבל עצם המדות דחו\"ג לא יש למע' כו'. והנה הנחה שלהם הוא אמת בצד א' ובצד א' אינו אמת, דזה אמת שלמע' המדות אינם בבחי' התפעלות כו', אבל מ\"ש שלא יש בחי' המדות למע' רק הפעולה כו' א\"ז אמת דיש מדות למע' מדת החסד ומדת הגבו' כו', ואדרבה הן תמיד בבחי' התגלות להתחסד ולהתרחם גם בעת שאינם פועלים פעולת החסד והרחמים כו', כי עצם המדות למע' אינם מצד התעוררות הזולת כ\"א מצד שלמות העצמות כו', וע\"כ הן תמיד בבחי' התגלות גם כשאינם פועלים פעולת החסד כו', ובחי' מדות העצמי' הן מצד בחי' החכ' שהם בבחי' אחדות כו', וזהו המבו' במ\"א דכשם שהוא וחכמתו א' כמו\"כ הוא ומדותיו א' דהעיקר הוא מצד המדות שבחכמה (שזהו עיקר האצי' מה שמבחי' החכ' דוקא כו' וכמ\"ש במ\"א וית' בסמוך), שהם בבחי' אחדות ממש כו'. וזהו ההפרש מה שהחכ' היא ראשית\nההשתל' ומה שבינה היא מקור ההשתל', דמה שבינה היא מקור ההשתל' הוא שהעו\"ע הוא באופן כזה להיות בבחי' מהות נבדל ומה שנמשך מן העילה אינו כמו"]]});
